SELECT 'moj-all-verified-judgments-review-002-chunk-066' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"2a0cbdd5-8e38-5cfc-abf0-764e102861d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد واملنع من السفر وأداء غرامة مالية ومصادرة اجلوال والغاء الشريحة املستخدمة.","document_number":"3432242","case_number":"3438038","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد واملنع من السفر وأداء غرامة مالية ومصادرة اجلوال والغاء الشريحة املستخدمة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3432242 :‬تاريخه‪1434/2/6 :‬هـ‬\n                         ‫رقم الدعوى‪3438038:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3460315‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬إقــرار املدعــى عليــه ‪ -‬عــدم وجــود‬\n      ‫ســوابق قضائيــة ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬تعزيــر بالســجن واجللــد‬\n      ‫واملنــع مــن الســفر وأداء غرامــة ماليــة ومصــادرة اجلــوال والغــاء‬\n                                                            ‫الشــريحة املســتخدمة‪.‬‬\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n          ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج احلشــيش املخــدر‪ ،‬مت‬\n      ‫القبــض علــى املدعــى عليــه وهــو يســلم املصــدر الســري مــادة احلشــيش‪،‬‬\n      ‫أقــر املدعــى عليــه بالترويــج‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫احتــواء املــادة املضبوطــة علــى احلشــيش املخــدر‪ ،‬وطلــب املدعــي العــام‬\n      ‫احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومنعــه مــن الســفر خــارج‬\n      ‫البــاد بعــد تنفيــذ العقوبــة عليهمــا مصــادرة جهــاز اجلــوال املســتخدم يف‬\n      ‫الترويــج ‪ ،‬وإلغــاء الشــريحة املســتخدمة يف الترويــج وذلــك الســتخدامها‬\n      ‫يف قضيــة الترويــج‪ ،‬إلزامــه بدفــع املبلــغ احلكومــي‪ ،‬حكمت احملكمة‬\n      ‫بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪ ،‬فقــررت احلكــم‬\n\n‫‪395‬‬\n\f‫علــى املدعــى عليــه بســجنه ســنة ونصــف مــن تاريــخ إيقافــه بســبب هــذه‬\n‫القضيــة‪ ،‬إلزامــه بدفــع غرامــة ماليــة قدرهــا ثالثــة آالف ري ــال‪ ،‬وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات بــن كل دفعــة خمســون جلــدة‬\n‫بــن كل دفعــة وأخــرى عشــرة أيــام‪ ،‬واملنــع مــن الســفر خــارج البــاد ملــدة‬\n‫ســنتني بعــد انتهــاء مــدة محكوميتــه‪ ،‬مصــادرة اجلــوال املســتخدم يف‬\n‫الترويــج وإلغــاء الشــريحة املســتخدمة يف الترويــج وذلــك الســتخدامهما‬\n‫يف قضيــة الترويــج‪ ،‬إلزامــه بدفــع املبلــغ احلكومــي وقــدره مائــة ري ــال‪،‬‬\n‫قــرر املدعــى عليــه عــدم قناعتــه باحلكــم‪ ،‬ومت تصديــق احلكــم مــن قبــل‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬لقاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بخميس مشيط برقم ‪..........‬وتاريخ ‪1434/01/21‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/21‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام وادعــى ‪..........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪)..........‬‬\n‫جهــة اإلصــدار ظهــران اجلنــوب املهنــة موظــف ‪ .....‬متهــم بالوســاطة يف‬\n‫ا يف دعــواه إنــه عنــد‬   ‫املؤثــرات العقليــة وال يوجــد عليــه ســوابق قائ ـ ً‬\n‫الســاعة الثامنــة مــن مســاء يــوم الســبت املوافــق ‪1433/12/25‬ه ـ ورد‬\n‫بــاغ مــن أحــد املصــادر الســرية مفــاده عــن قيــام املتهــم ‪..........‬بالتوســط‬\n‫يف ترويــج احلبــوب احملظــورة ويحمــل جــوال رقــم (‪ )..........‬فتــم االتصــال‬\n‫علــى جــوال مــن قبــل املصــدر ومت التفــاوض معــه علــى شــراء قطعــة مــن‬\n\n                                                                                       ‫‪396‬‬\n\f      ‫احلشــيش املخــدر مببلــغ (‪ )100‬مائــة ريــال فاســتعد بذلــك وطلــب مــن‬\n      ‫املصــدر مقابلتــه عنــد ‪ ....‬مقــر عملــه فقابلــه املصــدر مــع أحــد أفــراد‬\n      ‫الفرقــة وكان معهمــا املبلــغ املرقــم وركــب معهــم املتهــم واســتلم املبلــغ‬\n      ‫املرقــم مــن الفــرد وطلــب مــن الفــرد االجتــاه إلــى حــي ‪ .....‬ثــم نــزل املتهــم‬\n      ‫مــن الســيارة واختفــى عــن األنظــار وبعــد عشــر دقائــق عــاد املتهــم وســلم‬\n      ‫للفــرد قطعــة علــى شــكل أصبــع بلــغ وزنهــا (‪ )2.3‬اثنــان جــرام وثالثــة‬\n      ‫مــن العشــرة مــن اجلــرام ومت إعادتــه إلــى مقــر عملــه وعنــد وصولــه إلــى‬\n      ‫البنــك ومشــاهدته للفرقــة قــام بابتــاع شــيء مــا كان بيــده فقبــض‬\n      ‫عليــه وبتفتيشــه لــم يعثــر معــه علــى أي شــيء مــن املمنوعــات ووجــد معــه‬\n      ‫اجلــوال املســتخدم يف عمليــة الترويــج ولــم يعثــر علــى املبلــغ املرقــم فتــم‬\n      ‫التحفــظ عليــه وعلــى املضبوطــات وبســماع أقــوال املتهــم أقــر بأنــه قــام‬\n      ‫بالتوســط يف ترويــج قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )2.3‬اثنــان‬\n      ‫جــرام وثالثــة مــن العشــرة مــن اجلــرام وباســتجواب املتهــم بعــد إحاطتــه‬\n      ‫بالتهمــة املوجهــة لــه وبجهــة التحقيــق أقــر بــأن اجلــوال رقــم (‪ )..........‬عائــد‬\n      ‫لــه وأنكــر عالقتــه بالتوســط يف الترويــج وبتحليــل عينــة ممــا مت ضبطــه‬\n      ‫ثبــت احتوائهــا علــى مــادة احلشــيش املخــدر مبوجــب التقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )..........‬لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة عســير واحلشــيش مــن‬\n      ‫املــواد املدرجــة باجلــدول رقــم (‪ )4‬فئــة (أ‪،‬ج) وهــو مــن املــواد املخــدرة‬\n      ‫امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وملــا أشــير‬\n      ‫إليــه أقــر توجيــه االتهام‪..........‬بالتوســط يف ترويــج قطعــة مــن احلشــيش‬\n      ‫املخــدر بلــغ وزنهــا (‪ )2.3‬اثنــان جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n      ‫واملجــرم مبوجــب املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n\n\n‫‪397‬‬\n\f‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ /1 :‬أقوالــه املدونــة مبلــف التحقيــق ‪/2‬‬\n‫محضــر القبــض والتفتيــش ‪ /3‬التقريــر الكيميائــي وحيــث أن مــا‬\n‫أقــدم عليــه املذكــور فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بعقوبــة األصليــة‬\n‫والتكميليــة وقــد أقــدم عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا لــذا‬\n‫فإنه يتعني إحالته للمحكمة اجلزئية بخميس مشــيط اســتناد ًا للمادتني‬\n‫(‪ )126‬و (‪ )128‬مــن نظــام اإلجــراءات اجلزائيــة بطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه مبــا يلــي‪ /1 :‬عقوبــة تعزيريــة وفقـ ًا ملــا ورد يف املــادة‬\n‫(‪ )1/38‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليــه ‪ /2‬منعــه مــن الســفر‬\n‫خــارج اململكــة بعــد تنفيــذ العقوبــة وفقـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة‬\n‫األولى من النظام املشار إليه ‪ /3‬مصادر اجلوال ذى الرقم املصنعي رقم‬\n‫(‪ )..........‬وفقـ ًا ملــا ورد يف الفقــرة األولــى للمــادة (‪ )53‬مــن النظــام املشــار‬\n‫إليــه وإلغــاء الشــريحة الهاتفيــة رقــم (‪ )..........‬اســتناد ًا لتعميــم صاحــب‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم (‪ )9897‬وتاريــخ ‪1428/2/10-9‬ه ـ‬\n‫‪ /4‬إلــزام املتهــم بدفــع املبلــغ احلكومــي وقــدره (‪ )100‬مائــة ريال اســتناد ًا‬\n‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)65980/4/5/1‬‬\n‫وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي وبعرضهــا علــى املدعــى عليــه‬\n‫أجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن توســطي يف ترويــج قطعــة مــن‬\n‫احلشــيش املخــدر يبلــغ وزنهــا اثنــان جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n‫صحيــح وأنــا تائــب ونــادم هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى‬\n‫أقوالــه املدونــة يف دفتــر االســتدالل بتاريــخ ‪1434/12/25‬ه ــواملتضمن‬\n‫إقــرار املدعــى عليــه بالتوســط يف ترويــج قطعــة حشــيش هــذا وقــد جــرى‬\n\n\n                                                                                           ‫‪398‬‬\n\f      ‫االطــاع علــى محضــر القبــض والتفتيــش واملتضمــن أنــه مت تكليــف‬\n      ‫أحــد الفــرق القابضــة يف مكافحــة املخــدرات متابعــة املدعــى عليــه‬\n      ‫وجــرى االتصــال عليــه مــن قبــل املصــدر الســري علــى جوالــه وجــرى‬\n      ‫االتفــاق علــى شــراء قطعــة حشــيش مببلــغ مائــة ريــال وطلــب مــن املصــدر‬\n      ‫الســري مقابلتــه ‪ .......‬حيــث مقــر عملــه وركــب مــع املصــدر الســري‬\n      ‫واجتهــا إلــى حــي ‪..........‬وغــاب املدعــى عليــه عشــر دقائــق تقريبـ ًا ثــم عــاد‬\n      ‫وســلم للمصــدر قطعــة احلشــيش املتفــق عليــه وســلم املبلــغ املرقــم ثــم عــاد‬\n      ‫املصــدر وبرفقتــه املدعــى عليــه إلــى البنــك وبتفتيشــه لــم يعثــر علــى أي‬\n      ‫مخــدرات هــذا وقــد جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )..........‬واملتضمــن إيجابيــة العينــة املضبوطــة للحشــيش املخــدر‬\n      ‫ـاء علــى محضــر القبــض والتفتيــش والتقريــر الكيميائــي املشــار‬                ‫وبنـ ً‬\n      ‫إليهمــا أعــاه ونظــر ًا ألن املدعــى عليــه يســتحق عقوبــة طبق ـ ًا للقواعــد‬\n      ‫الشــرعية ووفقـ ًا للمادتــن (‪ )56( ، )38‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة ونظــر ًا لقلــة الكميــة التــي توســط بهــا وخللــو صحيفــة‬\n      ‫املدعــى عليــه مــن الســوابق وملقتضــى املــادة (‪ )60‬مــن النظــام املشــار‬\n      ‫ـدي إدانــة املدعــى عليــه بالتوســط‬     ‫إليــه ولــكل مــا تقــدم فقــد ثبــت لـ ّ‬\n      ‫ببيــع قطعــة حشــيش مخــدر بلــغ وزنهــا اثنــان جــرام وثالثــة مــن العشــرة‬\n      ‫مــن اجلــرام وحكمــت بتعزيــره لقــاء ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجن املدعــى‬\n      ‫ـاء علــى‬\n             ‫عليــه ملــدة ســنه ونصــف مــن تاريــخ إيقافــه بســبب هــذه القضيــة بنـ ً‬\n      ‫املادتــن (‪ )38،60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وإلزامــه بدفــع غرامــه ماليــه قدرهــا ثالثــة آالف ريــال وجلــده ثالثمائــة‬\n      ‫جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة كل دفعــه‬\n      ‫خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام‪ .‬ثاني ـاً‪ :‬منعــه مــن‬\n\n\n‫‪399‬‬\n\f‫الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء مــدة محكوميتــه‬\n‫ـاء علــى املــادة (‪ )56‬مــن النظــام املشــار إليــه‪ .‬ثالث ـاً‪ :‬مصــادرة اجلــوال‬ ‫بنـ ً‬\n‫ـاء علــى املــادة (‪ )53‬مــن النظــام املشــار‬  ‫ذو الرقــم املصنعــي (‪ )..........‬بنـ ً‬\n‫إليــه وإلغــاء الشــريحة الهاتفيــة رقــم (‪ )..........‬اســتناد ًا لتعميــم ســمو وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬بتاريــخ ‪1428/2/10-9‬ه ـ رابع ـاً‪ :‬إلزامــه بدفــع‬\n‫املبلــغ احلكومــي املرقــم وقــدره مائــة ريــال اســتناد ًا لبرقيــة ســمو وزيــر‬\n‫الداخليــة (‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ ومبــا تقــدم‬\n‫حكمــت وبإعــان احلكــم قــرر املدعــي العــام االعتــراض بــدون الئحــة‬\n‫اعتراضيــة وقــرر املدعــى عليــه القناعــة وأمــرت برفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وجــرى النطــق باحلكــم‬\n‫بتاريــخ ‪1434/2/5‬ه ـ الســاعة احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪..........‬وتاريــخ ‪1434/2/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة‬\n‫القاضــي باحملكمــة الشــيخ ‪....... /‬برقــم ‪ ..........‬وتاريخ‪1434/2/6‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ .......... /‬يف قضيــة (مخــدرات )‬\n‫علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                     ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                            ‫‪400‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":395,"source_page_end":400,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d3025bf0412de4dc256d194173a3476260c71ff8bf78d4a13eb99b73b31f0b57","normalized_text_hash":"77eeb6ecbbb0acac6d0519212a3fd89baa19c35f54f4412a3d2507bb1c6a6933","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p395-3432242"},{"id":"6d57f840-1462-5ff9-8064-db0c0e19aa26","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -االجتار يف احلبوب احملظورة -ترويج احلبوب احملظورة - تعاطي احلبوب احملظورة -ثبوت إدانة املدعى عليه -اعتراف املدعى عليه األول وإنكار املدعى عليه الثاني -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة املبلغ املضبوط واجلوال وإلغاء الشريحة املستخدمة يف اجلرمية -رد طلب املدعى العام مبعاقبة املدعى عليه الثاني -رد مصادرة السيارة .","document_number":"3425509","case_number":"3438064","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"مخدرات -االجتار يف احلبوب احملظورة -ترويج احلبوب احملظورة - تعاطي احلبوب احملظورة -ثبوت إدانة املدعى عليه -اعتراف املدعى عليه األول وإنكار املدعى عليه الثاني -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة املبلغ املضبوط واجلوال وإلغاء الشريحة املستخدمة يف اجلرمية -رد طلب املدعى العام مبعاقبة املدعى عليه الثاني -رد مصادرة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3425509 :‬تاريخه‪1434/01/28 :‬هـ‬\n                           ‫رقم الدعوى‪3438064:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3439176‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬االجتــار يف احلبــوب احملظــورة ‪ -‬ترويــج احلبــوب احملظــورة ‪-‬‬\n       ‫تعاطــي احلبــوب احملظــورة ‪ -‬ثبــوت إدانــة املدعى عليــه ‪ -‬اعتراف املدعى‬\n       ‫عليــه األول وإنــكار املدعــى عليــه الثانــي ‪ -‬تعزيــر بالســجن واجللــد‬\n       ‫والغرامــة واملنــع مــن الســفر ومصــادرة املبلــغ املضبــوط واجلــوال وإلغــاء‬\n       ‫الشــريحة املســتخدمة يف اجلرميــة ‪ -‬رد طلــب املدعــى العــام مبعاقبــة‬\n                                   ‫املدعــى عليــه الثانــي ‪ -‬رد مصــادرة الســيارة ‪.‬‬\n\n\n\n\n       ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n           ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n       ‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهما بترويج املخدرات احلشــيش‬\n       ‫املخدر ‪ ،‬مت القبض على املدعى عليهما بعد ترويجهما مادة احلشــيش‪،‬‬\n       ‫أقــر املدعــى عليــه بصفــة الترويــج‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n       ‫احتــواء املــادة املضبوطــة علــى احلشــيش‪ ،‬طلــب املدعــي العــام احلكــم‬\n       ‫ـاء علــى مــا ورد يف نصــوص نظــام مكافحــة‬      ‫علــى املدعــى عليهمــا ‪ -‬بنـ ً‬\n       ‫املخــدرات واملؤثــرات العقليــة‪ -‬بعقوبة تعزيرية ومنعهما من الســفر خارج‬\n       ‫البــاد بعــد تنفيــذ العقوبــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة وإلغــاء‬\n\n‫‪401‬‬\n\f‫الشــريحة ‪ ،‬ومصــادرة املبلــغ الــذي أفــاد بأنــه مــن نتــاج بيعــه للمخــدرات‪،‬‬\n‫ومصــادرة الســيارة العائــدة للمتهــم الثانــي املســتخدمة يف اجلرميــة ‪ ،‬إقرار‬\n‫املدعــى عليــه األول بالدعــوى وإنــكار املدعــى عليــه الثانــي ســوى إقــراره‬\n‫بالتعاطــي ووجــود قرائــن تدينــه منهــا إقــراره بالتعاطــي ومحضــر القبــض‬\n‫‪ ،‬حكمــت احملكمــة بثبــوت إدانــة املدعــى عليهمــا بترويــج وتعاطــي‬\n‫احلبــوب احملظــورة‪ ،‬فقــررت احملكمــة احلكــم علــى املدعــى عليــه األول‬\n‫بســجنه مــدة ســنة وســتة أشــهر تعزيــرا للقرائــن والتهــم تبــدأ مــن تاريــخ‬\n‫توقيفــه يف هــذه القضيــة ‪ ،‬وجلــده مائــة وخمســون جلــدة مفرقــة علــى‬\n‫دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــر أيــام‪ ،‬وإلزامــه بدفــع‬\n‫غرامــة ماليــة قدرهــا ألــف ري ــال خلزينــة الدولــة‪ ،‬ومنعــه مــن الســفر خلــارج‬\n‫البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه‪ ،‬ومصــادرة اجلــوال‬\n‫املســتخدم يف اجلرميــة وإلغــاء الشــريحة‪ ،‬ومصــادر املبلــغ وقــدره ألفــان‬\n‫وثالثمائــة وأربعــة عشــر ريــاال‪ ،‬وتعزيــر املدعــى عليهمــا باجللــد خمســن‬\n‫جلــدة دفعــة واحــدة لقــاء تعاطيهمــا املخــدرات‪ ،‬رد معاقبــة املدعــى عليــه‬\n‫الثانــي وكذلــك رد طلــب مصــادرة الســيارة‪ ،‬تعزيــر املدعــى عليــه‬\n‫الثانــي لقــاء توجــه التهمــة عليــه بترويــج احلبــوب احملظــورة بالتســليم‬\n‫وذلــك بســجنه ســتة أشــهر تبــدأ مــن تاريــخ توقيفــه يف القضيــة‪ ،‬قــررا‬\n‫املدعــى عليهمــا عــدم قناعتهمــا باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n\n                                                                                        ‫‪402‬‬\n\f      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ ‪1434/01/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/21‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1434/01/27‬ه ـ حضــر املدعــي العــام‪.......... /‬املشــار‬\n      ‫ا دعــواي هــي مــا ورد يف الئحــة‬    ‫إلــى تكليفــه يف الضبــط وادعــى قائ ـ ً‬\n      ‫الدعــوى العامــة املتضمنــة االدعــاء علــى كل مــن‪..........-1 /‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪............-2)..........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقم(‪)..........‬حيــث أنــه مت القبــض علــى‬\n      ‫املدعــى عليهمــا مــن قبــل مكافحــة املخــدرات بعــد قيامهمــا بترويــج‬\n      ‫املخــدرات وقــد انتهــى التحقيــق معهمــا إلــى توجيــه االتهــام للمدعــى‬\n      ‫عليهمــا بترويــج عــدد أربــع حبــات مــن احلبــوب املنبهــة احملظــورة األول‬\n      ‫عــن طريــق البيــع وتعاطيــه مــن املضبــوط والثانــي بالتســليم وتعاطيــه‬\n      ‫مــن الســابق للحبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬مــا‬\n      ‫ورد يف اعترافهمــا املــدون علــى اللفــة رقــم (‪ - 2)17‬مــا تضمنــه محضــر‬\n      ‫القبــض والشــراء املــدون علــى اللفــة لفــة رقــم(‪-3 )1‬التقريرالكيميائــي‬\n      ‫الشــرعي املرفــق بالرقم(‪)24‬وبالبحــث عــن ســوابقهما اتضــح عــدم‬\n      ‫وجــود ســوابق مســجله عليهمــا وحيــث أن مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫وهمــا بكامــل أهليتهمــا املعتبــرة شــرعا فعــل محــرم شــرع ًا ومعاقــب‬\n      ‫عليــه مبوجــب نظــام مكافحــة املخــدرات لــذا أطلــب إثبــات مــا أســند‬\n      ‫إليهمــا واحلكــم عليهمــا مبــا يلــي‪-1 :‬عقوبــة تعزيريــة وفق ـ ًا ملــا ورد يف‬\n      ‫املــادة (‪ )1/38‬الفقــرة األولــى بحدهــا األعلــى مــن النظــام املشــار إليــه‬\n      ‫بحدهــا األعلــى لقــاء مــا أســند إليهمــا ‪ -2‬منعهمــا مــن الســفر إلــى خــارج‬\n      ‫البــاد بعــد تنفيــذ العقوبــة وفقــا ملــا ورديف املــادة (‪)1/56‬مــن النظــام‬\n      ‫املشــار إليــه ‪ -3‬مصــادرة اجلــوال ذي الرقــم املصنعــي رقــم(‪)..........‬‬\n\n\n‫‪403‬‬\n\f‫وفقــا ملــا ورد يف املــادة الثالثــة واخلمســن مــن النظــام املشــار إليــه وعــدم‬\n‫صــرف الشــريحة رقم(‪)..........‬لنفــس املشــترك اســتنادا لتعميــم صاحــب‬\n‫الســمو امللكــي وزيــر الداخليــة رقم(‪)9895‬وتاريــخ ‪1428/02/1-9‬ه ـ‬\n‫‪ -4‬مصــادرة املبلــغ الــذي أفــاد بأنــه مــن نتــاج بيعــه للمخــدرات وقــدره‬\n‫ألفــان وثالثمائــة وأربعــة عشــر ريــاال ومصــادرة الســيارة مــن نــوع ‪..........‬‬\n‫موديل(‪)..........‬لوحــة رقــم(‪ )..........‬والعائــدة للمتهــم الثانــي املســتخدمة‬\n‫يف اجلرميــة اســتنادا للمــادة (‪ )1/53‬مــن ذات النظــام هــذه دعــواي ويف‬\n‫هــذه اجللســة حضــر املدعــى عليهمــا وبســؤالهما اإلجابــة علــى دعــوى‬\n‫املدعــي العــام أجــاب املدعــى عليــه األول بقولــه مــا نســب لــي يف دعــوى‬\n‫املدعــي العــام كلــه صحيــح حيــث قمــت بترويــج احلبــوب احملظــورة‬\n‫مقابــل مبلــغ مائــة وخمســون ريــا ًال واســتخدمت اجلــوال املشــار إليــه يف‬\n‫التنســيق يف هــذه العمليــة وقــد تعاطيــت احلبــوب احملظــورة واملدعــى عليــه‬\n‫الثانــي ال عالقــة لــه بهــذه القضيــة وأنــا تائــب إلــى اهلل وأتعهــد بعــدم‬\n‫ال وليــس لــي ســوابق هــذه إجابتــي وأجــاب املدعــى‬   ‫تكــرار ذلــك مســتقب ً‬\n‫عليــه الثانــي بقولــه مــا نســب لــي يف الدعــوى غيــر صحيــح والصحيــح‬\n‫أنــي كنــت أقــود ســيارتي مســجلة باســمي وهــي لوالــدي وكان املدعــى‬\n‫عليــه األول راكب ـ ًا معــي وطلــب منــي تســليم كيــس نايلــون لشــخص‬\n‫آخــر ال أعرفــه فســلمته لــه ولــم أكــن أعلــم بوجــود احلبــوب احملظــورة‬\n‫داخــل الكيــس وأنــا أتعاطــى احلبــوب احملظــورة يف الســابق وليــس‬\n‫لــي ســوابق مســجلة علــي هــذه إجابتــي وجــرى االطــاع علــى األدلــة‬\n‫والقرائــن املشــار إليهــا فوجــد مضمونهــا كمــا ذكــر ووجــد يف محضــر‬\n‫القبــض املــدون يف امللــف املرفــق باملعاملــة لفــة رقم(‪)1‬أنــه حــن القبــض‬\n‫علــى املدعــى عليهمــا ضبــط مــع املدعــى عليــه األول مبلــغ قــدره أربعــة‬\n\n\n                                                                                        ‫‪404‬‬\n\f      ‫آالف وثالثمائــة وأربعــة عشــر ريــا ًال مــن ضمنهــا املبلــغ احلكومــي كمــا‬\n      ‫وجــد يف إقــرار املدعــى عليــه األول حتقيق ـ ًا أن املبلــغ الــذي ضبــط معــه‬\n      ‫حصــل عليــه عــن طريــق اإلعانــة مــن برنامــج حافــز وأمــا بقيــة املبلــغ فهــو‬\n      ‫نتــاج بيعــه للمــواد املخــدرة ووجــد إقــرار املدعــى عليــه الثانــي حتقيق ـ ًا‬\n      ‫كمــا جــاء يف إجابتــه وجــرى ســؤال املدعــى عليــه األول عــن مصــدر‬\n      ‫ا ضبــط بحوزتــي مبلــغ قــدره‬        ‫املبلــغ الــذي ضبــط بحوزتــه فقــرر قائ ـ ً‬\n      ‫أربعــة آالف وثالثمائــة وأربعــة عشــر ريــا ًال ألفــان منهــا حصلــت عليهــا‬\n      ‫مــن برنامــج اإلعانــة حافــز والباقــي حصيلــة بيــع احلبــوب احملظــورة‬\n      ‫ـاء علــى‬ ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنـ ً‬  ‫هكــذا قــرر فبنـ ً‬\n      ‫مــا يلــي‪ -1:‬اعتــراف املدعــى عليــه األول مبــا نســب لــه يف الدعــوى‬\n      ‫واعترافــه باســتخدام اجلــوال وشــريحة االتصــال يف التنســيق لعمليــة‬\n      ‫الترويــج ‪ -2‬ترويــج املدعــى عليــه األول للحبــوب احملظــورة فعــل محــرم‬\n      ‫شــرع ًا ومجــرم نظام ـ ًا ومعاقــب عليــه مبــا ورد يف املادتــن(‪)56-38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات مــع إعمــال املــادة الســتني وذلــك لعــدم‬\n      ‫وجــود ســوابق مســجلة عليــه وملــا قــرره مــن التوبــة والتعهــد ‪-3‬اســتخدام‬\n      ‫املدعــى عليــه األول للجــوال وشــريحة االتصــال املشــار إليهــا يف الدعــوى‬\n      ‫العامــة يف التنســيق لعمليــة الترويــج موجبــة ملصادرتهــا وفق ـ ًا للمــادة‬\n      ‫(‪)53‬مــن النظــام املشــار إليــه ‪-4‬اعتــراف املدعــى عليــه األول بــأن جــزء‬\n      ‫مــن املبلــغ املضبــوط معــه وقــدره ألفــان وثالثمائــة وأربعــة عشــر ريــا ًال‬\n      ‫حصيلــة بيــع احلبــوب احملظــورة موجــب ملصادرتــه ‪ -5‬اعتــراف املدعــى‬\n      ‫عليهمــا بتعاطــي احلبــوب احملظــورة وفعلهمــا هــذا محــرم ومعاقــب عليــه‬\n      ‫بعقوبــة تعزيريــة ومعاقبــة الثانــي مبوجــب املــادة (‪)56‬مــن النظــام املشــار‬\n      ‫إليــه ‪-6‬إنــكار املدعــى عليــه الثانــي ملــا نســب لــه يف الدعــوى العامــة مــن‬\n\n\n‫‪405‬‬\n\f‫ترويجــه احلبــوب احملظــورة عــن طريــق التســليم ولــم يقــدم املدعــي العــام‬\n‫أدلــة كافيــة إلثبــات إدانتــه بذلــك إال أن مــا تضمنــه إقــراره حتقيق ـ ًا‬\n‫ومــا تضمنــه محضــر القبــض قرائــن تــورث تهمتــه بذلــك ويســتحق عليهــا‬\n‫عقوبــة تعزيريــة لــذا فقــد تقــرر مــا يلــي‪ :‬أو ًال ثبــت لــدي إدانــة املدعــى‬\n‫عليــه األول‪.......... /‬بترويــج عــدد أربــع حبــات مــن احلبــوب احملظــورة‬\n‫عــن طريــق البيــع وقــررت تعزيــره علــى ذلــك بســجنه مــدة ســنة وســتة‬\n‫أشــهر تبــدأ مــن تاريــخ توقيفــه يف هــذه القضيــة وجلــده مائــة وخمســن‬\n‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة وبينهمــا عشــرة‬\n‫أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا ألــف ريــال خلزينــة الدولــة ومنعــه‬\n‫مــن الســفر إلــى خــارج هــذه البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة‬\n‫ســجنه ثاني ـاً‪ :‬قــررت مصــادرة اجلــوال وشــريحة االتصــال املشــار إليهــا‬\n‫يف الئحــة الدعــوى كمــا قــررت مصــادرة املبلــغ املضبــوط مــع املدعــى‬\n‫عليــه األول وقــدره ألفــان وثالثمائــة وأربعــة عشــر ريــا ًال ثالثـاً‪ :‬ثبــت لــدي‬\n‫تعاطــي املدعــى عليهمــا للحبــوب احملظــورة وقــررت تعزيرهمــا علــى ذلــك‬\n‫بجلــد كل منهمــا خمســن جلــدة دفعــة واحــدة ومنــع املدعى عليــه الثاني‬\n‫مــن الســفر إلــى خــارج هــذه البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة‬\n‫ســجنه رابعـاً‪ :‬لــم يثبــت لــدي إدانــة املدعــى عليــه الثانــي‪.......... /‬بترويــج‬\n‫الكميــة املشــار إليهــا مــن احلبــوب احملظــورة عــن طريــق التســليم وقــررت‬\n‫رد طلــب املدعــي العــام معاقبــة املدعــى عليــه الثانــي مبوجــب املــادة(‪)38‬‬\n‫مــن النظــام املشــار إليــه كمــا قــررت رد طلــب املدعــي العــام مصــادرة‬\n‫الســيارة املشــار إليهــا العائــدة للمدعــى عليــه الثانــي خامس ـاً‪ :‬قــررت‬\n‫تعزيــر املدعــى عليــه الثانــي لقــاء توجــه التهمــة عليــه بترويــج احلبــوب‬\n‫احملظــورة عــن طريــق التســليم وذلــك بســجنه مــدة ســتة أشــهر تبــدأ مــن‬\n\n\n                                                                                         ‫‪406‬‬\n\f      ‫تاريــخ توقيفــه يف هــذه القضيــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n      ‫املدعــي العــام قــرر اعتراضــه عليــه وطلــب رفــع احلكــم إلــى محكمــة‬\n      ‫االســتئناف بــدون تقــدمي الئحــة اعتراضيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس‬\n      ‫مشــيط برقــم ‪..........‬وتاريــخ ‪1434 /02/04‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪..........‬برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/01/28‬ه ــاخلاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد كل‬\n      ‫مــن ‪ .......... /‬يف قضيــة ( مخــدرات ) علــى الصفــة املوضحــة يف القــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n                    ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪407‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":401,"source_page_end":407,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fbb97eeb64edf26d8e2776cb822b5bef72f411e27579bc358095e41b53ac87c4","normalized_text_hash":"8973d083fa03d266dc4c11e74ade2bdd886d9db0e4b35d7b2391df0f24a4aea1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p401-3425509"},{"id":"c63b7f55-3480-5482-b34b-6ae6fb7dba95","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة «امفيتامن» -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع","document_number":"3428687","case_number":"3438099","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة «امفيتامن» -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 3428687 :‬تاريخه‪1434/2/3 :‬هـ‬\n                    ‫رقم الدعوى‪3438099:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3451856‬تاريخه‪1434/3/1 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة «امفيتامــن» ‪ -‬ترويــج احلبــوب‬\n‫احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬عــدم‬\n‫وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع‬\n                                                                ‫مــن الســفر‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬واملــادة (‪ )60‬مــن‬\n                                 ‫نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج احلبــوب احملظــورة‬\n‫«االمفيتامــن»‪ -‬بقصــد الكســب املــادي‪ ،‬مت القبــض علــى املدعــى‬\n‫عليــه وبحوزتــه حبــوب االمفيتامــن‪ ،‬أقــر املدعــى عليــه بالترويــج‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫االمفيتامــن‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبــة‬\n‫تعزيريــة ‪ ،‬واملنــع مــن الســفر خــارج البــاد ‪ -‬حكمــت احملكمــة بثبــوت‬\n‫إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪ ،‬وقــررت احملكمــة‬\n‫احلكــم عليــه بســجنه ثــاث ســنوات مــن تاريــخ التوقيــف‪ ،‬وجلــده مائــة‬\n‫وخمســون جلــدة مفرقــة علــى ثــاث فتــرات متســاويات بــن كل فتــرة‬\n\n                                                                                       ‫‪408‬‬\n\f      ‫وأخــرى عشــر أيــام منهــا فتــرة علنــا يف مــكان عــام‪ ،‬وبعــد اجللــد الســابق‬\n      ‫بخمســة عشــر يومــا يجلــد املدعــى عليــه ســبعني جلــدة دفعــة واحــدة لقــاء‬\n      ‫تعاطــي احلبــوب احملظــورة‪ ،‬يدفــع غرامــة ماليــة قدرهــا ألــف وخمســمائة‬\n      ‫ري ــال يف خزينــة الدولــة العامــة‪ ،‬منعــه مــن الســفر خلــارج البــاد ملدة ثالث‬\n      ‫ســنوات‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم‬\n                                                   ‫مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ املقيــدة باحملكمة برقم ‪..........‬وتاريخ ‪1434/01/21‬‬\n      ‫ه ـ ففــي يــوم الســبت املوافــق‪ 1434/02/02‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪10 : 30‬وفيهــا حضــر املدعــي ‪ ، ..........‬املكلــف بخطــاب التكليف رقم‬\n      ‫‪ 51‬وتاريــخ ‪1430/5/8‬ه ـ ‪ ،‬وادعــى علــى احلاضــر يف مجلــس القضــاء‬\n      ‫‪ ،..........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ،..........‬يبلــغ‬\n      ‫مــن العمــر ‪ 31‬ســنة ‪ ،‬عاطــل عــن العمــل ‪ ،‬محصــن ‪ ،‬يقيــم بأحــد ‪، ..‬‬\n      ‫املقبــوض عليــه بتاريــخ ‪1433/12/28‬ه ـ ‪ ،‬أودع ســجن خميــس مشــيط‬\n      ‫بتاريخ ‪1434/1/3‬هـ ‪ ،‬قائال يف دعواه انتهى التحقيق مع املذكور إلى‬\n      ‫توجيــه االتهــام لــه بترويــج عــدد أربــع وعشــرين حبــة محظــورة عــن طريــق‬\n      ‫البيــع ‪ ،‬وتعاطيــه حلبــة واحــدة محظــورة مــن الســابق ‪ ،‬وبتحليــل عينــة‬\n      ‫ممــا مت ضبطــه ثبــت احتواءهــا علــى مــادة االمفيتامــن املنبهــة احملظــورة‬\n      ‫مبوجــب التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n\n‫‪409‬‬\n\f‫الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة عســير برقم‪..........‬لعــام‬\n‫‪1434‬ه ـ واملرفــق علــى اللفــة ‪ ،37‬وبالبحــث عــن ســوابقه اتضــح عــدم‬\n‫وجــود ســوابق مســجلة عليــه ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة وفقــا ملــا ورد يف املــادة ‪ 1/38‬مــن نظــام املخــدرات‬\n‫واملؤثــرات العقليــة لقــاء مــا نســب إليــه مــن الترويــج ‪ ،‬وإجــراء املقتضــى‬\n‫الشــرعي بحقــه لقــاء تعاطيــه للحبــوب احملظــورة ‪ ،‬ومنعــه مــن الســفر‬\n‫خــارج اململكــة بعــد تنفيــذ العقوبــة وفقــا ملــا ورد يف املــادة ‪ 1/56‬مــن‬\n‫ذات النظــام ‪ ،‬هكــذا ادعــى ‪ ،‬وبســؤال املدعــى عليــه قــال إن جميــع مــا‬\n‫ذكــره املدعــي العــام يف دعــواه صحيــح جملــة وتفصيــا حيــث روجــت‬\n‫عــدد أربــع وعشــرين حبــة محظــورة عــن طريــق البيــع علــى أحــد املصــادر‬\n‫الســرية ملكافحــة املخــدرات الــذي طلــب منــي أن أبيــع لــه عــدد خمــس‬\n‫وعشــرين حبــة محظــورة مببلــغ ثمامنائــة وخمســن ريــاال فبعــت عليــه أربــع‬\n‫وعشــرين حبــة باملبلــغ املذكــور وتعاطيــت حبــة منهــا قبــل القبــض علــي‬\n‫‪ ،‬وإنــي إذ اعتــرف بخطــأي فإنــي أعدكــم وعــدا جازمــا أال يتكــرر‬\n‫منــي مثــل ذلــك مــرة أخــرى إن شــاء اهلل تعالــى هكــذا أجــاب ‪ ،‬فنظــرا‬\n‫إلــى مــا ورد يف الدعــوى ‪ ،‬وإلــى إقــرار املدعــى عليــه مبــا نســب إليــه ‪،‬‬\n‫ومــا نســب إليــه مــن الترويــج موجــب لعقابــه مبــا دون احلــد األدنــى مــن‬\n‫عقوبــة الســجن الــواردة يف مــادة النظــام املشــار إليهــا يف الدعــوى ‪ ،‬نظــرا‬\n‫إلــى املــادة الســتني مــن ذات النظــام ‪ ،‬لعــدم وجــود ســوابق مســجلة علــى‬\n‫املدعــى عليــه وملــا أظهــره مــن اعتــراف باخلطــأ ووعــد بعــدم العــودة إليــه‬\n‫‪ ،‬ويعــزر مبــا دون حــد املســكر لقــاء تعاطيــه احلبــوب احملظــورة ألنهــا‬\n‫منبهــة وليســت مخــدرة ‪ ،‬وبنــاء علــى كل مــا تقــدم فقــد ثبــت لــدي ترويج‬\n‫املدعــى عليــه لعــدد أربــع وعشــرين حبــة محظــورة عــن طريــق البيــع ‪،‬‬\n\n\n                                                                                      ‫‪410‬‬\n\f      ‫ويســجن لقــاء ذلــك ثــاث ســنوات مــن تاريــخ التوقيــف ‪ ،‬ويجلــد مائــة‬\n      ‫وخمســن جلــدة علــى ثــاث فتــرات متســاويات بــن كل فتــرة وأخــرى‬\n      ‫عشــرة أيــام منهــا فتــرة واحــدة علنــا يف مــكان عــام ‪ ،‬ويدفــع غرامــة‬\n      ‫ماليــة قدرهــا ألــف وخمســمائة ريــال تــودع يف خزينــة الدولــة العامــة ‪،‬‬\n      ‫وبعــد اجللــد الســابق بخمســة عشــر يومــا يجلــد املذكــور ســبعني جلــدة‬\n      ‫دفعــة واحــدة لقــاء تعاطــي احلبــوب احملظــورة ‪ ،‬وبعــد تنفيــذ احلكــم‬\n      ‫عليــه مينــع مــن الســفر إلــى خــارج اململكــة ملــدة ثــاث ســنوات ‪ ،‬ومبــا‬\n      ‫تقــدم حكمــت ‪ ،‬وبعــرض احلكــم عليــه قــال إننــي مقتنــع بــه ‪ ،‬وقــال‬\n      ‫املدعــي العــام إننــي معتــرض علــى احلكــم واطلــب رفعــة إلــى محكمــة‬\n      ‫االســتئناف دون الئحــة اعتراضيــة ‪ ،‬وبــذا انتهــت يف الســاعة احلاديــة‬\n      ‫عشــرة والربــع ‪،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n      ‫‪.......‬وتاريــخ بــدون املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪ ........ /‬برقــم ‪.........‬وتاريــخ ‪1434/2/3‬ه ــاخلاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .......... /‬يف قضيــة (مخــدرات) علــى الصفــة‬\n      ‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                ‫وســلم‪.‬‬\n\n\n\n‫‪411‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":408,"source_page_end":411,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0619bdacc7de1aebb8b46b9a9a2f6bfb8a5ef6390e4dac9765c62395df0f8c43","normalized_text_hash":"0e98dbd8851b69a4d547e680d1ece7ab9329345a29cec7831d605ebf1b977192","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p408-3428687"},{"id":"f79d592a-951c-5751-9b92-19c88f2a89e6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -مقاومة قوات الشرطة -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد والغرامة املالية واإلبعاد خارج الباد ومبصادرة املبالغ املضبوطة واجلوال والشريحة املستخدمة","document_number":"34186346","case_number":"3438316","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -مقاومة قوات الشرطة -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد والغرامة املالية واإلبعاد خارج الباد ومبصادرة املبالغ املضبوطة واجلوال والشريحة املستخدمة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34186346 :‬تاريخه‪1434/4/13 :‬هـ‬\n                     ‫رقم الدعوى‪3438316 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34186346‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬مقاومــة قــوات الشــرطة ‪ -‬إقــرار‬\n‫املدعــى عليــه ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬ثبــوت إدانــة املدعــى‬\n‫عليــه ‪ -‬تعزيــر بالســجن واجللــد والغرامــة املاليــة واإلبعــاد خــارج‬\n‫البــاد ومبصــادرة املبالــغ املضبوطــة واجلــوال والشــريحة املســتخدمة‬\n                                                              ‫باجلرميــة‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n    ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهمــا بترويــج املخــدرات‬\n‫(احلشــيش)‪ ،‬مت القبــض علــى املدعــى عليهمــا بعــد تســليمهما املصــدر‬\n‫الســري مــادة احلشــيش ‪ ،‬أقــرا بالترويــج وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي احتــواء املــادة املضبوطــة علــى احلشــيش‪ ،‬وطلــب املدعــي‬\n‫ـاء علــى مــا ورد يف نصــوص نظــام‬\n                                  ‫العــام احلكــم علــى املدعــى عليهمــا بنـ ً‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة بالســجن واجللــد‪ ،‬والغرامــة‬\n‫ومصــادرة املبالــغ املضبوطــة معهمــا للترجيــح أنهــا مــن متحصــات‬\n‫الترويــج‪ ،‬ومصــادرة اجلــوال املضبــوط مــع األول الســتخدامه يف مــا‬\n\n                                                                                  ‫‪412‬‬\n\f      ‫نســب إليــه ‪ ،‬واإلبعــاد خــارج البــاد بعــد االنتهــاء مــن تنفيــذ عقوبتــه‬\n      ‫وعــدم الســماح لــه بالعــودة مــرة أخــرى ‪ ،‬احلكــم علــى الثانــي بعقوبــة‬\n      ‫تعزيريــة لقــاء مقاومتــه للفقــرة القابضــة ومحاولتــه للهــرب‪ ،‬حكمــت‬\n      ‫احملكمــة بثبــوت إدانــة املدعــى عليهمــا ببيــع احلشــيش املخــدر بقصــد‬\n      ‫االجتــار‪ ،‬وقــررت احملكمــة احلكــم علــى املدعــى عليهمــا بالســجن‬\n      ‫واجللــد والغرامــة ومصــادرة املبالــغ املضبوطــة معهما ومصــادرة اجلوال مع‬\n      ‫الشــريحة واإلبعــاد خــارج البــاد ‪ ،‬قــررا املدعــى عليهمــا عــدم قناعتهمــا‬\n          ‫باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ‪ .‬فلــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جــدة‪ /‬املســاعد برقــم ‪..........‬وتاريــخ‬\n      ‫‪ 1434/01/21‬هـ املقيدة باحملكمة برقم ‪ ..........‬وتاريخ ‪1434/01/20‬‬\n      ‫ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/03/03‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫ال‬\n       ‫‪09 : 45‬وفيهــا حضــر املدعــي العــام وقــدم الئحتــه مدعي ـ ًا علــى ك ً‬\n      ‫ـاء‬\n      ‫مــن ‪.......... .1 -:‬وتاريــخ ‪1433/10/1‬ه ـ ‪ .‬بتاريــخ ‪1433/9/26‬ه ـ وبنـ ً‬\n      ‫ملعلومــات وارده ملكافحــة املخــدرات مبحافظــة جــدة مــن الســجني‪/‬‬\n      ‫‪..........‬بوجــود شــخص حبشــي اجلنســية موجــود علــى هاتــف جــوال رقــم‬\n      ‫(‪ )..........‬يقــوم بترويــج احلشــيش املخــدر ‪ ،‬واســتعد بالشــراء منــه ‪،‬‬\n      ‫واتصــل الســجني علــى الهاتــف املشــار اليــه أعــاه وطلــب شــراء (‪ )6‬ســتة‬\n      ‫كيلــو مــن مــادة احلشــيش املخــدر ووافــق وطلــب تامــن املبلــغ وأفــاد بــان‬\n      ‫اجمالــي املبلــغ (‪ )67,200‬وأن قيمــة الكيلــو الواحــد (‪ )11200‬إحــدى‬\n\n‫‪413‬‬\n\f‫عشــر ألــف ومائتــان ريــال واحلضــور إليــه بشــارع ‪ . .....‬فتــم االنتقــال‪،‬‬\n‫وباملــكان والوقــت احملدديــن ورد اتصــال مــن املدعــى عليــه يفيــد بأنــه‬\n‫باملوقــع املتفــق عليــه ومت مالحظــة ســيارة مــن نــوع ‪ ...‬حتمــل لوحــة رقــم‬\n‫( ‪ )......‬بقيــادة األول الــذي نــزل منهــا واجتــه للمرافــق (املدعــى عليــه‬\n‫الثانــي ) وأخــذ منــه كيــس نايلــون كان يحملــه الثانــي بيــده وقــام األول‬\n‫بتســليم الكيــس للفــرد ممثــل دور املشــتري وضبــط بداخــل الكيــس‬\n‫(‪ )6‬ســتة بالطــات ســوداء اللــون مغلقــة مصنعيـ ًا بلــغ وزنهــا اإلجمالــي (‪)6‬‬\n‫ســتة كيلــو وهــي الكميــة املتفــق عليهــا ‪ .‬فتــم القبــض عليهمــا وضبــط‬\n‫الهاتــف اجلــوال املســتخدم يف التنســيق واحلامــل للرقــم املصنعــي (‪)..........‬‬\n‫بحــوزة املدعــى عليــه األول وضبــط معــه مبلــغ (‪ )1430‬ألــف وأربعمائــة‬\n‫وثالثــن ريــال وضبــط مــع الثانــي مبلــغ (‪ )445‬أربعمائــة وخمســة وأربعون‬\n‫ريــاالً‪ .‬وقــد حــاول الثانــي الهــرب وقــاوم الفرقــة القابضــة ‪ .‬وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪1433‬ه إيجابيــة‬\n‫العينــة مــن املــادة املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر‬\n‫واحتوائهــا علــى املــادة الفعالــة لــه واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ .‬وباســتجواب‬\n‫األول ‪ ،.......... /‬أعتــرف بأنــه اتفــق مــع شــخص طلــب منــه هاتفي ـ ًا (‪)6‬‬\n‫ســتة كيلــو مــن مــادة احلشــيش املخــدر وأن تقابــل معــه وســلمه الكميــة‬\n‫املتفــق عليهــا واملضبوطــة ‪،‬وان قــام بالتوســط بينــه وبــن املشــتري أحــد‬\n‫األشــخاص( مت فصــل أوراق للبحــث عــن املدعــو ‪ ........... /‬باســتجواب‬\n‫الثانــي ‪ ،.......... /‬أفــاد بأنــه كان يرافــق األول ليوصلــه ملنــزل صديقـ ًا له‬\n‫‪ .‬وانتهــى التحقيــق الــى توجيــه االتهــام لــأول‪.......... /‬والثانــي ‪.......... /‬‬\n‫ببيــع (‪ )6000‬ســتة آالف جــرام مــن مــادة احلشــيش املخــدر عــن طريــق‬\n\n\n                                                                                        ‫‪414‬‬\n\f                           ‫البيــع بقصــد االجتــار وذلــك لألدلــة والقرائــن األتيــة‪-:‬‬\n      ‫‪ .1‬مــا ورد يف اعتــراف األول املــدون بدفتــر التحقيــق صفحــة رقــم ( ‪)5-1‬‬\n                                                                          ‫املرفق لفــة (‪).....‬‬\n         ‫‪.2‬ما ورد مبحضر الضبط صفحة رقم ( ‪ ) 13-12‬املرفق لفة رقم ‪.....‬‬\n                   ‫‪.3‬ما ورد بالتقرير الكيميائي املنوه عنه املرفق لفة ( ‪. ) ......‬‬\n      ‫وبالبحث عن ســوابقه لم يعثر له على ســوابق مســجلة عليه ‪ .‬وحيث إن‬\n      ‫مــا أقدمــا عليــه املذكوريــن وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا مــن‬\n      ‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليهمــا‬\n                           ‫ومعاقبتهمــا بالعقوبــات األصليــة والتكميليــة التاليــة‪-:‬‬\n      ‫‪.1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إليهمــا اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n                                                                              ‫املشــار إليــه ‪.‬‬\n      ‫‪ .2‬مصــادرة املبلــغ (‪ )1430‬ألــف وأربعمائــة وثالثــن ريــال املضبوطــة مــع‬\n      ‫األول ومصــادرة مبلــغ (‪ )445‬أربعمائــة وخمســة وأربعــون ريــا ًال املضبوطة‬\n      ‫مــع الثانــي للترجيــح أنهــا مــن مســتحصالت الترويــج و مصــادرة اجلــوال‬\n      ‫املضبــوط مــع األول والــذي يحمــل الرقــم املصنعــي رقــم (‪ )..........‬وذلــك‬\n      ‫الســتخدامه يف مــا نســب إليــه اســتناد ًا للفقرتــن (‪ )2 ،1‬مــن املــادة (‪)53‬‬\n                                           ‫مــن نظــام مكافحــة املخــدرات املشــار إليــه‬\n      ‫‪ .3‬إبعادهمــا خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا وعــدم‬\n      ‫الســماح لهمــا بالعــودة إليهــا وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام‬\n      ‫املخــدرات املشــار إليــه ‪ .‬كمــا أطلــب احلكــم علــى الثانــي لقــاء مقاومتــه‬\n\n\n‫‪415‬‬\n\f‫للفرقــة القابضــة ومحاولتــه الهــرب ‪ .‬هــذه دعــواي وأســألهما اجلــواب ‪.‬‬\n‫وبســؤال املدعــى عليهمــا اللذيــن يجيــدان التحــدث باللغــة العربيــة عــن‬\n‫الدعــوى اجابــا بقولهمــا امنــا ورد يف دعــوى املدعــي العــام علينــا هــو‬\n‫صحيــح حيــث قمنــا ببيــع ســتة االف جــرام مــن مــادة احلشــيش املخــدر‬\n‫عــن طريــق البيــع بقصــد االجتــار واضــاف املدعــى عليــه االول ‪..........‬‬\n‫ان املبلــغ املضبــوط معــي وهــو الــف واربعمائــة وثالثــن ريــال يعــود لــي‬\n‫اكتســبته مــن عمليــة الترويــج وان الهاتــف اجلــوال مــع شــريحته يعــود‬\n‫لــي والــذي اســتخدمته يف عمليــة الترويــج واضــاف املدعــى عليــه الثانــي‬\n‫‪.......... /‬قائــا ان املبلــغ املضبــوط معــي وهــو اربعمائــة وخمســة واربعــون‬\n‫ريــاال يعــود لــي اكتســبته مــن الترويــج وبالرجوع الــى اوراق املعاملة وجد‬\n‫التقريــر الكيميائــي املذكــور رقمــه ومصــدره اعــاه املتضمــن ايجابيــة‬\n‫العينــة ملــادة احلشــيش املخــدر كمــا لــم جنــد للمدعــى عليهمــا ســوابق‬\n‫مســجلة عليــه وحيــث احلــال مــا ذكــر مــن دعــوى العــام ضــد املذكــور‬\n‫ينفــي مــا ذكــر اعــاه ويطلــب مجازاتهمــا مــن ســجن وجلــد وغرامــة‬\n‫ومصــادرة املبالــغ املاليــة والهاتــف اجلــوال مــع شــريحته وابعادهمــا خــارج‬\n‫اململكــة وحيــث اجــاب املدعــى عليهمــا بصحــة هــذه الدعــوى مــن حيــث‬\n‫الترويــج بقصــد الكســب املــادي وان املبالــغ املضبوطــة معهمــا تعود لهما‬\n‫اكتســباها مــن عمليــة الترويــج وان الهاتــف اجلــوال يعــود للمدعــى عليــه‬\n‫االول ‪.......... /‬فبعــد االطــاع والتأمــل ولكــون االعتــراف ســيد االدلــة‬\n‫فقــد ثبــت لــدي ادانــة املدعــى عليهمــا ‪.......... /‬املذكــور و‪ .....‬املذكــور‬\n‫ببيــع ســته االف جــرام مــن مــادة احلشــيش املخــدر بقصــد االجتــار وان‬\n‫املبالــغ املضبوطــة معهمــا تعــودان لهمــا اكتســباها مــن عمليــة التريــج‬\n‫وان الهاتــف اجلــوال مــع شــريحته يعــود للمدعــى عليــه االول ‪.......... /‬‬\n\n\n                                                                                     ‫‪416‬‬\n\f      ‫والــذي اســتخدمه يف عمليــة الترويــج وحكمــت اوال ‪ :‬بتعزيــر املدعــى‬\n      ‫عليهمــا ‪.......... /‬و‪ ..........‬بالســجن مــدة قدرهــا اثنــا عشــر عامــا من تاريخ‬\n      ‫دخولهمــا الســجن وجلــد كل واحــد منهمــا الــف جلــدة علــى عشــرين‬\n      ‫دفعــة كل دفعــة خمســون جلــدة بــن الدفعــة والتــي خمســة عشــر يومــا‬\n      ‫وغرامــة ماليــة قدرهــا عشــرون الــف ريــال علــى كل واحــد منهمــا‬\n      ‫اســتنادا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات لقــاء بيعهمــا ســتة‬\n      ‫االف جــرام مــن مــادة احلشــيش املخــدر بقصــد الكســب املــادي ثانيــا ‪:‬‬\n      ‫مصــادرة املبالــغ املاليــة املضبوطــة مــع املدعــى عليهمــا وايداعهــا بيــت‬\n      ‫املــال ومصــادرة الهاتــف اجلــوال مــع شــريحته والغائهــا ومنــع صرفهــا مــرة‬\n      ‫اخــرى لســوء اســتخدامها اســتنادا للمــادة (‪ )53‬مــن نفــس النظــام ثالثــا‬\n      ‫‪ :‬ابعــاد املدعــى عليــه الــى خــارج اململكــة بعــد انتهــاء محكوميتهمــا‬\n      ‫اســتنادا للمــادة (‪ )56‬مــن نفــس النظــام املشــار اليــه وبعرضــه عليهمــا‬\n      ‫قــرر املدعــى عليهمــا عــدم القناعــة وال يرغبــان تقــدمي الئحــة اعتراضيــة‬\n      ‫بذلــك ولــم يبــد املدعــي العــام اعتراضــا ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/03‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n      ‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة املســاعد‬\n      ‫رقــم(‪ )..........‬وتاريــخ (‪1434/4/23‬هــ) املرفــق بهــا القــرار رقــم(‪)..........‬‬\n      ‫وتاريــخ (‪1434/4/13‬هـ)الصــادر مــن فضيلــة الشــيخ‪........../‬القاضي‬\n      ‫باحملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪/‬‬\n      ‫‪ ..........‬ورفيقــه املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪، ،‬‬\n\n\n‫‪417‬‬\n\f‫وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n    ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                              ‫‪418‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":412,"source_page_end":418,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b5764b6858e5614920acbfd975ad12cc763367e4f6218a3f091546daf2ed5064","normalized_text_hash":"f0dd5eaa75b28d5f25bf9e6cc93beb2f6dc3aa6dca20cefee0f096e30579f17d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p412-34186346"},{"id":"0cb4ccb8-9705-5eff-a3ab-4f7b360af4d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والغاء الشريحة املستخدمة يف","document_number":"3435641","case_number":"3441372","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/11","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والغاء الشريحة املستخدمة يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3435641 :‬تاريخه‪1434/2/11 :‬هـ‬\n                          ‫رقم الدعوى‪3441372:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3435641‬تاريخه‪1434/2/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت‬\n      ‫إدانــة املدعــى عليــه ‪ -‬تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n      ‫واملنــع مــن الســفر ومبصــادرة اجلــوال والغــاء الشــريحة املســتخدمة يف‬\n                                                                       ‫اجلرميــة‪.‬‬\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪)53‬‬\n      ‫والفقــرة (‪ )1‬مــن املــادة (‪ )56‬املــادة (‪ )60‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن‬\n                                   ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات « حبــوب‬\n      ‫الكبتاجــون احملظــورة »‪ ،‬مت القبــض علــى املدعــى عليــه وبحوزتــه‬\n      ‫املبلــغ املرقــم‪ ،‬أقــر املدعــى عليــه بالترويــج‪ ،‬أثبــت التقريــر الكيميائــي‬\n      ‫الشــرعي احتــواء املــادة املضبوطــة علــى الكبتاجــون‪ ،‬طلــب املدعــي‬\n      ‫العــام احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة و منعــه مــن الســفر‬\n      ‫خــارج البــاد بعــد تنفيــذ العقوبــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n      ‫وإلغــاء الشــريحة وعــدم صرفهــا لنفــس املســتخدم‪ .‬حكمــت احملكمــة‬\n      ‫بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة عــن طريــق البيــع‪،‬‬\n\n‫‪419‬‬\n\f‫فقــررت احملكمــة احلكــم علــى املدعــى عليــه بتعزيــره بالســجن ملــدة‬\n‫ســنة ونصــف مــن تاريــخ إيقافــه‪ ،‬وجلــده ثالثمائــة جلــدة مفرقــة علــى‬\n‫ســت دفعــات كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة‬\n‫أيــام‪ ،‬تغرميــه ثالثــة آالف ري ــال لقــاء تروجيــه خلمــس حبــات عــن طريــق‬\n‫البيــع‪ ،‬منعــه مــن الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة‬\n‫محكوميتــه‪ ،‬ومصــادرة اجلــوال املســتخدم يف ترويــج املخــدرات وإلغــاء‬\n‫الشــريحة املســجلة باســمه وعــدم صرفهــا لــه مــرة أخــرى‪ ،‬قــرر املدعــى‬\n‫عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ ‪1434/01/24‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/24‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/02/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام وادعــى علــى ‪..........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪)..........‬‬\n‫جهــة اإلصــدار أحــوال تبــوك املهنــة ‪ ......‬متهــم يف بيــع املؤثــرات العقليــة‬\n‫ا يف دعــواه ‪ :‬إنــه يف يــوم األحــد املوافــق‬   ‫وال يوجــد عليــه ســوابق قائ ـ ً‬\n‫‪1433/12/26‬ه ـ ورد بــاغ مــن أحــد املصــادر بقيــام ‪ .....‬بترويــج احلبــوب‬\n‫املنبهــة احملظــورة ويحمــل جــوال رقــم (‪ )..........‬ذو الرقــم املصنعــي‬\n‫(‪ )..........‬فتــم االتصــال علــى جوالــه مــن قبــل املصــدر والتفــاوض معــه‬\n‫علــى شــراء خمــس حبــات مــن الكبتاجــون مببلــغ وقــدره (‪ )200‬ريــال‬\n                                                                                          ‫‪420‬‬\n\f      ‫وكانــت املكاملــة علــى مســمع مــن فرقــة مكافحــة املخــدرات بخميــس‬\n      ‫مشــيط ومت تكليــف أحــد أفــراد الفرقــة مبرافقــة املصــدر بعــد إعطائــه‬\n      ‫املبلــغ املرقــم ملقابلــة املصــدر والشــراء منــه ومتــت عمليــة الشــراء واســتالم‬\n      ‫خمــس حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون املخــدر مــن قبــل‬\n      ‫الفــرد وأعطيــت اإلشــارة ملتابعتــه ومتــت متابعتــه والقبــض عليــه وبتفتيشــه‬\n      ‫عثــر معــه علــى املبلــغ املرقــم ولــم يعثــر معــه أو يف ســيارته علــى أي شــيء‬\n      ‫مــن املمنوعــات وهــي مــن نــوع ‪ .....‬وقــد مت مخاطبــة املخــدرات بخطابنــا‬\n      ‫رقــم (‪ )..........‬وتاريــخ ‪1433/12/28‬ه ـ بتســليمها إلــى صاحبهــا فتــم‬\n      ‫التحفــظ عليــه ومــا مت ضبطــه معــه وبســماع أقــوال املتهــم أقــر بأنــه قــام‬\n      ‫بترويــج خمــس حبــات مــن احلبــوب املنبهــة احملظــورة عــن طريــق البيــع‬\n      ‫وأنــه يقــوم بترويــج احلبــوب احملظــورة مــن الســابق وباســتجواب املتهــم‬\n      ‫أقــر بأنــه قــام بشــراء عشــر حبــات مــن احلبــوب املنبهــة احملظــورة وقــد‬\n      ‫اســتخدم منهــا خمــس حبــات وقــام ببيــع خمــس حبــات وأنــه يتعاطــى‬\n      ‫احلبــوب املنبهــة يف الســابق وأن اجلــوال املســتخدم يف عمليــة الترويــج رقــم‬\n      ‫(‪ )..........‬عائــد لــه وجهــاز ‪ ....‬وبتحليــل مــا مت ضبطــه ثبــت احتوائهــا علــى‬\n      ‫مــادة اإلمفيتامــن احملظــورة مبوجــب التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )..........‬لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الطبيــة الشــرعية مبنطقــة عســير واإلمفيتامــن مــن‬\n      ‫املدرجــة باجلــدول الثانــي فئــة (ب) وهــو مــن املــواد املخــدرة امللحقــة بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وملــا أشــير إليــه أقــر توجيــه‬\n      ‫االتهــام‪ ..........‬بترويــج خمــس حبــات مــن احلبــوب املنبهــة احملظــورة عــن‬\n      ‫طريــق البيــع وترويجهــا يف الســابق وتعاطيــه مــن املضبــوط ويف الســابق‬\n      ‫واملجــرم مبوجــب املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n\n\n‫‪421‬‬\n\f‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ /1 :‬إقــرار املتهــم ‪ /2‬أقــوال املتهــم ‪/3‬‬\n‫محضــر القبــض والتفتيــش ‪ /4‬التقريــر الكيميائــي وحيــث إن مــا‬\n‫أقــدم عليــه املذكــور فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد أقــدم عليــه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا لــذا أطلــب إثبــات مــا أســند إليــه‬\n                                                          ‫واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪ /1‬عقوبــة تعزيريــة وفق ـ ًا ملــا ورد يف املــادة (‪ )1/38‬مــن النظــام املشــار‬\n‫إليــه لقــاء مــا أســند إليــه وإعمــال املــادة (‪ )62‬بتطبيــق العقوبــة األشــد‬\n‫بحــق املتهــم لقــاء ترويجــه للحبــوب احملظــورة عــن طريــق البيــع ويف‬\n‫الســابق وتعاطيــه مــن املضبــوط يف الســابق ‪ /2‬منعــه مــن الســفر خــارج‬\n‫اململكــة بعــد تنفيــذ العقوبــة وفقـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة األولــى‬\n‫مــن النظــام املشــار إليــه ‪ /3‬مصــادرة اجلــوال ذي الرقــم املصنعــي (‪)..........‬‬\n‫وفق ـ ًا ملــا ورد يف املــادة (‪ )53‬مــن النظــام املشــار إليــه وإلغــاء الشــريحة‬\n‫الهاتفيــة رقــم (‪ )..........‬اســتنادا لتعميــم صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذه دعــواي وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكــره املدعــي‬\n‫العــام مــن ترويجــي خمــس حبــات محظــورة عــن طريــق البيــع صحيــح‬\n‫وأنــا تائــب ونــادم هكــذا أجاب‪.‬هــذا وقــد جــرى االطــاع علــى محضــر‬\n‫القبــض والتفتيــش بتاريــخ ‪1433/12/26‬ه ـ واملتضمــن إنــه بنــاء علــى‬\n‫مــا وردنــا مــن أحــد املصــادر الســرية بــأن هنــاك شــخص يدعــى ‪......‬‬\n‫ويعمــل ‪ .....‬يقــوم بترويــج احلبــوب احملظــورة وقــد قــام املصــدر باالتصــال‬\n‫علــى املــروج ومت االتفــاق علــى شــراء خمــس حبــات محظــورة مــن نــوع‬\n\n\n                                                                                         ‫‪422‬‬\n\f      ‫كبتاجــون مببلــغ مائتــي ريــال وكانــت املكاملــة مبســمع مــن الفرقــة‬\n      ‫القابضــة ومت تكليــف أحــد األفــراد مبرافقــة املصــدر الســري ملقابلــة‬\n      ‫املــروج والشــراء منــه وقــد متــت املقابلــة ومت الشــراء منــه يف حــي ‪..........‬‬\n      ‫وبعدهــا مت القبــض علــى املدعــو ‪..........‬وبتفتيشــه شــخصيا عثــر علــى‬\n      ‫املبلــغ املرقــم ومســلم لــه مــن قبــل املصــدر الســري ولــم يعثــر معــه علــى‬\n      ‫أي ممنوعــات هــذا وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n      ‫برقــم ‪..........‬لعــام ‪1433‬ه ـ واملتضمــن ايجابيــة العينــة املضبوطــة ملــادة‬\n      ‫اإلمفيتامــن احملظــورة‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث صــادق املدعــى عليــه علــى صحــة دعــوى املدعــي العــام وبنــاء‬\n      ‫علــى محضــر القبــض والتفتيــش والتقريــر الكيميائــي املشــار إليهمــا‬\n      ‫أعــاه ونظــرا ألن املدعــى عليــه يســتحق عقوبــة طبقــا للقواعــد الشــرعية‬\n      ‫ووفقــا للمادتــن ‪ 56،38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ونظــرا خللــو صحيفــة املدعــى عليــه مــن الســوابق ونظــرا لصغــر‬\n      ‫ســنه وملــا قــرره مــن التوبــة والنــدم وملقتضــى املــادة ‪ 60‬مــن النظــام املشــار‬\n      ‫إليــه ولكلمــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه خلمــس‬\n      ‫حبــات محظــورة مــن نــوع كبتاجــون لقصــد الترويــج عــن طريــق البيــع‬\n      ‫وحكمــت عليــه مبــا يلــي‪ :‬أوال ســجنه ســنة ونصــف مــن تاريــخ إيقافــه‬\n      ‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســن‬\n      ‫جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وتغرميــه ثالثــة األف ريــال لقــاء‬\n      ‫تروجيــه خلمــس حبــات عــن طريــق البيــع بنــاء علــى املادتــن ‪ 60،38‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬ثانيــا‪ :‬منعــه مــن الســفر‬\n      ‫خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة محكوميتــه بنــاء علــى‬\n      ‫املــادة ‪56‬مــن النظــام املشــار إليــه أعاله‪.‬ثالثــا‪ :‬مصــادر اجلــوال ذو الرقــم‬\n\n\n‫‪423‬‬\n\f‫املصنعي(‪ )..........‬بناء على املادة ‪ 53‬من النظام املشار إليه أعاله وإلغاء‬\n‫الشــريحة الهاتفيــة رقــم ‪..........‬بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقم‬\n‫‪9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ومبــا تقــدم حكمــت وبإعــان احلكــم‬\n‫قــرر املدعــي العــام االعتــراض بــدون الئحــة اعتراضيــة وقــرر املدعــى‬\n‫عليــه القناعــة وجــرى النطــق باحلكــم بتاريــخ ‪1434/2/11‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط املكلف‬\n‫الشــيخ ‪.......... /‬برقــم ‪ 34201834‬وتاريــخ ‪1434/2/12‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيل ــته برقــم ‪..........‬وتاريــخ ‪1434/2/11‬ه ــاخلاص‬\n‫بدعــوى املدعــي العــام ضـ ــد ‪.......... /‬يف قضيــة ( مخــدرات ) علــى الصفة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                              ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪424‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":419,"source_page_end":424,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83ba0cd3c9274a90e4050b78fad6b27bdcec0b1660909854d45fbe127a3dd9f4","normalized_text_hash":"f29d9db0aa166387756d061bfa36f08520cdfe90a33103392abdf47d737f2011","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p419-3435641"},{"id":"9b980d73-377a-5283-8024-bba3a8c5c383","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -الوساطة يف ترويج الهيروين املخدر -الشروع يف ترويج الهيروين املخدر -التعزير للتهمة -التعزير بالسجن واجللد","document_number":"3457461","case_number":"3441813","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/08","year":"1434","subject":"مخدرات -الوساطة يف ترويج الهيروين املخدر -الشروع يف ترويج الهيروين املخدر -التعزير للتهمة -التعزير بالسجن واجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3457461 :‬تاريخه ‪1434/03/08 :‬هـ‬\n                           ‫رقم الدعوى ‪3441813:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34218757‬تاريخه‪1434/5/21 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬الوســاطة يف ترويــج الهيرويــن املخــدر ‪ -‬الشــروع يف ترويــج‬\n       ‫الهيرويــن املخــدر ‪ -‬التعزيــر للتهمــة ‪ -‬التعزيــر بالســجن واجللــد‬\n                                                                       ‫واإلبعــاد ‪.‬‬\n\n\n\n\n       ‫‪ -1‬تعميم معالي وزير العدل رقم ‪/13‬ت‪ 3406 /‬وتاريخ ‪1429/06/17‬هـ‪.‬‬\n                                  ‫‪ -2‬املادة (‪ )6/2‬من نظام وثايق السفر ‪.‬‬\n                              ‫‪ -3‬املادة (‪ )49‬من النظام األساسي للحكم ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بالتوســط يف ترويــج الهيرويــن‬\n       ‫املخــدر والشــروع يف بيــع نصــف كيلــو مــن الهيرويــن املخــدر ‪ ،‬حيــث‬\n       ‫وردت معلومــات وجــود شــخص يقــوم بالتوســط والداللــة علــى الهرويــن‬\n       ‫املخــدر بكميــات كبيــرة جــد ًا ويعمــل ســائق أجــرة وأن معــه أشــخاص‬\n       ‫آخريــن وهــم عصابــة ومت متكــن املصــدر مــن االتصــال علــى املدعــى‬\n       ‫عليــه واالتفــاق علــى شــراء نصــف كيلــو مــن الهرويــن وكانــت املكاملــة‬\n       ‫علــى مســمع مــن رجــال الضبــط ‪ ،‬مت إعــداد اخلطــة الالزمــة وتزويــد‬\n       ‫املصــدر باملبلــغ املرقــم وتكليــف أحــد األفــراد مبرافقتــه ليقــوم بتمثيــل‬\n       ‫دور املشــتري مت تســليم املبلــغ للمدعــى عليــه ودخــل املدعــى عليــه داخــل‬\n\n‫‪425‬‬\n\f‫الســوق إلحضــار الكميــة فتــم القبــض عليــه خوفـ ًا مــن هروبــه وضيــاع‬\n‫املبلــغ احلكومــي وعثــر مــع املدعــى عليــه علــى املبلــغ احلكومــي املرقــم‬\n‫وأقــر أمــام الفرقــة القابضــة بالتوســط يف شــراء الهرويــن وطلــب املدعــى‬\n‫العــام إثبــات مــا أســند للمدعــى عليــه وأنكــر املدعــى عليــه ما نســب إليه‬\n‫ممــا حــرا باملدعــي العــام إلحضــار شــاهدين مــن مكافحــة املخــدرات‬\n‫ورصــدت الشــهادة وأنكــر املدعــى عليــه مــا جــاء يف الشــهادة ‪،‬بنــاء‬\n‫علــى ماســبق حكمــت احملكمــة علــى املدعــى عليــه وبتعزيــره بالســجن‬\n‫واجللــد واإلبعــاد‪ ،‬رد طلــب املدعــي العــام يف املطالبــة بالغرامــة و مصــادرة‬\n      ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬     ‫اجلــوال وإلغــاء شــريحته ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 3441813‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34204121‬وتاريــخ ‪1434/01/24‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة الســاعة ‪15:11‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ...‬و حضــر حلضوره الســجني ‪ ...‬بنجالديشــي‬\n‫مبوجــب اإلقامــة رقــم (‪ )...‬بقولــه باالطــاع علــى محضر البــاغ والضبط‬\n‫والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات‬\n‫تبــن أنــه يف يــوم اجلمعــة املوافــق ‪1433/12/17‬ه ـ ورود معلومــات مــن‬\n‫مكتــب االتصــال يف دولــة ‪ ......‬الشــقيقة مفادهــا وجــود شــخص‬\n‫بنجالديشــي اجلنســية يقــوم بالتوســط والداللــة علــى الهرويــن املخــدر‬\n‫بكميات كبيرة جدا ويعمل ســائق تاكســي يف اخلبر ويقوم بالتوســط‬\n\n                                                                                     ‫‪426‬‬\n\f      ‫يف بيــع الهيرويــن املخــدر علــى ســيارته التاكســي ويدعــى‪... /‬‬\n      ‫البنجالديشــي أفــاد املصــدر بأنــه يحمــل رقــم جــوال (‪ )...‬وذكــر املصــدر‬\n      ‫أنهــم عصابــة مكونــه مــن الشــخص البنجالديشــي وأشــخاص مــن‬\n      ‫اجلنســية الباكســتانية وذكــر أنهــم حذريــن جــدا يف التعامــل وبنــاء علــى‬\n      ‫مــا ذكــر مت متكــن املصــدر مــن االتصــال علــى املدعــو‪ ... /‬علــى هاتفــه‬\n      ‫رقــم (‪ )...‬بعــد التحيــة والســام ذكــر املصــدر أنــه بالقــرب مــن جســر‬\n      ‫البحريــن وســأله املصــدر عــن توفــر النصــف كيلــو مــن الهيروين وجاوب‬\n      ‫قائــا موجــود بســعر ســتون ألــف ريــال وقــال البنجالديشــي تعــال إلــى‬\n      ‫مجمــع ‪ ...‬عنــد بوابــة ثمانيــة وانتهــت املكاملــة وكانــت علــى مســمع مــن‬\n      ‫رجــال الضبــط اجلنائــي باملكافحــة ومــن ثــم مت التوجــه إلــى مجمــع ‪...‬‬\n      ‫وعنــد الوصــول إليــه نــزل املصــدر وأحــد رجــال املكافحــة ليقــوم بتمثيــل‬\n      ‫دور املشــتري مــع املصــدر ويكــون شــاهدا علــى عمليــة االســتالم‬\n      ‫والتســليم ومت تســليم املصــدر املبلــغ احلكومــي املرقــم وبعــد حوالــي‬\n      ‫عشــر دقائــق اتصــل البنجالديشــي املدعــو‪ ... /‬علــى املصــدر وقــال أنــه يف‬\n      ‫الشــارع العــام فذهبــوا أمــا أنظــار الفرقــة باجتــاه املدعــو‪ ... /‬الــذي كان‬\n      ‫يركــب ســيارة تاكســي مــن نــوع ‪ ....‬بيضــاء اللــون وركبــوا معــه‬\n      ‫واجتهــوا باجتــاه إحــدى الشــوارع القريبــة مــن مجمــع ‪ ...‬ومــن خــال‬\n      ‫متابعــة الفرقــة القابضــة لــه اتضــح لهــم حــذره الشــديد وجــرى التفــاوض‬\n      ‫معــه علــى احلصــول علــى عينــة مــن الهرويــن املخــدر لتجربتــه ومــن ثــم‬\n      ‫تســليمه املبلــغ احلكومــي املرقــم واســتالم النصــف كيلــو مــن الهيرويــن‬\n      ‫املخــدر إال أنــه رفــض ذلــك وأصــر أن يتــم إعطائــه املبلــغ وقــدره ســتون‬\n      ‫ألفــا ثــم يذهــب مترجــا إلــى مجمــع ‪ ...‬حيــث ذكــر للمصــدر ومرافقــه‬\n      ‫أن هنــاك بداخــل املجمــع ‪ ...‬شــخص باكســتاني ســوف يحضــر لــه املبلــغ‬\n\n\n‫‪427‬‬\n\f‫ويســتلم منــه النصــف الكيلــو وهــو يحملــه بداخــل شــنطة وقــال أبقــوا يف‬\n‫الســيارة وأنــا ســوف أخــذ املبلــغ وأذهــب ملقابلــة الشــخص الباكســتاني‬\n‫يف خــال عشــر دقائــق ولكــن رفــض املصــدر ومرافقــه ذلــك إال بعــد‬\n‫مشــاهدة العينــة مــن الهيرويــن وبعــد ذلــك جــرى التفــاوض ملــدة ســاعتني‬\n‫مــع املصــدر ومرافقــه إال أن املدعــو‪ ...‬كان مصــر ًا علــى اســتالم املبلــغ‬\n‫بنفســه والذهــاب بــه وحــده ورفــض املصــدر ومرافقــه ذلــك ثــم أنــزل‬\n‫صاحــب التاكســي املدعــو ( ‪ ) ...‬املصــدر ومرافقــه مــن الســيارة لعــدم‬\n‫توصلهــم إلــى اتفــاق بذلــك وبعــد حوالــي ســاعة عــاود االتصــال املدعــو‪/‬‬\n‫‪ ...‬علــى املصــدر ومرافقــه وقــال لهــم لكــم عشــرة دقائــق ســوف نتقابــل‬\n‫يف مواقــف مجمــع ‪ ...‬عنــد بوابــة رقــم ( ‪ ) 1‬ســوف أخــذ املبلــغ وأنــزل‬\n‫لوحــدي لكــي أحضــر الكميــة املتفــق عليهــا مــن الهرويــن املخــدر‬\n‫فوافــق املصــدر ومرافقــه علــى ذلــك ومت التوجــه بالفرقــة علــى مجمــع ‪...‬‬\n‫عنــد البوابــة املتفــق عليهــا ومت توزيــع األفــراد بشــكل دقيــق وبعــد حوالي‬\n‫ربــع ســاعة وصــل املدعــو‪ ... /‬وقابــل املصــدر ومرافقــه وأخــذ منهــم املبلــغ‬\n‫احلكومــي املرقــم وقــدره ســتون ألــف ريــال ثــم ذكــر لهــم ســوف يحضــر‬\n‫الكميــة مــن داخــل املجمــع يف غضــون عشــر دقائــق وبعــد توجــه هــو‬\n‫لوحــده إلــى املجمــع وهــو حتــت أنظــار الفرقــة ودخــل إلــى بوابــة رقــم ( ‪1‬‬\n‫)ومــن ثــم أجتــه إلــى بوابــة رقــم( ‪ ) 2‬وأجتــه باجتــاه إحــدى ســائقي األجــرة‬\n‫وقــال ألحدهــم ممكــن توصلنــي وعنــد محاولــة ركوبــه مت القبــض‬\n‫عليــه مــن قبــل الفرقــة خوفــا مــن هروبــه وضيــاع املبلــغ احلكومــي املرقــم‬\n‫ومت العثــور علــى املبلــغ احلكومــي املرقــم يف جيبــه األميــن كامــا‬\n‫ومبناقشــته أعتــرف وأقــر أنــه تلقــى اتصــال أفــاد فيــه أن الباكســتاني‬\n‫الــذي يســلم لــه كميــة الهيرويــن طلــب منــه الركــوب يف أحــد ســيارات‬\n\n\n                                                                                       ‫‪428‬‬\n\f      ‫األجــرة ومبناقشــته كذلــك أقــر أنــه يقــوم بالتوســط يف شــراء الهرويــن‬\n      ‫املخــدر قبــل ذلــك عــدة مــرات وأنــه يتقاضــى مائــة ريــال علــى كل‬\n      ‫كبســولة مــن الهرويــن املخــدر وباســتجواب املدعــى عليــه أقــر بأنــه قــام‬\n      ‫باســتقبال املدعــو ‪(... /‬بحرينــي اجلنســية) أربــع مــرات وقــام باصطحابــه‬\n      ‫إلــى شــارع ‪ ......‬باخلبــر للداللــة علــى الهيرويــن املخــدر ويف كل مــرة‬\n      ‫يعطيــه البحرينــي مائــة ريــال ويقــوم بإرســال بطاقــة شــحن للباكســتاني‬\n      ‫مببلــغ (‪ )300‬ريــال وأنــه يقــوم باالتصــال علــى الباكســتاني ليرشــده‬\n      ‫علــى مــكان تواجــد الهيرويــن حيــث يقــوم برميــه علــى شــارع ‪ .......‬باخلبر‬\n      ‫بســوق ‪ ....‬ولــم يقابــل الباكســتاني وإمنــا معرفــه معــه عــن طريــق التلفــون‬\n      ‫ويقــوم بالتنســيق معــه علــى هاتفــه رقــم (‪ )...‬ويدعــى ( ‪ ) ...‬ويف يــوم‬\n      ‫القبــض عليــه اتصــل علــى الشــخص الباكســتاني وطلــب منــه نصــف‬\n      ‫كيلــو مــن الهيرويــن املخــدر واخبــره الباكســتاني بــأن قيمــة النصــف‬\n      ‫كيلــو هــي (‪)60‬ألــف ريــال وأخبــر الشــخص البحرينــي بذلــك وأســتلم‬\n      ‫املبلــغ املذكــور وقــام باالتفــاق مــع الشــخص املــروج الباكســتاني وطلــب‬\n      ‫منــه الباكســتاني املقابلــة يف مجمــع ‪ ...‬مــول ودخــل ومعــه املبلــغ ثــم‬\n      ‫اتصــل املــروج الباكســتاني وقــال لــه تعــال عنــد البوابــة رقــم (‪ )2‬وخــرج‬\n      ‫عنــد البوابــة ومت القبــض عليــه وانتهــى التحقيــق إلــى توجيــه االتهــام‪...‬‬\n      ‫بالتوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر والشــروع يف بيــع‬\n      ‫نصــف كيلــو مــن الهيرويــن املخــدر ‪.‬وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫وأقــرار املدعــى عليــه واملرفــق علــى اللفــات رقــم (‪-2. )12.11.2‬‬\n      ‫محضــرا البــاغ والقبــض والتفتيــش املشــار إليه واملــدون على الصفحات‬\n      ‫رقــم (‪ )2‬و(‪ )12.11‬مــن ملــف ضبــط إجــراءات االســتدالل ‪ .‬وبالبحــث‬\n      ‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائية مســجلة وحيث‬\n\n\n‫‪429‬‬\n\f‫إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرعاً‪-‬‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا ونظام ـ ًا فإننــي أطلــب إثبــات إدانتــه‬\n‫مبــا أســند إليــه وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n‫مكافحــة املخــدرات‪ ،‬واحلكــم عليــه مبــا يلــي ‪ -1:‬بعقوبــة الســجن‬\n‫واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن‬\n‫النظــام مــع مراعــاة املــادة (‪ )62/1‬مــن النظــام مــع تشــديد العقوبــة عليــه‬\n‫وفقــا للمــادة (‪/2/38‬ج) مــن النظــام واســتنادا لتعميــم ســمو وزيــر‬\n‫الداخلية رقم ( ‪2/8346/4/5/1‬ش ) وتاريخ ‪1427/2/8‬هـ ‪ -2.‬إبعاده‬\n‫عــن البــاد إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫النظــام ثانيــا ‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه و الــذي‬\n‫مــن نــوع نوكيــا و يحمــل الرقم املصنعي رقــم (‪)35166305765845/2‬‬\n‫ورقــم االتصــال (‪ )...‬الســتخدامه يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعــواي وبطلبــي‬\n‫مــن املدعــى عليــه اجلــواب أجــاب بواســطة مترجــم احملكمــة ‪ ...‬قائــا مــا‬\n‫ذكــره املدعــي العــام غيــر صحيــح والصحيــح أنــي قابلــت شــخص مــن‬\n‫اجلنســية البحرينيــة وركــب معــي واجتهــت معــه إلــى محــل ‪ ...‬بكورنيش‬\n‫اخلبــر وتوقفــت قليــا وكان يتحــدث بهاتفــه النقــال والنــي اعــرف‬\n‫العربيــة فهمــت انــه يتكلــم عــن شــراء هيرويــن مخــدر مببلــغ ســتني ألــف‬\n‫ريــال ثــم طلــب منــي االجتــاه إلــى مجمــع ‪ ...‬مــول بالدمــام فتوجهــت ثــم‬\n‫توقفــت قليــا ثــم طلــب منــي التوجــه إلــى البــرج ‪ ...‬علــى طريــق الدمــام‬\n‫اخلبــر الســريع وهنالــك قابلنــا شــخصني مــن اجلنســية البحرينيــة وحصــل‬\n\n\n                                                                                     ‫‪430‬‬\n\f      ‫بينهمــا خــاف ومشــادة وكان بيــد الشــخص الراكــب معــي علبــة‬\n      ‫بالســتيك بهــا مبلــغ ســتني ألــف ريــال وبعــد مشــادة بينــه وبــن زمالئــه قــام‬\n      ‫برمــي العلبــة التــي حتــوي املبلــغ بداخل الســيارة فقمــت باخذها وخرجت‬\n      ‫مــن الســيارة لرمــي املبلــغ وهنــا مت القبــض علــي مــن قبــل رجــال االمــن‬\n      ‫هكــذا أجــاب ورفعــت اجللســة الحضــار بينــة املدعــي العــام وهــم أعضــاء‬\n      ‫محضــر القبــض مــن افــراد مكافحــة املخــدرات بالدمــام ويف جلســة‬\n      ‫اخــرى حضــر املدعــي العــام وحضــر للشــهادة عضــو الفرقــة القابضــة ‪...‬‬\n      ‫ســجله ‪ ...‬وبســؤاله عمــا لديــه شــهد قائــا وردنــا إخباريــة عــن وجــود‬\n      ‫شــخص يقــوم بترويــج الهرويــن املخــدر بكميــات كبيــرة ويعمــل ســائق‬\n      ‫تاكســي فجــرى التنســيق واالعــداد لالطاحــة بــه فجــرى متكني املصدر‬\n      ‫مــن االتصــال بــه فاتفــق معــه علــى كميــة محــددة مببلــغ ســتني ألــف ريــال‬\n      ‫فتواعدنــا عنــد ‪ ...‬مــول عنــد البوابــه رقــم (‪ )8‬وملــا وصلنــا للموقــغ اتصلنــا‬\n      ‫بــه فقــال ســوف اصــل بعــد عشــر دقائــق ثــم بعــد عشــر دقائــق وصــل علــى‬\n      ‫ســيارة تاكســي والتقينــا معــه وركبنــا معــه يف الســيارة وتفاوضنــا معــه‬\n      ‫علــى ان تشــتري منــه كميــة حشــيش مخــدر فقــال البــد ان اخــذ مبلــغ‬\n      ‫الســتني ألــف ريــال ثــم ادخــل الســوق واحضــر كميــة الهيرويــن بعــد‬\n      ‫خمــس دقائــق فرفضنــا تســليمه املبلــغ اال بتســليم الهيرويــن فحاولنــا‬\n      ‫اقناعــه بقصــد االيقــاع بــه فطلبنــا منــه عينــة حتــى تعــرف جــودة الهيروين‬\n      ‫فرفضــت ذلــك اال باســتالم املبلــغ كامــل فقلنــا لــه نعطيــك جــزء مــن‬\n      ‫املبلــغ قــدره خمســة االف ريــال امــا كامــل املبلــغ فــا فرفــض فلــم نتفــق‬\n      ‫فافترقنــا بعدهــا بعشــر دقائــق اتصلنــا عليــه مــره ثانيــة وطلبنــا ان نلتقــي‬\n      ‫معــه وذلــك للتفــاوض مــرة اخــرى فاتفقنــا علــى االلتقــاء عنــد مجمــع ‪...‬‬\n      ‫يف املــكان احملــدد قابلنــاه وحاولنــا التفــاوض معــه ثــم ســلمناه كامــل‬\n\n\n‫‪431‬‬\n\f‫املبلــغ وقــدره ســتون ألــف ريــال ثــم قــال ســوف ادخــل الســوق واســتلم‬\n‫كميــة الهيرويــن وارجــع اليكــم مــرة ثانيــة ثــم دخــل الســوق وهنــا انتهــى‬\n‫دوري فاشــهد هلل تعالــى بالتفــاوض مــع املدعــى عليــه علــى شــراء هيروين‬\n‫مخــدر مببلــغ ســتني ألــف ريــال واســتالمه للمبلــغ هــذا مالــدي واشــهد بــه‬\n‫هــذا وحضــر للشــهادة وادائهــا ‪ ...‬ســجله ‪ ...‬وبســؤاله عمــا لديــه قــال‬\n‫اشــهد هلل تعالــى أنــي كنــت مــن ضمــن الفرقــة القابضــة وشــاهدت‬\n‫املدعــى عليــه يدخــل إلــى مجمــع ‪ ....‬مــن بوابــة بعــد ان تــرك الشــاهد‬\n‫األول يف ســيارته ويخــرج مــن بوابــة اخــرى وركــب ســيارة اجــرة فقمــت‬\n‫بالقبــض عليــه وبحيازتــه مبلــغ الســتني ألــف ريــال احلكومــي املرقــم هــذا‬\n‫مالــدي وبــه اشــهد وحضــر للشــهادة ‪ ...‬ســجله ‪ ...‬و‪...‬سجله‪....‬وبســؤالهما‬\n‫عمــا لديهمــا شــهد كل واحــد منهمــا منفــردا بعدالــة وثقــة الشــاهدين‬\n‫وعليــه جــرى التوقيــع ويف جلســة اخــرى حضــر املدعــي العــام ‪ ....‬و‬\n‫حضــر حلضــوره الســجني ‪ ...‬بنجالديشــي هــذا وبطلبــي مــن املدعــي العــام‬\n‫زيــادة بينــة قــال ليــس لــدي ســوى مــا يف أوراق املعاملــة هــذا وبتــاوة‬\n‫شــهادة الشــاهدين قــرر املدعــى عليــه قائــا بواســطة املترجــم املتعــاون‬\n‫‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬و الــذي يقــوم‬\n‫بالترجمــة مــن اللغــة العربيــة إلــى اللغــة األرديــة و بالعكــس قائــا مــا‬\n‫ذكــره الشــاهد ‪ ...‬غيــر صحيــح جملــة و تفصيــا و الصحيــح هــو جوابي‬\n‫يف اجللســة الســابقة أمــا مــا شــهد بــه الشــاهد ‪ ...‬فالصحيــح منــه أنــه مت‬\n‫القبــض علــي و معــي املبلــغ احلكومــي املرقــم ألن الشــخص البحرينــي‬\n‫ألقــاه بســيارتي بداخــل علبــة فقمــت بأخذهــا وخرجــت مــن الســيارة‬\n‫لرمــي املبلــغ وهنــا مت القبــض و غيــر صحيــح أنــي دخلــت للســوق مــن‬\n‫بوابــة ثــم خرجــت مــن بوابــة أخــرى و ركبــت ســيارة ملوزيــن بــل مت القبض‬\n\n\n                                                                                    ‫‪432‬‬\n\f      ‫علــي مبجــرد خروجــي مــن ســيارة اللموزيــن التــي أقودهــا و غيــر صحيــح‬\n      ‫أنــي قمــت بالتوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر و وغيــر‬\n      ‫صحيــح أيضــا أنــي قمــت بالشــروع يف بيــع نصــف كيلــو مــن الهيرويــن‬\n      ‫املخــدر أمــا الشــهود فــا أعرفهــم وال أقــول فيهــم شــيئا هكــذا أجــاب‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث أنكــر املدعــى عليــه‬\n      ‫التوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر والشــروع يف بيــع‬\n      ‫نصــف كيلــو مــن الهيرويــن املخــدر و حيــث أقــر بالقبــض عليــه وبيــده‬\n      ‫علبــه حتتــوي علــى مبلــغ ســتني ألــف ريــال و هــو املبلــغ احلكومــي املرقــم‬\n      ‫و حيــث أنــه دفــع أنــه كان يقصــد مــن ذلــك رمــي املبلــغ و حيــث أن هــذا‬\n      ‫الدفــع ينــايف شــهادة الشــاهدين حيــث شــهد الشــاهد األول ‪ ...‬بتســليمه‬\n      ‫كامــل املبلــغ وقــدره ســتون ألــف ريــال و شــهد الشــاهد الثانــي بالقبــض‬\n      ‫عليــه وبحيازتــه مبلــغ الســتني ألــف ريــال احلكومــي املرقــم و حيــث شــهد‬\n      ‫الشــاهد األول بالتفــاوض مــع املدعــى عليــه علــى بيــع هرويــن مببلــغ‬\n      ‫ســتني ألــف ريــال و حيــث ليــس للمدعــي العــام زيــادة بينــة لــذا فإنــه لــم‬\n      ‫يثبــت لــدي إدانــة املدعــى عليــه ‪ ...‬بالتوســط أربــع مــرات يف ترويــج‬\n      ‫الهيرويــن املخــدر والشــروع يف بيــع نصــف كيلــو مــن الهيرويــن املخــدر‬\n      ‫لعــدم كفايــة األدلــة و عــدم اكتمــال نصــاب الشــهادة و تتوجــه عليــه‬\n      ‫التهمــة يف الشــروع يف ترويــج الهرويــن املخــدر و اســتالم الثمــن وقــدره‬\n      ‫ســتون ألــف ريــال و ذلــك لشــهادة الشــاهد الواحــد يف التفــاوض مــع‬\n      ‫املدعــى عليــه يف بيــع هرويــن مخــدر مببلــغ ســتني ألــف ريــال و شــهادة‬\n      ‫شــاهد ثــانٍ يف القبــض علــى املدعــى عليــه و بحيازتــه مبلــغ الســتني ألــف‬\n      ‫ريــال و حكمــت عليــه باآلتــي ‪ ]1[ :‬تعزيــره علــى التهمــة يف الشــروع يف‬\n      ‫ترويــج الهرويــن املخــدر مــع مراعــاة التشــديد عليــه يف العقوبــة ملــا ورد يف‬\n\n\n‫‪433‬‬\n\f‫شــهادة الشــاهد مــن شــدة حــذره و رفضــه تســليم املخــدر إال بعــد اســتالم‬\n‫املبلــغ و لكبــر املبلــغ املقبــوض بحيازتــه و الــذي ســيؤدي بالتالــي إلــى‬\n‫كبــر كميــة الهرويــن املشــروع يف ترويجهــا ممــا يلــزم معــه التشــديد‬\n‫عليــه يف العقوبــة صيانــة للعبــاد والبــاد مــن شــر املفســدين يف األرض‬\n‫بنشــر هــذه اآلفــات التــي تضــر بديــن النــاس و دنياهــم وذلــك بســجنه‬\n‫أربــع ســنوات تبــدأ اعتبــارا مــن تاريــخ ســجنه و جلــده ثالثمائــة جلــدة‬\n‫مفرقــة علــى ســتة دفعــات متســاويات بــن كل دفعــة و األخــرى أســبوع‬\n‫[‪ ]2‬رد مطالبــة املدعــي العــام بتطبيــق عقوبــة الســجن واجللــد والغرامــة‬\n‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام لعــدم ثبــوت‬\n‫الترويــج [‪ ]3‬رد مطالبــة املدعــي العــام بإعمــال مقتضــى الفقــرة رقــم (‪)2‬‬\n‫مــن املــادة رقــم (‪ )56‬مــن النظــام لعــدم ثبــوت الترويــج [‪ ]4‬رد مطالبــة‬\n‫املدعــي العــام مبصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه ورد‬\n‫املطالبــة بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس املدعــى‬\n‫عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n‫‪1429/2/10-9‬هـ لعدم ثبوت الترويج [‪ ]5‬و حيث أن للقاضي احلكم‬\n‫باإلبعــاد و املصــادرة ولــو لــم تثبــت اإلدانــة وذلــك بنــاء على قواعــد التعزير‬\n‫العامــة حيــث نــص تعميــم معالــي وزيــر العــدل رقــم ‪/13‬ت‪ 3406 /‬بتاريخ‬\n‫‪1429 /6/17‬ه ـ ونــص احلاجــة منــه ‪ :‬أمــا يف حالــة عــدم ثبــوت اإلدانــة‬\n‫وتوجــه الشــبهة فــا مينــع مــن الســفر وفقـ ًا للمــادة (‪ )56‬املشــار إليهــا وإذا‬\n‫رأى ناظــر القضيــة أن يعــزر مــن توجهــت إليــه الشــبهة باملنــع مــن الســفر‬\n‫فلــه ذلــك ألنــه داخــل ضمــن صالحيــة أصحــاب الفضيلــة وفــق املــادة‬\n‫(‪ )2/6‬مــن نظــام الوثائــق الســفرية بالنســبة للمواطــن الســعودي‬\n‫ا باملــادة (‪ )49‬مــن النظــام‬  ‫وتعليمــات اإلبعــاد بالنســبة لألجنبــي عم ـ ً‬\n\n\n                                                                                        ‫‪434‬‬\n\f      ‫األساســي للحكــم ل ــذا نرغــب إليكــم االطــاع واعتمــاد كــون احلكم‬\n      ‫باملنــع مــن الســفر ال يكــون وفق ـ ًا للمــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة إال يف حــال ثبــوت التهمــة واإلدانــة وفقـ ًا ملــا‬\n      ‫نــص عليــه النظــام مــن أوصــاف جرميــة و يف حــال عــدم ثبــوت اإلدانــة‬\n      ‫ورأى فضيلــة ناظــر القضيــة ‪ -‬لقــوة التهمــة ‪ -‬التعزيــر باملنــع مــن الســفر‬\n      ‫فــإن لــه ذلــك اســتناد ًا علــى املبــادئ العامــة يف التعزيــر لــذا فقــد حكمــت‬\n      ‫بإبعــاد املدعــى عليــه مــن البــاد و عــدم متكينــه مــن دخولهــا مــرة ثانيــة‬\n      ‫اتقــاء لشــره كمــا حكمــت مبصــادرة اجلــوال العائــد للمدعــى عليــه و‬\n      ‫إســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس املدعــى عليــه‬\n      ‫وذلــك بنــاء علــى املصلحــة العامــة حتــى ال يتم اســتغالل الرقــم يف عمليات‬\n      ‫تنســيق و تفــاوض أخــرى مــن قبــل املدعــى عليــه أو غيــره و بعرض احلكم‬\n      ‫عليهمــا قــرر املدعــي العــام املعارضــة و االكتفــاء بالئحــة الدعــوى عــن‬\n      ‫تقــدمي معارضــة وقــرر املدعــى عليــه القناعــة بــه وصلــى اهلل علــى نبينــا‬\n                                  ‫محمد و آله وصحبه وسلم حرر يف ‪1434 /2/27‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة اخلبــر برقم ‪34204121‬‬\n      ‫وتاريــخ ‪1434/4/14‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/959615‬‬\n      ‫وتاريــخ ‪1434/4/20‬ه ـ املرفــق بهاالقــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ... /‬املســجل برقــم ‪ 3457461‬وتاريــخ ‪1434/3/8‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ .../‬بنجالديشــي اجلنســية يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ؛ وبدراســةالقرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n\n\n‫‪435‬‬\n\f‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                         ‫وســلم حــرر يف ‪1434 /5/18‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪436‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":425,"source_page_end":436,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38dbd0fe4274288af2dfd1a32bd944f08c6398b23b416fc4a101cc85a66c4a88","normalized_text_hash":"ef2a0dab0b47b6f3fc80933db9a9e4fe51f11c9631a135e58f40218eea65b83d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p425-3457461"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"2a0cbdd5-8e38-5cfc-abf0-764e102861d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد واملنع من السفر وأداء غرامة مالية ومصادرة اجلوال والغاء الشريحة املستخدمة.","document_number":"3432242","case_number":"3438038","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/6","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد واملنع من السفر وأداء غرامة مالية ومصادرة اجلوال والغاء الشريحة املستخدمة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3432242 :‬تاريخه‪1434/2/6 :‬هـ‬\n                         ‫رقم الدعوى‪3438038:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 3460315‬تاريخه‪1434/3/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬إقــرار املدعــى عليــه ‪ -‬عــدم وجــود‬\n      ‫ســوابق قضائيــة ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬تعزيــر بالســجن واجللــد‬\n      ‫واملنــع مــن الســفر وأداء غرامــة ماليــة ومصــادرة اجلــوال والغــاء‬\n                                                            ‫الشــريحة املســتخدمة‪.‬‬\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n          ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج احلشــيش املخــدر‪ ،‬مت‬\n      ‫القبــض علــى املدعــى عليــه وهــو يســلم املصــدر الســري مــادة احلشــيش‪،‬‬\n      ‫أقــر املدعــى عليــه بالترويــج‪ ،‬وأثبــت التقريــر الكيميائــي الشــرعي‬\n      ‫احتــواء املــادة املضبوطــة علــى احلشــيش املخــدر‪ ،‬وطلــب املدعــي العــام‬\n      ‫احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة ومنعــه مــن الســفر خــارج‬\n      ‫البــاد بعــد تنفيــذ العقوبــة عليهمــا مصــادرة جهــاز اجلــوال املســتخدم يف‬\n      ‫الترويــج ‪ ،‬وإلغــاء الشــريحة املســتخدمة يف الترويــج وذلــك الســتخدامها‬\n      ‫يف قضيــة الترويــج‪ ،‬إلزامــه بدفــع املبلــغ احلكومــي‪ ،‬حكمت احملكمة‬\n      ‫بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪ ،‬فقــررت احلكــم‬\n\n‫‪395‬‬\n\f‫علــى املدعــى عليــه بســجنه ســنة ونصــف مــن تاريــخ إيقافــه بســبب هــذه‬\n‫القضيــة‪ ،‬إلزامــه بدفــع غرامــة ماليــة قدرهــا ثالثــة آالف ري ــال‪ ،‬وجلــده‬\n‫ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات بــن كل دفعــة خمســون جلــدة‬\n‫بــن كل دفعــة وأخــرى عشــرة أيــام‪ ،‬واملنــع مــن الســفر خــارج البــاد ملــدة‬\n‫ســنتني بعــد انتهــاء مــدة محكوميتــه‪ ،‬مصــادرة اجلــوال املســتخدم يف‬\n‫الترويــج وإلغــاء الشــريحة املســتخدمة يف الترويــج وذلــك الســتخدامهما‬\n‫يف قضيــة الترويــج‪ ،‬إلزامــه بدفــع املبلــغ احلكومــي وقــدره مائــة ري ــال‪،‬‬\n‫قــرر املدعــى عليــه عــدم قناعتــه باحلكــم‪ ،‬ومت تصديــق احلكــم مــن قبــل‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬لقاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمة اجلزائية بخميس مشيط برقم ‪..........‬وتاريخ ‪1434/01/21‬هـ‬\n‫املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/21‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام وادعــى ‪..........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪)..........‬‬\n‫جهــة اإلصــدار ظهــران اجلنــوب املهنــة موظــف ‪ .....‬متهــم بالوســاطة يف‬\n‫ا يف دعــواه إنــه عنــد‬   ‫املؤثــرات العقليــة وال يوجــد عليــه ســوابق قائ ـ ً‬\n‫الســاعة الثامنــة مــن مســاء يــوم الســبت املوافــق ‪1433/12/25‬ه ـ ورد‬\n‫بــاغ مــن أحــد املصــادر الســرية مفــاده عــن قيــام املتهــم ‪..........‬بالتوســط‬\n‫يف ترويــج احلبــوب احملظــورة ويحمــل جــوال رقــم (‪ )..........‬فتــم االتصــال‬\n‫علــى جــوال مــن قبــل املصــدر ومت التفــاوض معــه علــى شــراء قطعــة مــن‬\n\n                                                                                       ‫‪396‬‬\n\f      ‫احلشــيش املخــدر مببلــغ (‪ )100‬مائــة ريــال فاســتعد بذلــك وطلــب مــن‬\n      ‫املصــدر مقابلتــه عنــد ‪ ....‬مقــر عملــه فقابلــه املصــدر مــع أحــد أفــراد‬\n      ‫الفرقــة وكان معهمــا املبلــغ املرقــم وركــب معهــم املتهــم واســتلم املبلــغ‬\n      ‫املرقــم مــن الفــرد وطلــب مــن الفــرد االجتــاه إلــى حــي ‪ .....‬ثــم نــزل املتهــم‬\n      ‫مــن الســيارة واختفــى عــن األنظــار وبعــد عشــر دقائــق عــاد املتهــم وســلم‬\n      ‫للفــرد قطعــة علــى شــكل أصبــع بلــغ وزنهــا (‪ )2.3‬اثنــان جــرام وثالثــة‬\n      ‫مــن العشــرة مــن اجلــرام ومت إعادتــه إلــى مقــر عملــه وعنــد وصولــه إلــى‬\n      ‫البنــك ومشــاهدته للفرقــة قــام بابتــاع شــيء مــا كان بيــده فقبــض‬\n      ‫عليــه وبتفتيشــه لــم يعثــر معــه علــى أي شــيء مــن املمنوعــات ووجــد معــه‬\n      ‫اجلــوال املســتخدم يف عمليــة الترويــج ولــم يعثــر علــى املبلــغ املرقــم فتــم‬\n      ‫التحفــظ عليــه وعلــى املضبوطــات وبســماع أقــوال املتهــم أقــر بأنــه قــام‬\n      ‫بالتوســط يف ترويــج قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )2.3‬اثنــان‬\n      ‫جــرام وثالثــة مــن العشــرة مــن اجلــرام وباســتجواب املتهــم بعــد إحاطتــه‬\n      ‫بالتهمــة املوجهــة لــه وبجهــة التحقيــق أقــر بــأن اجلــوال رقــم (‪ )..........‬عائــد‬\n      ‫لــه وأنكــر عالقتــه بالتوســط يف الترويــج وبتحليــل عينــة ممــا مت ضبطــه‬\n      ‫ثبــت احتوائهــا علــى مــادة احلشــيش املخــدر مبوجــب التقريــر الكيميائــي‬\n      ‫الشــرعي رقــم (‪ )..........‬لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة‬\n      ‫الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة عســير واحلشــيش مــن‬\n      ‫املــواد املدرجــة باجلــدول رقــم (‪ )4‬فئــة (أ‪،‬ج) وهــو مــن املــواد املخــدرة‬\n      ‫امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وملــا أشــير‬\n      ‫إليــه أقــر توجيــه االتهام‪..........‬بالتوســط يف ترويــج قطعــة مــن احلشــيش‬\n      ‫املخــدر بلــغ وزنهــا (‪ )2.3‬اثنــان جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n      ‫واملجــرم مبوجــب املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n\n\n‫‪397‬‬\n\f‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ /1 :‬أقوالــه املدونــة مبلــف التحقيــق ‪/2‬‬\n‫محضــر القبــض والتفتيــش ‪ /3‬التقريــر الكيميائــي وحيــث أن مــا‬\n‫أقــدم عليــه املذكــور فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة بعقوبــة األصليــة‬\n‫والتكميليــة وقــد أقــدم عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا لــذا‬\n‫فإنه يتعني إحالته للمحكمة اجلزئية بخميس مشــيط اســتناد ًا للمادتني‬\n‫(‪ )126‬و (‪ )128‬مــن نظــام اإلجــراءات اجلزائيــة بطلــب إثبــات مــا أســند‬\n‫إليــه واحلكــم عليــه مبــا يلــي‪ /1 :‬عقوبــة تعزيريــة وفقـ ًا ملــا ورد يف املــادة‬\n‫(‪ )1/38‬مــن النظــام املشــار إليــه لقــاء مــا أســند إليــه ‪ /2‬منعــه مــن الســفر‬\n‫خــارج اململكــة بعــد تنفيــذ العقوبــة وفقـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة‬\n‫األولى من النظام املشار إليه ‪ /3‬مصادر اجلوال ذى الرقم املصنعي رقم‬\n‫(‪ )..........‬وفقـ ًا ملــا ورد يف الفقــرة األولــى للمــادة (‪ )53‬مــن النظــام املشــار‬\n‫إليــه وإلغــاء الشــريحة الهاتفيــة رقــم (‪ )..........‬اســتناد ًا لتعميــم صاحــب‬\n‫الســمو امللكــي وزيــر الداخليــة رقــم (‪ )9897‬وتاريــخ ‪1428/2/10-9‬ه ـ‬\n‫‪ /4‬إلــزام املتهــم بدفــع املبلــغ احلكومــي وقــدره (‪ )100‬مائــة ريال اســتناد ًا‬\n‫لبرقيــة صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪)65980/4/5/1‬‬\n‫وتاريــخ ‪1428/10/23-22‬ه ـ هــذه دعــواي وبعرضهــا علــى املدعــى عليــه‬\n‫أجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن توســطي يف ترويــج قطعــة مــن‬\n‫احلشــيش املخــدر يبلــغ وزنهــا اثنــان جــرام وثالثــة مــن العشــرة مــن اجلــرام‬\n‫صحيــح وأنــا تائــب ونــادم هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى‬\n‫أقوالــه املدونــة يف دفتــر االســتدالل بتاريــخ ‪1434/12/25‬ه ــواملتضمن‬\n‫إقــرار املدعــى عليــه بالتوســط يف ترويــج قطعــة حشــيش هــذا وقــد جــرى‬\n\n\n                                                                                           ‫‪398‬‬\n\f      ‫االطــاع علــى محضــر القبــض والتفتيــش واملتضمــن أنــه مت تكليــف‬\n      ‫أحــد الفــرق القابضــة يف مكافحــة املخــدرات متابعــة املدعــى عليــه‬\n      ‫وجــرى االتصــال عليــه مــن قبــل املصــدر الســري علــى جوالــه وجــرى‬\n      ‫االتفــاق علــى شــراء قطعــة حشــيش مببلــغ مائــة ريــال وطلــب مــن املصــدر‬\n      ‫الســري مقابلتــه ‪ .......‬حيــث مقــر عملــه وركــب مــع املصــدر الســري‬\n      ‫واجتهــا إلــى حــي ‪..........‬وغــاب املدعــى عليــه عشــر دقائــق تقريبـ ًا ثــم عــاد‬\n      ‫وســلم للمصــدر قطعــة احلشــيش املتفــق عليــه وســلم املبلــغ املرقــم ثــم عــاد‬\n      ‫املصــدر وبرفقتــه املدعــى عليــه إلــى البنــك وبتفتيشــه لــم يعثــر علــى أي‬\n      ‫مخــدرات هــذا وقــد جــرى االطــاع علــى التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )..........‬واملتضمــن إيجابيــة العينــة املضبوطــة للحشــيش املخــدر‬\n      ‫ـاء علــى محضــر القبــض والتفتيــش والتقريــر الكيميائــي املشــار‬                ‫وبنـ ً‬\n      ‫إليهمــا أعــاه ونظــر ًا ألن املدعــى عليــه يســتحق عقوبــة طبق ـ ًا للقواعــد‬\n      ‫الشــرعية ووفقـ ًا للمادتــن (‪ )56( ، )38‬مــن نظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة ونظــر ًا لقلــة الكميــة التــي توســط بهــا وخللــو صحيفــة‬\n      ‫املدعــى عليــه مــن الســوابق وملقتضــى املــادة (‪ )60‬مــن النظــام املشــار‬\n      ‫ـدي إدانــة املدعــى عليــه بالتوســط‬     ‫إليــه ولــكل مــا تقــدم فقــد ثبــت لـ ّ‬\n      ‫ببيــع قطعــة حشــيش مخــدر بلــغ وزنهــا اثنــان جــرام وثالثــة مــن العشــرة‬\n      ‫مــن اجلــرام وحكمــت بتعزيــره لقــاء ذلــك مبــا يلــي‪ :‬أوالً‪ :‬ســجن املدعــى‬\n      ‫ـاء علــى‬\n             ‫عليــه ملــدة ســنه ونصــف مــن تاريــخ إيقافــه بســبب هــذه القضيــة بنـ ً‬\n      ‫املادتــن (‪ )38،60‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n      ‫وإلزامــه بدفــع غرامــه ماليــه قدرهــا ثالثــة آالف ريــال وجلــده ثالثمائــة‬\n      ‫جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســون جلــدة كل دفعــه‬\n      ‫خمســون جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام‪ .‬ثاني ـاً‪ :‬منعــه مــن‬\n\n\n‫‪399‬‬\n\f‫الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء مــدة محكوميتــه‬\n‫ـاء علــى املــادة (‪ )56‬مــن النظــام املشــار إليــه‪ .‬ثالث ـاً‪ :‬مصــادرة اجلــوال‬ ‫بنـ ً‬\n‫ـاء علــى املــادة (‪ )53‬مــن النظــام املشــار‬  ‫ذو الرقــم املصنعــي (‪ )..........‬بنـ ً‬\n‫إليــه وإلغــاء الشــريحة الهاتفيــة رقــم (‪ )..........‬اســتناد ًا لتعميــم ســمو وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬بتاريــخ ‪1428/2/10-9‬ه ـ رابع ـاً‪ :‬إلزامــه بدفــع‬\n‫املبلــغ احلكومــي املرقــم وقــدره مائــة ريــال اســتناد ًا لبرقيــة ســمو وزيــر‬\n‫الداخليــة (‪ )65980/4/5/1‬وتاريــخ ‪1428/10/23-22‬ه ـ ومبــا تقــدم‬\n‫حكمــت وبإعــان احلكــم قــرر املدعــي العــام االعتــراض بــدون الئحــة‬\n‫اعتراضيــة وقــرر املدعــى عليــه القناعــة وأمــرت برفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وجــرى النطــق باحلكــم‬\n‫بتاريــخ ‪1434/2/5‬ه ـ الســاعة احلاديــة عشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪..........‬وتاريــخ ‪1434/2/25‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة‬\n‫القاضــي باحملكمــة الشــيخ ‪....... /‬برقــم ‪ ..........‬وتاريخ‪1434/2/6‬ه ـ‬\n‫واخلــاص بدعــوى املدعــي العــام ضــد ‪ .......... /‬يف قضيــة (مخــدرات )‬\n‫علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                     ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n                                                                                            ‫‪400‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":395,"source_page_end":400,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d3025bf0412de4dc256d194173a3476260c71ff8bf78d4a13eb99b73b31f0b57","normalized_text_hash":"77eeb6ecbbb0acac6d0519212a3fd89baa19c35f54f4412a3d2507bb1c6a6933","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p395-3432242"},{"id":"6d57f840-1462-5ff9-8064-db0c0e19aa26","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -االجتار يف احلبوب احملظورة -ترويج احلبوب احملظورة - تعاطي احلبوب احملظورة -ثبوت إدانة املدعى عليه -اعتراف املدعى عليه األول وإنكار املدعى عليه الثاني -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة املبلغ املضبوط واجلوال وإلغاء الشريحة املستخدمة يف اجلرمية -رد طلب املدعى العام مبعاقبة املدعى عليه الثاني -رد مصادرة السيارة .","document_number":"3425509","case_number":"3438064","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/28","year":"1434","subject":"مخدرات -االجتار يف احلبوب احملظورة -ترويج احلبوب احملظورة - تعاطي احلبوب احملظورة -ثبوت إدانة املدعى عليه -اعتراف املدعى عليه األول وإنكار املدعى عليه الثاني -تعزير بالسجن واجللد والغرامة واملنع من السفر ومصادرة املبلغ املضبوط واجلوال وإلغاء الشريحة املستخدمة يف اجلرمية -رد طلب املدعى العام مبعاقبة املدعى عليه الثاني -رد مصادرة السيارة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3425509 :‬تاريخه‪1434/01/28 :‬هـ‬\n                           ‫رقم الدعوى‪3438064:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3439176‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬االجتــار يف احلبــوب احملظــورة ‪ -‬ترويــج احلبــوب احملظــورة ‪-‬‬\n       ‫تعاطــي احلبــوب احملظــورة ‪ -‬ثبــوت إدانــة املدعى عليــه ‪ -‬اعتراف املدعى‬\n       ‫عليــه األول وإنــكار املدعــى عليــه الثانــي ‪ -‬تعزيــر بالســجن واجللــد‬\n       ‫والغرامــة واملنــع مــن الســفر ومصــادرة املبلــغ املضبــوط واجلــوال وإلغــاء‬\n       ‫الشــريحة املســتخدمة يف اجلرميــة ‪ -‬رد طلــب املدعــى العــام مبعاقبــة‬\n                                   ‫املدعــى عليــه الثانــي ‪ -‬رد مصــادرة الســيارة ‪.‬‬\n\n\n\n\n       ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n           ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n       ‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهما بترويج املخدرات احلشــيش‬\n       ‫املخدر ‪ ،‬مت القبض على املدعى عليهما بعد ترويجهما مادة احلشــيش‪،‬‬\n       ‫أقــر املدعــى عليــه بصفــة الترويــج‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي‬\n       ‫احتــواء املــادة املضبوطــة علــى احلشــيش‪ ،‬طلــب املدعــي العــام احلكــم‬\n       ‫ـاء علــى مــا ورد يف نصــوص نظــام مكافحــة‬      ‫علــى املدعــى عليهمــا ‪ -‬بنـ ً‬\n       ‫املخــدرات واملؤثــرات العقليــة‪ -‬بعقوبة تعزيرية ومنعهما من الســفر خارج‬\n       ‫البــاد بعــد تنفيــذ العقوبــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة وإلغــاء‬\n\n‫‪401‬‬\n\f‫الشــريحة ‪ ،‬ومصــادرة املبلــغ الــذي أفــاد بأنــه مــن نتــاج بيعــه للمخــدرات‪،‬‬\n‫ومصــادرة الســيارة العائــدة للمتهــم الثانــي املســتخدمة يف اجلرميــة ‪ ،‬إقرار‬\n‫املدعــى عليــه األول بالدعــوى وإنــكار املدعــى عليــه الثانــي ســوى إقــراره‬\n‫بالتعاطــي ووجــود قرائــن تدينــه منهــا إقــراره بالتعاطــي ومحضــر القبــض‬\n‫‪ ،‬حكمــت احملكمــة بثبــوت إدانــة املدعــى عليهمــا بترويــج وتعاطــي‬\n‫احلبــوب احملظــورة‪ ،‬فقــررت احملكمــة احلكــم علــى املدعــى عليــه األول‬\n‫بســجنه مــدة ســنة وســتة أشــهر تعزيــرا للقرائــن والتهــم تبــدأ مــن تاريــخ‬\n‫توقيفــه يف هــذه القضيــة ‪ ،‬وجلــده مائــة وخمســون جلــدة مفرقــة علــى‬\n‫دفعــات كل دفعــة خمســون جلــدة بينهمــا عشــر أيــام‪ ،‬وإلزامــه بدفــع‬\n‫غرامــة ماليــة قدرهــا ألــف ري ــال خلزينــة الدولــة‪ ،‬ومنعــه مــن الســفر خلــارج‬\n‫البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة ســجنه‪ ،‬ومصــادرة اجلــوال‬\n‫املســتخدم يف اجلرميــة وإلغــاء الشــريحة‪ ،‬ومصــادر املبلــغ وقــدره ألفــان‬\n‫وثالثمائــة وأربعــة عشــر ريــاال‪ ،‬وتعزيــر املدعــى عليهمــا باجللــد خمســن‬\n‫جلــدة دفعــة واحــدة لقــاء تعاطيهمــا املخــدرات‪ ،‬رد معاقبــة املدعــى عليــه‬\n‫الثانــي وكذلــك رد طلــب مصــادرة الســيارة‪ ،‬تعزيــر املدعــى عليــه‬\n‫الثانــي لقــاء توجــه التهمــة عليــه بترويــج احلبــوب احملظــورة بالتســليم‬\n‫وذلــك بســجنه ســتة أشــهر تبــدأ مــن تاريــخ توقيفــه يف القضيــة‪ ،‬قــررا‬\n‫املدعــى عليهمــا عــدم قناعتهمــا باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n\n                                                                                        ‫‪402‬‬\n\f      ‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ ‪1434/01/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/21‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافق‪1434/01/27‬ه ـ حضــر املدعــي العــام‪.......... /‬املشــار‬\n      ‫ا دعــواي هــي مــا ورد يف الئحــة‬    ‫إلــى تكليفــه يف الضبــط وادعــى قائ ـ ً‬\n      ‫الدعــوى العامــة املتضمنــة االدعــاء علــى كل مــن‪..........-1 /‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪............-2)..........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقم(‪)..........‬حيــث أنــه مت القبــض علــى‬\n      ‫املدعــى عليهمــا مــن قبــل مكافحــة املخــدرات بعــد قيامهمــا بترويــج‬\n      ‫املخــدرات وقــد انتهــى التحقيــق معهمــا إلــى توجيــه االتهــام للمدعــى‬\n      ‫عليهمــا بترويــج عــدد أربــع حبــات مــن احلبــوب املنبهــة احملظــورة األول‬\n      ‫عــن طريــق البيــع وتعاطيــه مــن املضبــوط والثانــي بالتســليم وتعاطيــه‬\n      ‫مــن الســابق للحبــوب احملظــورة وذلــك لألدلــة والقرائــن التاليــة ‪ -1:‬مــا‬\n      ‫ورد يف اعترافهمــا املــدون علــى اللفــة رقــم (‪ - 2)17‬مــا تضمنــه محضــر‬\n      ‫القبــض والشــراء املــدون علــى اللفــة لفــة رقــم(‪-3 )1‬التقريرالكيميائــي‬\n      ‫الشــرعي املرفــق بالرقم(‪)24‬وبالبحــث عــن ســوابقهما اتضــح عــدم‬\n      ‫وجــود ســوابق مســجله عليهمــا وحيــث أن مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫وهمــا بكامــل أهليتهمــا املعتبــرة شــرعا فعــل محــرم شــرع ًا ومعاقــب‬\n      ‫عليــه مبوجــب نظــام مكافحــة املخــدرات لــذا أطلــب إثبــات مــا أســند‬\n      ‫إليهمــا واحلكــم عليهمــا مبــا يلــي‪-1 :‬عقوبــة تعزيريــة وفق ـ ًا ملــا ورد يف‬\n      ‫املــادة (‪ )1/38‬الفقــرة األولــى بحدهــا األعلــى مــن النظــام املشــار إليــه‬\n      ‫بحدهــا األعلــى لقــاء مــا أســند إليهمــا ‪ -2‬منعهمــا مــن الســفر إلــى خــارج‬\n      ‫البــاد بعــد تنفيــذ العقوبــة وفقــا ملــا ورديف املــادة (‪)1/56‬مــن النظــام‬\n      ‫املشــار إليــه ‪ -3‬مصــادرة اجلــوال ذي الرقــم املصنعــي رقــم(‪)..........‬‬\n\n\n‫‪403‬‬\n\f‫وفقــا ملــا ورد يف املــادة الثالثــة واخلمســن مــن النظــام املشــار إليــه وعــدم‬\n‫صــرف الشــريحة رقم(‪)..........‬لنفــس املشــترك اســتنادا لتعميــم صاحــب‬\n‫الســمو امللكــي وزيــر الداخليــة رقم(‪)9895‬وتاريــخ ‪1428/02/1-9‬ه ـ‬\n‫‪ -4‬مصــادرة املبلــغ الــذي أفــاد بأنــه مــن نتــاج بيعــه للمخــدرات وقــدره‬\n‫ألفــان وثالثمائــة وأربعــة عشــر ريــاال ومصــادرة الســيارة مــن نــوع ‪..........‬‬\n‫موديل(‪)..........‬لوحــة رقــم(‪ )..........‬والعائــدة للمتهــم الثانــي املســتخدمة‬\n‫يف اجلرميــة اســتنادا للمــادة (‪ )1/53‬مــن ذات النظــام هــذه دعــواي ويف‬\n‫هــذه اجللســة حضــر املدعــى عليهمــا وبســؤالهما اإلجابــة علــى دعــوى‬\n‫املدعــي العــام أجــاب املدعــى عليــه األول بقولــه مــا نســب لــي يف دعــوى‬\n‫املدعــي العــام كلــه صحيــح حيــث قمــت بترويــج احلبــوب احملظــورة‬\n‫مقابــل مبلــغ مائــة وخمســون ريــا ًال واســتخدمت اجلــوال املشــار إليــه يف‬\n‫التنســيق يف هــذه العمليــة وقــد تعاطيــت احلبــوب احملظــورة واملدعــى عليــه‬\n‫الثانــي ال عالقــة لــه بهــذه القضيــة وأنــا تائــب إلــى اهلل وأتعهــد بعــدم‬\n‫ال وليــس لــي ســوابق هــذه إجابتــي وأجــاب املدعــى‬   ‫تكــرار ذلــك مســتقب ً‬\n‫عليــه الثانــي بقولــه مــا نســب لــي يف الدعــوى غيــر صحيــح والصحيــح‬\n‫أنــي كنــت أقــود ســيارتي مســجلة باســمي وهــي لوالــدي وكان املدعــى‬\n‫عليــه األول راكب ـ ًا معــي وطلــب منــي تســليم كيــس نايلــون لشــخص‬\n‫آخــر ال أعرفــه فســلمته لــه ولــم أكــن أعلــم بوجــود احلبــوب احملظــورة‬\n‫داخــل الكيــس وأنــا أتعاطــى احلبــوب احملظــورة يف الســابق وليــس‬\n‫لــي ســوابق مســجلة علــي هــذه إجابتــي وجــرى االطــاع علــى األدلــة‬\n‫والقرائــن املشــار إليهــا فوجــد مضمونهــا كمــا ذكــر ووجــد يف محضــر‬\n‫القبــض املــدون يف امللــف املرفــق باملعاملــة لفــة رقم(‪)1‬أنــه حــن القبــض‬\n‫علــى املدعــى عليهمــا ضبــط مــع املدعــى عليــه األول مبلــغ قــدره أربعــة‬\n\n\n                                                                                        ‫‪404‬‬\n\f      ‫آالف وثالثمائــة وأربعــة عشــر ريــا ًال مــن ضمنهــا املبلــغ احلكومــي كمــا‬\n      ‫وجــد يف إقــرار املدعــى عليــه األول حتقيق ـ ًا أن املبلــغ الــذي ضبــط معــه‬\n      ‫حصــل عليــه عــن طريــق اإلعانــة مــن برنامــج حافــز وأمــا بقيــة املبلــغ فهــو‬\n      ‫نتــاج بيعــه للمــواد املخــدرة ووجــد إقــرار املدعــى عليــه الثانــي حتقيق ـ ًا‬\n      ‫كمــا جــاء يف إجابتــه وجــرى ســؤال املدعــى عليــه األول عــن مصــدر‬\n      ‫ا ضبــط بحوزتــي مبلــغ قــدره‬        ‫املبلــغ الــذي ضبــط بحوزتــه فقــرر قائ ـ ً‬\n      ‫أربعــة آالف وثالثمائــة وأربعــة عشــر ريــا ًال ألفــان منهــا حصلــت عليهــا‬\n      ‫مــن برنامــج اإلعانــة حافــز والباقــي حصيلــة بيــع احلبــوب احملظــورة‬\n      ‫ـاء علــى‬ ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنـ ً‬  ‫هكــذا قــرر فبنـ ً‬\n      ‫مــا يلــي‪ -1:‬اعتــراف املدعــى عليــه األول مبــا نســب لــه يف الدعــوى‬\n      ‫واعترافــه باســتخدام اجلــوال وشــريحة االتصــال يف التنســيق لعمليــة‬\n      ‫الترويــج ‪ -2‬ترويــج املدعــى عليــه األول للحبــوب احملظــورة فعــل محــرم‬\n      ‫شــرع ًا ومجــرم نظام ـ ًا ومعاقــب عليــه مبــا ورد يف املادتــن(‪)56-38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات مــع إعمــال املــادة الســتني وذلــك لعــدم‬\n      ‫وجــود ســوابق مســجلة عليــه وملــا قــرره مــن التوبــة والتعهــد ‪-3‬اســتخدام‬\n      ‫املدعــى عليــه األول للجــوال وشــريحة االتصــال املشــار إليهــا يف الدعــوى‬\n      ‫العامــة يف التنســيق لعمليــة الترويــج موجبــة ملصادرتهــا وفق ـ ًا للمــادة‬\n      ‫(‪)53‬مــن النظــام املشــار إليــه ‪-4‬اعتــراف املدعــى عليــه األول بــأن جــزء‬\n      ‫مــن املبلــغ املضبــوط معــه وقــدره ألفــان وثالثمائــة وأربعــة عشــر ريــا ًال‬\n      ‫حصيلــة بيــع احلبــوب احملظــورة موجــب ملصادرتــه ‪ -5‬اعتــراف املدعــى‬\n      ‫عليهمــا بتعاطــي احلبــوب احملظــورة وفعلهمــا هــذا محــرم ومعاقــب عليــه‬\n      ‫بعقوبــة تعزيريــة ومعاقبــة الثانــي مبوجــب املــادة (‪)56‬مــن النظــام املشــار‬\n      ‫إليــه ‪-6‬إنــكار املدعــى عليــه الثانــي ملــا نســب لــه يف الدعــوى العامــة مــن‬\n\n\n‫‪405‬‬\n\f‫ترويجــه احلبــوب احملظــورة عــن طريــق التســليم ولــم يقــدم املدعــي العــام‬\n‫أدلــة كافيــة إلثبــات إدانتــه بذلــك إال أن مــا تضمنــه إقــراره حتقيق ـ ًا‬\n‫ومــا تضمنــه محضــر القبــض قرائــن تــورث تهمتــه بذلــك ويســتحق عليهــا‬\n‫عقوبــة تعزيريــة لــذا فقــد تقــرر مــا يلــي‪ :‬أو ًال ثبــت لــدي إدانــة املدعــى‬\n‫عليــه األول‪.......... /‬بترويــج عــدد أربــع حبــات مــن احلبــوب احملظــورة‬\n‫عــن طريــق البيــع وقــررت تعزيــره علــى ذلــك بســجنه مــدة ســنة وســتة‬\n‫أشــهر تبــدأ مــن تاريــخ توقيفــه يف هــذه القضيــة وجلــده مائــة وخمســن‬\n‫جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة وبينهمــا عشــرة‬\n‫أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا ألــف ريــال خلزينــة الدولــة ومنعــه‬\n‫مــن الســفر إلــى خــارج هــذه البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة‬\n‫ســجنه ثاني ـاً‪ :‬قــررت مصــادرة اجلــوال وشــريحة االتصــال املشــار إليهــا‬\n‫يف الئحــة الدعــوى كمــا قــررت مصــادرة املبلــغ املضبــوط مــع املدعــى‬\n‫عليــه األول وقــدره ألفــان وثالثمائــة وأربعــة عشــر ريــا ًال ثالثـاً‪ :‬ثبــت لــدي‬\n‫تعاطــي املدعــى عليهمــا للحبــوب احملظــورة وقــررت تعزيرهمــا علــى ذلــك‬\n‫بجلــد كل منهمــا خمســن جلــدة دفعــة واحــدة ومنــع املدعى عليــه الثاني‬\n‫مــن الســفر إلــى خــارج هــذه البــاد مــدة ســنتني تبــدأ بعــد انتهــاء عقوبــة‬\n‫ســجنه رابعـاً‪ :‬لــم يثبــت لــدي إدانــة املدعــى عليــه الثانــي‪.......... /‬بترويــج‬\n‫الكميــة املشــار إليهــا مــن احلبــوب احملظــورة عــن طريــق التســليم وقــررت‬\n‫رد طلــب املدعــي العــام معاقبــة املدعــى عليــه الثانــي مبوجــب املــادة(‪)38‬‬\n‫مــن النظــام املشــار إليــه كمــا قــررت رد طلــب املدعــي العــام مصــادرة‬\n‫الســيارة املشــار إليهــا العائــدة للمدعــى عليــه الثانــي خامس ـاً‪ :‬قــررت‬\n‫تعزيــر املدعــى عليــه الثانــي لقــاء توجــه التهمــة عليــه بترويــج احلبــوب‬\n‫احملظــورة عــن طريــق التســليم وذلــك بســجنه مــدة ســتة أشــهر تبــدأ مــن‬\n\n\n                                                                                         ‫‪406‬‬\n\f      ‫تاريــخ توقيفــه يف هــذه القضيــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n      ‫املدعــي العــام قــرر اعتراضــه عليــه وطلــب رفــع احلكــم إلــى محكمــة‬\n      ‫االســتئناف بــدون تقــدمي الئحــة اعتراضيــة وبعــرض احلكــم علــى املدعــى‬\n      ‫عليهمــا قــررا القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/27‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة‬\n      ‫لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس‬\n      ‫مشــيط برقــم ‪..........‬وتاريــخ ‪1434 /02/04‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيل ــة القاضــي باحملكمــة الشــيخ ‪..........‬برقــم ‪..........‬‬\n      ‫وتاريــخ ‪1434/01/28‬ه ــاخلاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد كل‬\n      ‫مــن ‪ .......... /‬يف قضيــة ( مخــدرات ) علــى الصفــة املوضحــة يف القــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل‬\n                    ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪407‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":401,"source_page_end":407,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fbb97eeb64edf26d8e2776cb822b5bef72f411e27579bc358095e41b53ac87c4","normalized_text_hash":"8973d083fa03d266dc4c11e74ade2bdd886d9db0e4b35d7b2391df0f24a4aea1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p401-3425509"},{"id":"c63b7f55-3480-5482-b34b-6ae6fb7dba95","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -تعاطي احلبوب احملظورة «امفيتامن» -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع","document_number":"3428687","case_number":"3438099","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"مخدرات -تعاطي احلبوب احملظورة «امفيتامن» -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -عدم وجود سوابق قضائية -تعزير بالسجن واجللد والغرامة واملنع","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 3428687 :‬تاريخه‪1434/2/3 :‬هـ‬\n                    ‫رقم الدعوى‪3438099:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3451856‬تاريخه‪1434/3/1 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬تعاطــي احلبــوب احملظــورة «امفيتامــن» ‪ -‬ترويــج احلبــوب‬\n‫احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت إدانــة املدعــى عليــه ‪ -‬عــدم‬\n‫وجــود ســوابق قضائيــة ‪ -‬تعزيــر بالســجن واجللــد والغرامــة واملنــع‬\n                                                                ‫مــن الســفر‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )56‬واملــادة (‪ )60‬مــن‬\n                                 ‫نظــام مكافحــة املخــدرات واملؤثــرات العقلية‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج احلبــوب احملظــورة‬\n‫«االمفيتامــن»‪ -‬بقصــد الكســب املــادي‪ ،‬مت القبــض علــى املدعــى‬\n‫عليــه وبحوزتــه حبــوب االمفيتامــن‪ ،‬أقــر املدعــى عليــه بالترويــج‪،‬‬\n‫أثبــت التقريــر الكيميائــي الشــرعي احتــواء املــادة املضبوطــة علــى‬\n‫االمفيتامــن‪ ،‬طلــب املدعــي العــام احلكــم علــى املدعــى عليــه بعقوبــة‬\n‫تعزيريــة ‪ ،‬واملنــع مــن الســفر خــارج البــاد ‪ -‬حكمــت احملكمــة بثبــوت‬\n‫إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة‪ ،‬وقــررت احملكمــة‬\n‫احلكــم عليــه بســجنه ثــاث ســنوات مــن تاريــخ التوقيــف‪ ،‬وجلــده مائــة‬\n‫وخمســون جلــدة مفرقــة علــى ثــاث فتــرات متســاويات بــن كل فتــرة‬\n\n                                                                                       ‫‪408‬‬\n\f      ‫وأخــرى عشــر أيــام منهــا فتــرة علنــا يف مــكان عــام‪ ،‬وبعــد اجللــد الســابق‬\n      ‫بخمســة عشــر يومــا يجلــد املدعــى عليــه ســبعني جلــدة دفعــة واحــدة لقــاء‬\n      ‫تعاطــي احلبــوب احملظــورة‪ ،‬يدفــع غرامــة ماليــة قدرهــا ألــف وخمســمائة‬\n      ‫ري ــال يف خزينــة الدولــة العامــة‪ ،‬منعــه مــن الســفر خلــارج البــاد ملدة ثالث‬\n      ‫ســنوات‪ ،‬قــرر املدعــى عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم‬\n                                                   ‫مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ‬\n      ‫‪1434/01/21‬ه ـ املقيــدة باحملكمة برقم ‪..........‬وتاريخ ‪1434/01/21‬‬\n      ‫ه ـ ففــي يــوم الســبت املوافــق‪ 1434/02/02‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪10 : 30‬وفيهــا حضــر املدعــي ‪ ، ..........‬املكلــف بخطــاب التكليف رقم‬\n      ‫‪ 51‬وتاريــخ ‪1430/5/8‬ه ـ ‪ ،‬وادعــى علــى احلاضــر يف مجلــس القضــاء‬\n      ‫‪ ،..........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ،..........‬يبلــغ‬\n      ‫مــن العمــر ‪ 31‬ســنة ‪ ،‬عاطــل عــن العمــل ‪ ،‬محصــن ‪ ،‬يقيــم بأحــد ‪، ..‬‬\n      ‫املقبــوض عليــه بتاريــخ ‪1433/12/28‬ه ـ ‪ ،‬أودع ســجن خميــس مشــيط‬\n      ‫بتاريخ ‪1434/1/3‬هـ ‪ ،‬قائال يف دعواه انتهى التحقيق مع املذكور إلى‬\n      ‫توجيــه االتهــام لــه بترويــج عــدد أربــع وعشــرين حبــة محظــورة عــن طريــق‬\n      ‫البيــع ‪ ،‬وتعاطيــه حلبــة واحــدة محظــورة مــن الســابق ‪ ،‬وبتحليــل عينــة‬\n      ‫ممــا مت ضبطــه ثبــت احتواءهــا علــى مــادة االمفيتامــن املنبهــة احملظــورة‬\n      ‫مبوجــب التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n\n‫‪409‬‬\n\f‫الســموم والكيميــاء الطبيــة الشــرعية مبنطقــة عســير برقم‪..........‬لعــام‬\n‫‪1434‬ه ـ واملرفــق علــى اللفــة ‪ ،37‬وبالبحــث عــن ســوابقه اتضــح عــدم‬\n‫وجــود ســوابق مســجلة عليــه ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بعقوبــة تعزيريــة وفقــا ملــا ورد يف املــادة ‪ 1/38‬مــن نظــام املخــدرات‬\n‫واملؤثــرات العقليــة لقــاء مــا نســب إليــه مــن الترويــج ‪ ،‬وإجــراء املقتضــى‬\n‫الشــرعي بحقــه لقــاء تعاطيــه للحبــوب احملظــورة ‪ ،‬ومنعــه مــن الســفر‬\n‫خــارج اململكــة بعــد تنفيــذ العقوبــة وفقــا ملــا ورد يف املــادة ‪ 1/56‬مــن‬\n‫ذات النظــام ‪ ،‬هكــذا ادعــى ‪ ،‬وبســؤال املدعــى عليــه قــال إن جميــع مــا‬\n‫ذكــره املدعــي العــام يف دعــواه صحيــح جملــة وتفصيــا حيــث روجــت‬\n‫عــدد أربــع وعشــرين حبــة محظــورة عــن طريــق البيــع علــى أحــد املصــادر‬\n‫الســرية ملكافحــة املخــدرات الــذي طلــب منــي أن أبيــع لــه عــدد خمــس‬\n‫وعشــرين حبــة محظــورة مببلــغ ثمامنائــة وخمســن ريــاال فبعــت عليــه أربــع‬\n‫وعشــرين حبــة باملبلــغ املذكــور وتعاطيــت حبــة منهــا قبــل القبــض علــي‬\n‫‪ ،‬وإنــي إذ اعتــرف بخطــأي فإنــي أعدكــم وعــدا جازمــا أال يتكــرر‬\n‫منــي مثــل ذلــك مــرة أخــرى إن شــاء اهلل تعالــى هكــذا أجــاب ‪ ،‬فنظــرا‬\n‫إلــى مــا ورد يف الدعــوى ‪ ،‬وإلــى إقــرار املدعــى عليــه مبــا نســب إليــه ‪،‬‬\n‫ومــا نســب إليــه مــن الترويــج موجــب لعقابــه مبــا دون احلــد األدنــى مــن‬\n‫عقوبــة الســجن الــواردة يف مــادة النظــام املشــار إليهــا يف الدعــوى ‪ ،‬نظــرا‬\n‫إلــى املــادة الســتني مــن ذات النظــام ‪ ،‬لعــدم وجــود ســوابق مســجلة علــى‬\n‫املدعــى عليــه وملــا أظهــره مــن اعتــراف باخلطــأ ووعــد بعــدم العــودة إليــه‬\n‫‪ ،‬ويعــزر مبــا دون حــد املســكر لقــاء تعاطيــه احلبــوب احملظــورة ألنهــا‬\n‫منبهــة وليســت مخــدرة ‪ ،‬وبنــاء علــى كل مــا تقــدم فقــد ثبــت لــدي ترويج‬\n‫املدعــى عليــه لعــدد أربــع وعشــرين حبــة محظــورة عــن طريــق البيــع ‪،‬‬\n\n\n                                                                                      ‫‪410‬‬\n\f      ‫ويســجن لقــاء ذلــك ثــاث ســنوات مــن تاريــخ التوقيــف ‪ ،‬ويجلــد مائــة‬\n      ‫وخمســن جلــدة علــى ثــاث فتــرات متســاويات بــن كل فتــرة وأخــرى‬\n      ‫عشــرة أيــام منهــا فتــرة واحــدة علنــا يف مــكان عــام ‪ ،‬ويدفــع غرامــة‬\n      ‫ماليــة قدرهــا ألــف وخمســمائة ريــال تــودع يف خزينــة الدولــة العامــة ‪،‬‬\n      ‫وبعــد اجللــد الســابق بخمســة عشــر يومــا يجلــد املذكــور ســبعني جلــدة‬\n      ‫دفعــة واحــدة لقــاء تعاطــي احلبــوب احملظــورة ‪ ،‬وبعــد تنفيــذ احلكــم‬\n      ‫عليــه مينــع مــن الســفر إلــى خــارج اململكــة ملــدة ثــاث ســنوات ‪ ،‬ومبــا‬\n      ‫تقــدم حكمــت ‪ ،‬وبعــرض احلكــم عليــه قــال إننــي مقتنــع بــه ‪ ،‬وقــال‬\n      ‫املدعــي العــام إننــي معتــرض علــى احلكــم واطلــب رفعــة إلــى محكمــة‬\n      ‫االســتئناف دون الئحــة اعتراضيــة ‪ ،‬وبــذا انتهــت يف الســاعة احلاديــة‬\n      ‫عشــرة والربــع ‪،‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/02‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n      ‫‪.......‬وتاريــخ بــدون املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪ ........ /‬برقــم ‪.........‬وتاريــخ ‪1434/2/3‬ه ــاخلاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ .......... /‬يف قضيــة (مخــدرات) علــى الصفــة‬\n      ‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                                ‫وســلم‪.‬‬\n\n\n\n‫‪411‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":408,"source_page_end":411,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0619bdacc7de1aebb8b46b9a9a2f6bfb8a5ef6390e4dac9765c62395df0f8c43","normalized_text_hash":"0e98dbd8851b69a4d547e680d1ece7ab9329345a29cec7831d605ebf1b977192","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p408-3428687"},{"id":"f79d592a-951c-5751-9b92-19c88f2a89e6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلشيش املخدر -مقاومة قوات الشرطة -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد والغرامة املالية واإلبعاد خارج الباد ومبصادرة املبالغ املضبوطة واجلوال والشريحة املستخدمة","document_number":"34186346","case_number":"3438316","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"مخدرات -ترويج احلشيش املخدر -مقاومة قوات الشرطة -إقرار املدعى عليه -عدم وجود سوابق قضائية -ثبوت إدانة املدعى عليه -تعزير بالسجن واجللد والغرامة املالية واإلبعاد خارج الباد ومبصادرة املبالغ املضبوطة واجلوال والشريحة املستخدمة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34186346 :‬تاريخه‪1434/4/13 :‬هـ‬\n                     ‫رقم الدعوى‪3438316 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34186346‬تاريخه‪1434/4/13 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬ترويــج احلشــيش املخــدر ‪ -‬مقاومــة قــوات الشــرطة ‪ -‬إقــرار‬\n‫املدعــى عليــه ‪ -‬عــدم وجــود ســوابق قضائيــة ‪ -‬ثبــوت إدانــة املدعــى‬\n‫عليــه ‪ -‬تعزيــر بالســجن واجللــد والغرامــة املاليــة واإلبعــاد خــارج‬\n‫البــاد ومبصــادرة املبالــغ املضبوطــة واجلــوال والشــريحة املســتخدمة‬\n                                                              ‫باجلرميــة‪.‬‬\n\n\n\n\n‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )1‬مــن املــادة (‪ )53‬والفقــرة (‪)1‬‬\n    ‫مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n‫الئحــة دعــوى ضــد املدعــى عليهمــا لقيامهمــا بترويــج املخــدرات‬\n‫(احلشــيش)‪ ،‬مت القبــض علــى املدعــى عليهمــا بعــد تســليمهما املصــدر‬\n‫الســري مــادة احلشــيش ‪ ،‬أقــرا بالترويــج وأثبــت التقريــر الكيميائــي‬\n‫الشــرعي احتــواء املــادة املضبوطــة علــى احلشــيش‪ ،‬وطلــب املدعــي‬\n‫ـاء علــى مــا ورد يف نصــوص نظــام‬\n                                  ‫العــام احلكــم علــى املدعــى عليهمــا بنـ ً‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة بالســجن واجللــد‪ ،‬والغرامــة‬\n‫ومصــادرة املبالــغ املضبوطــة معهمــا للترجيــح أنهــا مــن متحصــات‬\n‫الترويــج‪ ،‬ومصــادرة اجلــوال املضبــوط مــع األول الســتخدامه يف مــا‬\n\n                                                                                  ‫‪412‬‬\n\f      ‫نســب إليــه ‪ ،‬واإلبعــاد خــارج البــاد بعــد االنتهــاء مــن تنفيــذ عقوبتــه‬\n      ‫وعــدم الســماح لــه بالعــودة مــرة أخــرى ‪ ،‬احلكــم علــى الثانــي بعقوبــة‬\n      ‫تعزيريــة لقــاء مقاومتــه للفقــرة القابضــة ومحاولتــه للهــرب‪ ،‬حكمــت‬\n      ‫احملكمــة بثبــوت إدانــة املدعــى عليهمــا ببيــع احلشــيش املخــدر بقصــد‬\n      ‫االجتــار‪ ،‬وقــررت احملكمــة احلكــم علــى املدعــى عليهمــا بالســجن‬\n      ‫واجللــد والغرامــة ومصــادرة املبالــغ املضبوطــة معهما ومصــادرة اجلوال مع‬\n      ‫الشــريحة واإلبعــاد خــارج البــاد ‪ ،‬قــررا املدعــى عليهمــا عــدم قناعتهمــا‬\n          ‫باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ‪ .‬فلــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جــدة‪ /‬املســاعد برقــم ‪..........‬وتاريــخ‬\n      ‫‪ 1434/01/21‬هـ املقيدة باحملكمة برقم ‪ ..........‬وتاريخ ‪1434/01/20‬‬\n      ‫ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/03/03‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫ال‬\n       ‫‪09 : 45‬وفيهــا حضــر املدعــي العــام وقــدم الئحتــه مدعي ـ ًا علــى ك ً‬\n      ‫ـاء‬\n      ‫مــن ‪.......... .1 -:‬وتاريــخ ‪1433/10/1‬ه ـ ‪ .‬بتاريــخ ‪1433/9/26‬ه ـ وبنـ ً‬\n      ‫ملعلومــات وارده ملكافحــة املخــدرات مبحافظــة جــدة مــن الســجني‪/‬‬\n      ‫‪..........‬بوجــود شــخص حبشــي اجلنســية موجــود علــى هاتــف جــوال رقــم‬\n      ‫(‪ )..........‬يقــوم بترويــج احلشــيش املخــدر ‪ ،‬واســتعد بالشــراء منــه ‪،‬‬\n      ‫واتصــل الســجني علــى الهاتــف املشــار اليــه أعــاه وطلــب شــراء (‪ )6‬ســتة‬\n      ‫كيلــو مــن مــادة احلشــيش املخــدر ووافــق وطلــب تامــن املبلــغ وأفــاد بــان‬\n      ‫اجمالــي املبلــغ (‪ )67,200‬وأن قيمــة الكيلــو الواحــد (‪ )11200‬إحــدى‬\n\n‫‪413‬‬\n\f‫عشــر ألــف ومائتــان ريــال واحلضــور إليــه بشــارع ‪ . .....‬فتــم االنتقــال‪،‬‬\n‫وباملــكان والوقــت احملدديــن ورد اتصــال مــن املدعــى عليــه يفيــد بأنــه‬\n‫باملوقــع املتفــق عليــه ومت مالحظــة ســيارة مــن نــوع ‪ ...‬حتمــل لوحــة رقــم‬\n‫( ‪ )......‬بقيــادة األول الــذي نــزل منهــا واجتــه للمرافــق (املدعــى عليــه‬\n‫الثانــي ) وأخــذ منــه كيــس نايلــون كان يحملــه الثانــي بيــده وقــام األول‬\n‫بتســليم الكيــس للفــرد ممثــل دور املشــتري وضبــط بداخــل الكيــس‬\n‫(‪ )6‬ســتة بالطــات ســوداء اللــون مغلقــة مصنعيـ ًا بلــغ وزنهــا اإلجمالــي (‪)6‬‬\n‫ســتة كيلــو وهــي الكميــة املتفــق عليهــا ‪ .‬فتــم القبــض عليهمــا وضبــط‬\n‫الهاتــف اجلــوال املســتخدم يف التنســيق واحلامــل للرقــم املصنعــي (‪)..........‬‬\n‫بحــوزة املدعــى عليــه األول وضبــط معــه مبلــغ (‪ )1430‬ألــف وأربعمائــة‬\n‫وثالثــن ريــال وضبــط مــع الثانــي مبلــغ (‪ )445‬أربعمائــة وخمســة وأربعون‬\n‫ريــاالً‪ .‬وقــد حــاول الثانــي الهــرب وقــاوم الفرقــة القابضــة ‪ .‬وقــد أثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام ‪1433‬ه إيجابيــة‬\n‫العينــة مــن املــادة املضبوطــة واملرســلة للتحليــل ملــادة احلشــيش املخــدر‬\n‫واحتوائهــا علــى املــادة الفعالــة لــه واملدرجــة باجلــدول رقــم (‪ )1‬فئــة (أ)‬\n‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ .‬وباســتجواب‬\n‫األول ‪ ،.......... /‬أعتــرف بأنــه اتفــق مــع شــخص طلــب منــه هاتفي ـ ًا (‪)6‬‬\n‫ســتة كيلــو مــن مــادة احلشــيش املخــدر وأن تقابــل معــه وســلمه الكميــة‬\n‫املتفــق عليهــا واملضبوطــة ‪،‬وان قــام بالتوســط بينــه وبــن املشــتري أحــد‬\n‫األشــخاص( مت فصــل أوراق للبحــث عــن املدعــو ‪ ........... /‬باســتجواب‬\n‫الثانــي ‪ ،.......... /‬أفــاد بأنــه كان يرافــق األول ليوصلــه ملنــزل صديقـ ًا له‬\n‫‪ .‬وانتهــى التحقيــق الــى توجيــه االتهــام لــأول‪.......... /‬والثانــي ‪.......... /‬‬\n‫ببيــع (‪ )6000‬ســتة آالف جــرام مــن مــادة احلشــيش املخــدر عــن طريــق‬\n\n\n                                                                                        ‫‪414‬‬\n\f                           ‫البيــع بقصــد االجتــار وذلــك لألدلــة والقرائــن األتيــة‪-:‬‬\n      ‫‪ .1‬مــا ورد يف اعتــراف األول املــدون بدفتــر التحقيــق صفحــة رقــم ( ‪)5-1‬‬\n                                                                          ‫املرفق لفــة (‪).....‬‬\n         ‫‪.2‬ما ورد مبحضر الضبط صفحة رقم ( ‪ ) 13-12‬املرفق لفة رقم ‪.....‬‬\n                   ‫‪.3‬ما ورد بالتقرير الكيميائي املنوه عنه املرفق لفة ( ‪. ) ......‬‬\n      ‫وبالبحث عن ســوابقه لم يعثر له على ســوابق مســجلة عليه ‪ .‬وحيث إن‬\n      ‫مــا أقدمــا عليــه املذكوريــن وهمــا بكامــل أهليتهمــا املعتبــرة شــرع ًا مــن‬\n      ‫األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقـ ًا للمــادة الثالثــة مــن نظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n      ‫رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليهمــا‬\n                           ‫ومعاقبتهمــا بالعقوبــات األصليــة والتكميليــة التاليــة‪-:‬‬\n      ‫‪.1‬بالســجن واجللــد والغرامــة لقــاء مــا أســند إليهمــا اســتناد ًا للفقــرة‬\n      ‫(‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n                                                                              ‫املشــار إليــه ‪.‬‬\n      ‫‪ .2‬مصــادرة املبلــغ (‪ )1430‬ألــف وأربعمائــة وثالثــن ريــال املضبوطــة مــع‬\n      ‫األول ومصــادرة مبلــغ (‪ )445‬أربعمائــة وخمســة وأربعــون ريــا ًال املضبوطة‬\n      ‫مــع الثانــي للترجيــح أنهــا مــن مســتحصالت الترويــج و مصــادرة اجلــوال‬\n      ‫املضبــوط مــع األول والــذي يحمــل الرقــم املصنعــي رقــم (‪ )..........‬وذلــك‬\n      ‫الســتخدامه يف مــا نســب إليــه اســتناد ًا للفقرتــن (‪ )2 ،1‬مــن املــادة (‪)53‬‬\n                                           ‫مــن نظــام مكافحــة املخــدرات املشــار إليــه‬\n      ‫‪ .3‬إبعادهمــا خلــارج اململكــة بعــد االنتهــاء مــن تنفيــذ عقوبتهمــا وعــدم‬\n      ‫الســماح لهمــا بالعــودة إليهــا وفقـ ًا للفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن نظــام‬\n      ‫املخــدرات املشــار إليــه ‪ .‬كمــا أطلــب احلكــم علــى الثانــي لقــاء مقاومتــه‬\n\n\n‫‪415‬‬\n\f‫للفرقــة القابضــة ومحاولتــه الهــرب ‪ .‬هــذه دعــواي وأســألهما اجلــواب ‪.‬‬\n‫وبســؤال املدعــى عليهمــا اللذيــن يجيــدان التحــدث باللغــة العربيــة عــن‬\n‫الدعــوى اجابــا بقولهمــا امنــا ورد يف دعــوى املدعــي العــام علينــا هــو‬\n‫صحيــح حيــث قمنــا ببيــع ســتة االف جــرام مــن مــادة احلشــيش املخــدر‬\n‫عــن طريــق البيــع بقصــد االجتــار واضــاف املدعــى عليــه االول ‪..........‬‬\n‫ان املبلــغ املضبــوط معــي وهــو الــف واربعمائــة وثالثــن ريــال يعــود لــي‬\n‫اكتســبته مــن عمليــة الترويــج وان الهاتــف اجلــوال مــع شــريحته يعــود‬\n‫لــي والــذي اســتخدمته يف عمليــة الترويــج واضــاف املدعــى عليــه الثانــي‬\n‫‪.......... /‬قائــا ان املبلــغ املضبــوط معــي وهــو اربعمائــة وخمســة واربعــون‬\n‫ريــاال يعــود لــي اكتســبته مــن الترويــج وبالرجوع الــى اوراق املعاملة وجد‬\n‫التقريــر الكيميائــي املذكــور رقمــه ومصــدره اعــاه املتضمــن ايجابيــة‬\n‫العينــة ملــادة احلشــيش املخــدر كمــا لــم جنــد للمدعــى عليهمــا ســوابق‬\n‫مســجلة عليــه وحيــث احلــال مــا ذكــر مــن دعــوى العــام ضــد املذكــور‬\n‫ينفــي مــا ذكــر اعــاه ويطلــب مجازاتهمــا مــن ســجن وجلــد وغرامــة‬\n‫ومصــادرة املبالــغ املاليــة والهاتــف اجلــوال مــع شــريحته وابعادهمــا خــارج‬\n‫اململكــة وحيــث اجــاب املدعــى عليهمــا بصحــة هــذه الدعــوى مــن حيــث‬\n‫الترويــج بقصــد الكســب املــادي وان املبالــغ املضبوطــة معهمــا تعود لهما‬\n‫اكتســباها مــن عمليــة الترويــج وان الهاتــف اجلــوال يعــود للمدعــى عليــه‬\n‫االول ‪.......... /‬فبعــد االطــاع والتأمــل ولكــون االعتــراف ســيد االدلــة‬\n‫فقــد ثبــت لــدي ادانــة املدعــى عليهمــا ‪.......... /‬املذكــور و‪ .....‬املذكــور‬\n‫ببيــع ســته االف جــرام مــن مــادة احلشــيش املخــدر بقصــد االجتــار وان‬\n‫املبالــغ املضبوطــة معهمــا تعــودان لهمــا اكتســباها مــن عمليــة التريــج‬\n‫وان الهاتــف اجلــوال مــع شــريحته يعــود للمدعــى عليــه االول ‪.......... /‬‬\n\n\n                                                                                     ‫‪416‬‬\n\f      ‫والــذي اســتخدمه يف عمليــة الترويــج وحكمــت اوال ‪ :‬بتعزيــر املدعــى‬\n      ‫عليهمــا ‪.......... /‬و‪ ..........‬بالســجن مــدة قدرهــا اثنــا عشــر عامــا من تاريخ‬\n      ‫دخولهمــا الســجن وجلــد كل واحــد منهمــا الــف جلــدة علــى عشــرين‬\n      ‫دفعــة كل دفعــة خمســون جلــدة بــن الدفعــة والتــي خمســة عشــر يومــا‬\n      ‫وغرامــة ماليــة قدرهــا عشــرون الــف ريــال علــى كل واحــد منهمــا‬\n      ‫اســتنادا للمــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات لقــاء بيعهمــا ســتة‬\n      ‫االف جــرام مــن مــادة احلشــيش املخــدر بقصــد الكســب املــادي ثانيــا ‪:‬‬\n      ‫مصــادرة املبالــغ املاليــة املضبوطــة مــع املدعــى عليهمــا وايداعهــا بيــت‬\n      ‫املــال ومصــادرة الهاتــف اجلــوال مــع شــريحته والغائهــا ومنــع صرفهــا مــرة‬\n      ‫اخــرى لســوء اســتخدامها اســتنادا للمــادة (‪ )53‬مــن نفــس النظــام ثالثــا‬\n      ‫‪ :‬ابعــاد املدعــى عليــه الــى خــارج اململكــة بعــد انتهــاء محكوميتهمــا‬\n      ‫اســتنادا للمــادة (‪ )56‬مــن نفــس النظــام املشــار اليــه وبعرضــه عليهمــا‬\n      ‫قــرر املدعــى عليهمــا عــدم القناعــة وال يرغبــان تقــدمي الئحــة اعتراضيــة‬\n      ‫بذلــك ولــم يبــد املدعــي العــام اعتراضــا ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/03/03‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه‬\n      ‫احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــدة املســاعد‬\n      ‫رقــم(‪ )..........‬وتاريــخ (‪1434/4/23‬هــ) املرفــق بهــا القــرار رقــم(‪)..........‬‬\n      ‫وتاريــخ (‪1434/4/13‬هـ)الصــادر مــن فضيلــة الشــيخ‪........../‬القاضي‬\n      ‫باحملكمــة اجلزائيــة بجــدة ‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد ‪/‬‬\n      ‫‪ ..........‬ورفيقــه املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون باطنــه ‪، ،‬‬\n\n\n‫‪417‬‬\n\f‫وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n    ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                              ‫‪418‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":412,"source_page_end":418,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b5764b6858e5614920acbfd975ad12cc763367e4f6218a3f091546daf2ed5064","normalized_text_hash":"f0dd5eaa75b28d5f25bf9e6cc93beb2f6dc3aa6dca20cefee0f096e30579f17d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p412-34186346"},{"id":"0cb4ccb8-9705-5eff-a3ab-4f7b360af4d3","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والغاء الشريحة املستخدمة يف","document_number":"3435641","case_number":"3441372","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/11","year":"1434","subject":"مخدرات -ترويج احلبوب احملظورة -إقرار املدعى عليه -ثبوت إدانة املدعى عليه -تعزير املدعى عليه بالسجن واجللد والغرامة واملنع من السفر ومبصادرة اجلوال والغاء الشريحة املستخدمة يف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3435641 :‬تاريخه‪1434/2/11 :‬هـ‬\n                          ‫رقم الدعوى‪3441372:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 3435641‬تاريخه‪1434/2/11 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬ترويــج احلبــوب احملظــورة ‪ -‬إقــرار املدعــى عليــه ‪ -‬ثبــوت‬\n      ‫إدانــة املدعــى عليــه ‪ -‬تعزيــر املدعــى عليــه بالســجن واجللــد والغرامــة‬\n      ‫واملنــع مــن الســفر ومبصــادرة اجلــوال والغــاء الشــريحة املســتخدمة يف‬\n                                                                       ‫اجلرميــة‪.‬‬\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬املــادة (‪ )41‬والفقــرة (‪ )1‬مــن املــادة (‪)53‬‬\n      ‫والفقــرة (‪ )1‬مــن املــادة (‪ )56‬املــادة (‪ )60‬والفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن‬\n                                   ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n\n      ‫الئحــة دعــوى ضــد املدعــى عليــه لقيامــه بترويــج املخــدرات « حبــوب‬\n      ‫الكبتاجــون احملظــورة »‪ ،‬مت القبــض علــى املدعــى عليــه وبحوزتــه‬\n      ‫املبلــغ املرقــم‪ ،‬أقــر املدعــى عليــه بالترويــج‪ ،‬أثبــت التقريــر الكيميائــي‬\n      ‫الشــرعي احتــواء املــادة املضبوطــة علــى الكبتاجــون‪ ،‬طلــب املدعــي‬\n      ‫العــام احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة و منعــه مــن الســفر‬\n      ‫خــارج البــاد بعــد تنفيــذ العقوبــة ومصــادرة اجلــوال املســتخدم يف اجلرميــة‬\n      ‫وإلغــاء الشــريحة وعــدم صرفهــا لنفــس املســتخدم‪ .‬حكمــت احملكمــة‬\n      ‫بثبــوت إدانــة املدعــى عليــه بترويــج احلبــوب احملظــورة عــن طريــق البيــع‪،‬‬\n\n‫‪419‬‬\n\f‫فقــررت احملكمــة احلكــم علــى املدعــى عليــه بتعزيــره بالســجن ملــدة‬\n‫ســنة ونصــف مــن تاريــخ إيقافــه‪ ،‬وجلــده ثالثمائــة جلــدة مفرقــة علــى‬\n‫ســت دفعــات كل دفعــة خمســن جلــدة بــن كل دفعــة وأخــرى عشــرة‬\n‫أيــام‪ ،‬تغرميــه ثالثــة آالف ري ــال لقــاء تروجيــه خلمــس حبــات عــن طريــق‬\n‫البيــع‪ ،‬منعــه مــن الســفر خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة‬\n‫محكوميتــه‪ ،‬ومصــادرة اجلــوال املســتخدم يف ترويــج املخــدرات وإلغــاء‬\n‫الشــريحة املســجلة باســمه وعــدم صرفهــا لــه مــرة أخــرى‪ ،‬قــرر املدعــى‬\n‫عليــه قناعتــه باحلكــم‪ ،‬وجــرى تصديــق احلكــم مــن قبــل محكمــة‬\n                                                                        ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪..........‬وتاريــخ ‪1434/01/24‬‬\n‫ه ـ املقيــدة باحملكمــة برقــم ‪..........‬وتاريــخ ‪ 1434/01/24‬ه ـ ففــي يــوم‬\n‫اإلثنــن املوافــق‪ 1434/02/11‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام وادعــى علــى ‪..........‬ســعودي مبوجــب ســجل مدنــي رقــم (‪)..........‬‬\n‫جهــة اإلصــدار أحــوال تبــوك املهنــة ‪ ......‬متهــم يف بيــع املؤثــرات العقليــة‬\n‫ا يف دعــواه ‪ :‬إنــه يف يــوم األحــد املوافــق‬   ‫وال يوجــد عليــه ســوابق قائ ـ ً‬\n‫‪1433/12/26‬ه ـ ورد بــاغ مــن أحــد املصــادر بقيــام ‪ .....‬بترويــج احلبــوب‬\n‫املنبهــة احملظــورة ويحمــل جــوال رقــم (‪ )..........‬ذو الرقــم املصنعــي‬\n‫(‪ )..........‬فتــم االتصــال علــى جوالــه مــن قبــل املصــدر والتفــاوض معــه‬\n‫علــى شــراء خمــس حبــات مــن الكبتاجــون مببلــغ وقــدره (‪ )200‬ريــال‬\n                                                                                          ‫‪420‬‬\n\f      ‫وكانــت املكاملــة علــى مســمع مــن فرقــة مكافحــة املخــدرات بخميــس‬\n      ‫مشــيط ومت تكليــف أحــد أفــراد الفرقــة مبرافقــة املصــدر بعــد إعطائــه‬\n      ‫املبلــغ املرقــم ملقابلــة املصــدر والشــراء منــه ومتــت عمليــة الشــراء واســتالم‬\n      ‫خمــس حبــات بيضــاء اللــون حتمــل عالمــة الكبتاجــون املخــدر مــن قبــل‬\n      ‫الفــرد وأعطيــت اإلشــارة ملتابعتــه ومتــت متابعتــه والقبــض عليــه وبتفتيشــه‬\n      ‫عثــر معــه علــى املبلــغ املرقــم ولــم يعثــر معــه أو يف ســيارته علــى أي شــيء‬\n      ‫مــن املمنوعــات وهــي مــن نــوع ‪ .....‬وقــد مت مخاطبــة املخــدرات بخطابنــا‬\n      ‫رقــم (‪ )..........‬وتاريــخ ‪1433/12/28‬ه ـ بتســليمها إلــى صاحبهــا فتــم‬\n      ‫التحفــظ عليــه ومــا مت ضبطــه معــه وبســماع أقــوال املتهــم أقــر بأنــه قــام‬\n      ‫بترويــج خمــس حبــات مــن احلبــوب املنبهــة احملظــورة عــن طريــق البيــع‬\n      ‫وأنــه يقــوم بترويــج احلبــوب احملظــورة مــن الســابق وباســتجواب املتهــم‬\n      ‫أقــر بأنــه قــام بشــراء عشــر حبــات مــن احلبــوب املنبهــة احملظــورة وقــد‬\n      ‫اســتخدم منهــا خمــس حبــات وقــام ببيــع خمــس حبــات وأنــه يتعاطــى‬\n      ‫احلبــوب املنبهــة يف الســابق وأن اجلــوال املســتخدم يف عمليــة الترويــج رقــم‬\n      ‫(‪ )..........‬عائــد لــه وجهــاز ‪ ....‬وبتحليــل مــا مت ضبطــه ثبــت احتوائهــا علــى‬\n      ‫مــادة اإلمفيتامــن احملظــورة مبوجــب التقريــر الكيميائــي الشــرعي‬\n      ‫رقــم (‪ )..........‬لعــام ‪1433‬ه ـ الصــادر مــن مركــز مراقبــة الســموم‬\n      ‫والكيميــاء الطبيــة الشــرعية مبنطقــة عســير واإلمفيتامــن مــن‬\n      ‫املدرجــة باجلــدول الثانــي فئــة (ب) وهــو مــن املــواد املخــدرة امللحقــة بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وملــا أشــير إليــه أقــر توجيــه‬\n      ‫االتهــام‪ ..........‬بترويــج خمــس حبــات مــن احلبــوب املنبهــة احملظــورة عــن‬\n      ‫طريــق البيــع وترويجهــا يف الســابق وتعاطيــه مــن املضبــوط ويف الســابق‬\n      ‫واملجــرم مبوجــب املــادة (‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n\n\n‫‪421‬‬\n\f‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ /1 :‬إقــرار املتهــم ‪ /2‬أقــوال املتهــم ‪/3‬‬\n‫محضــر القبــض والتفتيــش ‪ /4‬التقريــر الكيميائــي وحيــث إن مــا‬\n‫أقــدم عليــه املذكــور فعــل محــرم ومجــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا‬\n‫مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وقــد أقــدم عليــه‬\n‫وهــو بكامــل أهليتــه املعتبــرة شــرع ًا لــذا أطلــب إثبــات مــا أســند إليــه‬\n                                                          ‫واحلكــم عليــه مبــا يلــي‪:‬‬\n‫‪ /1‬عقوبــة تعزيريــة وفق ـ ًا ملــا ورد يف املــادة (‪ )1/38‬مــن النظــام املشــار‬\n‫إليــه لقــاء مــا أســند إليــه وإعمــال املــادة (‪ )62‬بتطبيــق العقوبــة األشــد‬\n‫بحــق املتهــم لقــاء ترويجــه للحبــوب احملظــورة عــن طريــق البيــع ويف‬\n‫الســابق وتعاطيــه مــن املضبــوط يف الســابق ‪ /2‬منعــه مــن الســفر خــارج‬\n‫اململكــة بعــد تنفيــذ العقوبــة وفقـ ًا ملــا ورد يف املــادة (‪ )56‬الفقــرة األولــى‬\n‫مــن النظــام املشــار إليــه ‪ /3‬مصــادرة اجلــوال ذي الرقــم املصنعــي (‪)..........‬‬\n‫وفق ـ ًا ملــا ورد يف املــادة (‪ )53‬مــن النظــام املشــار إليــه وإلغــاء الشــريحة‬\n‫الهاتفيــة رقــم (‪ )..........‬اســتنادا لتعميــم صاحــب الســمو امللكــي وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذه دعــواي وبعــرض‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـاً‪ :‬مــا ذكــره املدعــي‬\n‫العــام مــن ترويجــي خمــس حبــات محظــورة عــن طريــق البيــع صحيــح‬\n‫وأنــا تائــب ونــادم هكــذا أجاب‪.‬هــذا وقــد جــرى االطــاع علــى محضــر‬\n‫القبــض والتفتيــش بتاريــخ ‪1433/12/26‬ه ـ واملتضمــن إنــه بنــاء علــى‬\n‫مــا وردنــا مــن أحــد املصــادر الســرية بــأن هنــاك شــخص يدعــى ‪......‬‬\n‫ويعمــل ‪ .....‬يقــوم بترويــج احلبــوب احملظــورة وقــد قــام املصــدر باالتصــال‬\n‫علــى املــروج ومت االتفــاق علــى شــراء خمــس حبــات محظــورة مــن نــوع‬\n\n\n                                                                                         ‫‪422‬‬\n\f      ‫كبتاجــون مببلــغ مائتــي ريــال وكانــت املكاملــة مبســمع مــن الفرقــة‬\n      ‫القابضــة ومت تكليــف أحــد األفــراد مبرافقــة املصــدر الســري ملقابلــة‬\n      ‫املــروج والشــراء منــه وقــد متــت املقابلــة ومت الشــراء منــه يف حــي ‪..........‬‬\n      ‫وبعدهــا مت القبــض علــى املدعــو ‪..........‬وبتفتيشــه شــخصيا عثــر علــى‬\n      ‫املبلــغ املرقــم ومســلم لــه مــن قبــل املصــدر الســري ولــم يعثــر معــه علــى‬\n      ‫أي ممنوعــات هــذا وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n      ‫برقــم ‪..........‬لعــام ‪1433‬ه ـ واملتضمــن ايجابيــة العينــة املضبوطــة ملــادة‬\n      ‫اإلمفيتامــن احملظــورة‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫وحيــث صــادق املدعــى عليــه علــى صحــة دعــوى املدعــي العــام وبنــاء‬\n      ‫علــى محضــر القبــض والتفتيــش والتقريــر الكيميائــي املشــار إليهمــا‬\n      ‫أعــاه ونظــرا ألن املدعــى عليــه يســتحق عقوبــة طبقــا للقواعــد الشــرعية‬\n      ‫ووفقــا للمادتــن ‪ 56،38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة ونظــرا خللــو صحيفــة املدعــى عليــه مــن الســوابق ونظــرا لصغــر‬\n      ‫ســنه وملــا قــرره مــن التوبــة والنــدم وملقتضــى املــادة ‪ 60‬مــن النظــام املشــار‬\n      ‫إليــه ولكلمــا تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليــه بحيازتــه خلمــس‬\n      ‫حبــات محظــورة مــن نــوع كبتاجــون لقصــد الترويــج عــن طريــق البيــع‬\n      ‫وحكمــت عليــه مبــا يلــي‪ :‬أوال ســجنه ســنة ونصــف مــن تاريــخ إيقافــه‬\n      ‫وجلــده ثالثمائــة جلــدة مفرقــة علــى ســت دفعــات كل دفعــة خمســن‬\n      ‫جلــدة بــن كل دفعــة وأخــرى عشــرة أيــام وتغرميــه ثالثــة األف ريــال لقــاء‬\n      ‫تروجيــه خلمــس حبــات عــن طريــق البيــع بنــاء علــى املادتــن ‪ 60،38‬مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬ثانيــا‪ :‬منعــه مــن الســفر‬\n      ‫خــارج البــاد ملــدة ســنتني تبــدأ بعــد انتهــاء فتــرة محكوميتــه بنــاء علــى‬\n      ‫املــادة ‪56‬مــن النظــام املشــار إليــه أعاله‪.‬ثالثــا‪ :‬مصــادر اجلــوال ذو الرقــم‬\n\n\n‫‪423‬‬\n\f‫املصنعي(‪ )..........‬بناء على املادة ‪ 53‬من النظام املشار إليه أعاله وإلغاء‬\n‫الشــريحة الهاتفيــة رقــم ‪..........‬بنــاء علــى تعميــم ســمو وزيــر الداخليــة رقم‬\n‫‪9798‬وتاريــخ ‪1428/2/10-9‬ه ـ ومبــا تقــدم حكمــت وبإعــان احلكــم‬\n‫قــرر املدعــي العــام االعتــراض بــدون الئحــة اعتراضيــة وقــرر املدعــى‬\n‫عليــه القناعــة وجــرى النطــق باحلكــم بتاريــخ ‪1434/2/11‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط املكلف‬\n‫الشــيخ ‪.......... /‬برقــم ‪ 34201834‬وتاريــخ ‪1434/2/12‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيل ــته برقــم ‪..........‬وتاريــخ ‪1434/2/11‬ه ــاخلاص‬\n‫بدعــوى املدعــي العــام ضـ ــد ‪.......... /‬يف قضيــة ( مخــدرات ) علــى الصفة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                              ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                         ‫‪424‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":419,"source_page_end":424,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"83ba0cd3c9274a90e4050b78fad6b27bdcec0b1660909854d45fbe127a3dd9f4","normalized_text_hash":"f29d9db0aa166387756d061bfa36f08520cdfe90a33103392abdf47d737f2011","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p419-3435641"},{"id":"9b980d73-377a-5283-8024-bba3a8c5c383","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -الوساطة يف ترويج الهيروين املخدر -الشروع يف ترويج الهيروين املخدر -التعزير للتهمة -التعزير بالسجن واجللد","document_number":"3457461","case_number":"3441813","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/08","year":"1434","subject":"مخدرات -الوساطة يف ترويج الهيروين املخدر -الشروع يف ترويج الهيروين املخدر -التعزير للتهمة -التعزير بالسجن واجللد","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3457461 :‬تاريخه ‪1434/03/08 :‬هـ‬\n                           ‫رقم الدعوى ‪3441813:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34218757‬تاريخه‪1434/5/21 :‬هـ‬\n\n\n       ‫مخــدرات ‪ -‬الوســاطة يف ترويــج الهيرويــن املخــدر ‪ -‬الشــروع يف ترويــج‬\n       ‫الهيرويــن املخــدر ‪ -‬التعزيــر للتهمــة ‪ -‬التعزيــر بالســجن واجللــد‬\n                                                                       ‫واإلبعــاد ‪.‬‬\n\n\n\n\n       ‫‪ -1‬تعميم معالي وزير العدل رقم ‪/13‬ت‪ 3406 /‬وتاريخ ‪1429/06/17‬هـ‪.‬‬\n                                  ‫‪ -2‬املادة (‪ )6/2‬من نظام وثايق السفر ‪.‬‬\n                              ‫‪ -3‬املادة (‪ )49‬من النظام األساسي للحكم ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام علــى املدعــى عليــه بالتوســط يف ترويــج الهيرويــن‬\n       ‫املخــدر والشــروع يف بيــع نصــف كيلــو مــن الهيرويــن املخــدر ‪ ،‬حيــث‬\n       ‫وردت معلومــات وجــود شــخص يقــوم بالتوســط والداللــة علــى الهرويــن‬\n       ‫املخــدر بكميــات كبيــرة جــد ًا ويعمــل ســائق أجــرة وأن معــه أشــخاص‬\n       ‫آخريــن وهــم عصابــة ومت متكــن املصــدر مــن االتصــال علــى املدعــى‬\n       ‫عليــه واالتفــاق علــى شــراء نصــف كيلــو مــن الهرويــن وكانــت املكاملــة‬\n       ‫علــى مســمع مــن رجــال الضبــط ‪ ،‬مت إعــداد اخلطــة الالزمــة وتزويــد‬\n       ‫املصــدر باملبلــغ املرقــم وتكليــف أحــد األفــراد مبرافقتــه ليقــوم بتمثيــل‬\n       ‫دور املشــتري مت تســليم املبلــغ للمدعــى عليــه ودخــل املدعــى عليــه داخــل‬\n\n‫‪425‬‬\n\f‫الســوق إلحضــار الكميــة فتــم القبــض عليــه خوفـ ًا مــن هروبــه وضيــاع‬\n‫املبلــغ احلكومــي وعثــر مــع املدعــى عليــه علــى املبلــغ احلكومــي املرقــم‬\n‫وأقــر أمــام الفرقــة القابضــة بالتوســط يف شــراء الهرويــن وطلــب املدعــى‬\n‫العــام إثبــات مــا أســند للمدعــى عليــه وأنكــر املدعــى عليــه ما نســب إليه‬\n‫ممــا حــرا باملدعــي العــام إلحضــار شــاهدين مــن مكافحــة املخــدرات‬\n‫ورصــدت الشــهادة وأنكــر املدعــى عليــه مــا جــاء يف الشــهادة ‪،‬بنــاء‬\n‫علــى ماســبق حكمــت احملكمــة علــى املدعــى عليــه وبتعزيــره بالســجن‬\n‫واجللــد واإلبعــاد‪ ،‬رد طلــب املدعــي العــام يف املطالبــة بالغرامــة و مصــادرة‬\n      ‫وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬     ‫اجلــوال وإلغــاء شــريحته ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة اخلبــر برقــم ‪ 3441813‬وتاريــخ ‪ 1434/01/24‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34204121‬وتاريــخ ‪1434/01/24‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1434/02/06‬ه ـ افتتحــت اجللســة الســاعة ‪15:11‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ...‬و حضــر حلضوره الســجني ‪ ...‬بنجالديشــي‬\n‫مبوجــب اإلقامــة رقــم (‪ )...‬بقولــه باالطــاع علــى محضر البــاغ والضبط‬\n‫والتفتيــش املعــد مــن قبــل رجــال الضبــط اجلنائــي مبكافحــة املخــدرات‬\n‫تبــن أنــه يف يــوم اجلمعــة املوافــق ‪1433/12/17‬ه ـ ورود معلومــات مــن‬\n‫مكتــب االتصــال يف دولــة ‪ ......‬الشــقيقة مفادهــا وجــود شــخص‬\n‫بنجالديشــي اجلنســية يقــوم بالتوســط والداللــة علــى الهرويــن املخــدر‬\n‫بكميات كبيرة جدا ويعمل ســائق تاكســي يف اخلبر ويقوم بالتوســط‬\n\n                                                                                     ‫‪426‬‬\n\f      ‫يف بيــع الهيرويــن املخــدر علــى ســيارته التاكســي ويدعــى‪... /‬‬\n      ‫البنجالديشــي أفــاد املصــدر بأنــه يحمــل رقــم جــوال (‪ )...‬وذكــر املصــدر‬\n      ‫أنهــم عصابــة مكونــه مــن الشــخص البنجالديشــي وأشــخاص مــن‬\n      ‫اجلنســية الباكســتانية وذكــر أنهــم حذريــن جــدا يف التعامــل وبنــاء علــى‬\n      ‫مــا ذكــر مت متكــن املصــدر مــن االتصــال علــى املدعــو‪ ... /‬علــى هاتفــه‬\n      ‫رقــم (‪ )...‬بعــد التحيــة والســام ذكــر املصــدر أنــه بالقــرب مــن جســر‬\n      ‫البحريــن وســأله املصــدر عــن توفــر النصــف كيلــو مــن الهيروين وجاوب‬\n      ‫قائــا موجــود بســعر ســتون ألــف ريــال وقــال البنجالديشــي تعــال إلــى‬\n      ‫مجمــع ‪ ...‬عنــد بوابــة ثمانيــة وانتهــت املكاملــة وكانــت علــى مســمع مــن‬\n      ‫رجــال الضبــط اجلنائــي باملكافحــة ومــن ثــم مت التوجــه إلــى مجمــع ‪...‬‬\n      ‫وعنــد الوصــول إليــه نــزل املصــدر وأحــد رجــال املكافحــة ليقــوم بتمثيــل‬\n      ‫دور املشــتري مــع املصــدر ويكــون شــاهدا علــى عمليــة االســتالم‬\n      ‫والتســليم ومت تســليم املصــدر املبلــغ احلكومــي املرقــم وبعــد حوالــي‬\n      ‫عشــر دقائــق اتصــل البنجالديشــي املدعــو‪ ... /‬علــى املصــدر وقــال أنــه يف‬\n      ‫الشــارع العــام فذهبــوا أمــا أنظــار الفرقــة باجتــاه املدعــو‪ ... /‬الــذي كان‬\n      ‫يركــب ســيارة تاكســي مــن نــوع ‪ ....‬بيضــاء اللــون وركبــوا معــه‬\n      ‫واجتهــوا باجتــاه إحــدى الشــوارع القريبــة مــن مجمــع ‪ ...‬ومــن خــال‬\n      ‫متابعــة الفرقــة القابضــة لــه اتضــح لهــم حــذره الشــديد وجــرى التفــاوض‬\n      ‫معــه علــى احلصــول علــى عينــة مــن الهرويــن املخــدر لتجربتــه ومــن ثــم‬\n      ‫تســليمه املبلــغ احلكومــي املرقــم واســتالم النصــف كيلــو مــن الهيرويــن‬\n      ‫املخــدر إال أنــه رفــض ذلــك وأصــر أن يتــم إعطائــه املبلــغ وقــدره ســتون‬\n      ‫ألفــا ثــم يذهــب مترجــا إلــى مجمــع ‪ ...‬حيــث ذكــر للمصــدر ومرافقــه‬\n      ‫أن هنــاك بداخــل املجمــع ‪ ...‬شــخص باكســتاني ســوف يحضــر لــه املبلــغ‬\n\n\n‫‪427‬‬\n\f‫ويســتلم منــه النصــف الكيلــو وهــو يحملــه بداخــل شــنطة وقــال أبقــوا يف‬\n‫الســيارة وأنــا ســوف أخــذ املبلــغ وأذهــب ملقابلــة الشــخص الباكســتاني‬\n‫يف خــال عشــر دقائــق ولكــن رفــض املصــدر ومرافقــه ذلــك إال بعــد‬\n‫مشــاهدة العينــة مــن الهيرويــن وبعــد ذلــك جــرى التفــاوض ملــدة ســاعتني‬\n‫مــع املصــدر ومرافقــه إال أن املدعــو‪ ...‬كان مصــر ًا علــى اســتالم املبلــغ‬\n‫بنفســه والذهــاب بــه وحــده ورفــض املصــدر ومرافقــه ذلــك ثــم أنــزل‬\n‫صاحــب التاكســي املدعــو ( ‪ ) ...‬املصــدر ومرافقــه مــن الســيارة لعــدم‬\n‫توصلهــم إلــى اتفــاق بذلــك وبعــد حوالــي ســاعة عــاود االتصــال املدعــو‪/‬‬\n‫‪ ...‬علــى املصــدر ومرافقــه وقــال لهــم لكــم عشــرة دقائــق ســوف نتقابــل‬\n‫يف مواقــف مجمــع ‪ ...‬عنــد بوابــة رقــم ( ‪ ) 1‬ســوف أخــذ املبلــغ وأنــزل‬\n‫لوحــدي لكــي أحضــر الكميــة املتفــق عليهــا مــن الهرويــن املخــدر‬\n‫فوافــق املصــدر ومرافقــه علــى ذلــك ومت التوجــه بالفرقــة علــى مجمــع ‪...‬‬\n‫عنــد البوابــة املتفــق عليهــا ومت توزيــع األفــراد بشــكل دقيــق وبعــد حوالي‬\n‫ربــع ســاعة وصــل املدعــو‪ ... /‬وقابــل املصــدر ومرافقــه وأخــذ منهــم املبلــغ‬\n‫احلكومــي املرقــم وقــدره ســتون ألــف ريــال ثــم ذكــر لهــم ســوف يحضــر‬\n‫الكميــة مــن داخــل املجمــع يف غضــون عشــر دقائــق وبعــد توجــه هــو‬\n‫لوحــده إلــى املجمــع وهــو حتــت أنظــار الفرقــة ودخــل إلــى بوابــة رقــم ( ‪1‬‬\n‫)ومــن ثــم أجتــه إلــى بوابــة رقــم( ‪ ) 2‬وأجتــه باجتــاه إحــدى ســائقي األجــرة‬\n‫وقــال ألحدهــم ممكــن توصلنــي وعنــد محاولــة ركوبــه مت القبــض‬\n‫عليــه مــن قبــل الفرقــة خوفــا مــن هروبــه وضيــاع املبلــغ احلكومــي املرقــم‬\n‫ومت العثــور علــى املبلــغ احلكومــي املرقــم يف جيبــه األميــن كامــا‬\n‫ومبناقشــته أعتــرف وأقــر أنــه تلقــى اتصــال أفــاد فيــه أن الباكســتاني‬\n‫الــذي يســلم لــه كميــة الهيرويــن طلــب منــه الركــوب يف أحــد ســيارات‬\n\n\n                                                                                       ‫‪428‬‬\n\f      ‫األجــرة ومبناقشــته كذلــك أقــر أنــه يقــوم بالتوســط يف شــراء الهرويــن‬\n      ‫املخــدر قبــل ذلــك عــدة مــرات وأنــه يتقاضــى مائــة ريــال علــى كل‬\n      ‫كبســولة مــن الهرويــن املخــدر وباســتجواب املدعــى عليــه أقــر بأنــه قــام‬\n      ‫باســتقبال املدعــو ‪(... /‬بحرينــي اجلنســية) أربــع مــرات وقــام باصطحابــه‬\n      ‫إلــى شــارع ‪ ......‬باخلبــر للداللــة علــى الهيرويــن املخــدر ويف كل مــرة‬\n      ‫يعطيــه البحرينــي مائــة ريــال ويقــوم بإرســال بطاقــة شــحن للباكســتاني‬\n      ‫مببلــغ (‪ )300‬ريــال وأنــه يقــوم باالتصــال علــى الباكســتاني ليرشــده‬\n      ‫علــى مــكان تواجــد الهيرويــن حيــث يقــوم برميــه علــى شــارع ‪ .......‬باخلبر‬\n      ‫بســوق ‪ ....‬ولــم يقابــل الباكســتاني وإمنــا معرفــه معــه عــن طريــق التلفــون‬\n      ‫ويقــوم بالتنســيق معــه علــى هاتفــه رقــم (‪ )...‬ويدعــى ( ‪ ) ...‬ويف يــوم‬\n      ‫القبــض عليــه اتصــل علــى الشــخص الباكســتاني وطلــب منــه نصــف‬\n      ‫كيلــو مــن الهيرويــن املخــدر واخبــره الباكســتاني بــأن قيمــة النصــف‬\n      ‫كيلــو هــي (‪)60‬ألــف ريــال وأخبــر الشــخص البحرينــي بذلــك وأســتلم‬\n      ‫املبلــغ املذكــور وقــام باالتفــاق مــع الشــخص املــروج الباكســتاني وطلــب‬\n      ‫منــه الباكســتاني املقابلــة يف مجمــع ‪ ...‬مــول ودخــل ومعــه املبلــغ ثــم‬\n      ‫اتصــل املــروج الباكســتاني وقــال لــه تعــال عنــد البوابــة رقــم (‪ )2‬وخــرج‬\n      ‫عنــد البوابــة ومت القبــض عليــه وانتهــى التحقيــق إلــى توجيــه االتهــام‪...‬‬\n      ‫بالتوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر والشــروع يف بيــع‬\n      ‫نصــف كيلــو مــن الهيرويــن املخــدر ‪.‬وذلــك لألدلــة والقرائــن التاليــة‬\n      ‫وأقــرار املدعــى عليــه واملرفــق علــى اللفــات رقــم (‪-2. )12.11.2‬‬\n      ‫محضــرا البــاغ والقبــض والتفتيــش املشــار إليه واملــدون على الصفحات‬\n      ‫رقــم (‪ )2‬و(‪ )12.11‬مــن ملــف ضبــط إجــراءات االســتدالل ‪ .‬وبالبحــث‬\n      ‫عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق جنائية مســجلة وحيث‬\n\n\n‫‪429‬‬\n\f‫إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرعاً‪-‬‬\n‫فعــل محــرم ومعاقــب عليــه شــرعا ونظام ـ ًا فإننــي أطلــب إثبــات إدانتــه‬\n‫مبــا أســند إليــه وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام‬\n‫مكافحــة املخــدرات‪ ،‬واحلكــم عليــه مبــا يلــي ‪ -1:‬بعقوبــة الســجن‬\n‫واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن‬\n‫النظــام مــع مراعــاة املــادة (‪ )62/1‬مــن النظــام مــع تشــديد العقوبــة عليــه‬\n‫وفقــا للمــادة (‪/2/38‬ج) مــن النظــام واســتنادا لتعميــم ســمو وزيــر‬\n‫الداخلية رقم ( ‪2/8346/4/5/1‬ش ) وتاريخ ‪1427/2/8‬هـ ‪ -2.‬إبعاده‬\n‫عــن البــاد إعمــاال ملقتضــى الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )56‬مــن‬\n‫النظــام ثانيــا ‪ :‬مصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه و الــذي‬\n‫مــن نــوع نوكيــا و يحمــل الرقم املصنعي رقــم (‪)35166305765845/2‬‬\n‫ورقــم االتصــال (‪ )...‬الســتخدامه يف الترويــج وفقــا للفقــرة رقــم (‪ )1‬مــن‬\n‫املــادة رقــم (‪ )53‬مــن النظــام ‪ ،‬مــع املطالبــة بإســقاط شــريحة الهاتــف‬\n‫النقــال وعــدم صرفهــا لنفــس املدعــى عليــه وفقــا لتعميــم ســمو وزيــر‬\n‫الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1429/2/10-9‬ه ـ هــذه دعــواي وبطلبــي‬\n‫مــن املدعــى عليــه اجلــواب أجــاب بواســطة مترجــم احملكمــة ‪ ...‬قائــا مــا‬\n‫ذكــره املدعــي العــام غيــر صحيــح والصحيــح أنــي قابلــت شــخص مــن‬\n‫اجلنســية البحرينيــة وركــب معــي واجتهــت معــه إلــى محــل ‪ ...‬بكورنيش‬\n‫اخلبــر وتوقفــت قليــا وكان يتحــدث بهاتفــه النقــال والنــي اعــرف‬\n‫العربيــة فهمــت انــه يتكلــم عــن شــراء هيرويــن مخــدر مببلــغ ســتني ألــف‬\n‫ريــال ثــم طلــب منــي االجتــاه إلــى مجمــع ‪ ...‬مــول بالدمــام فتوجهــت ثــم‬\n‫توقفــت قليــا ثــم طلــب منــي التوجــه إلــى البــرج ‪ ...‬علــى طريــق الدمــام‬\n‫اخلبــر الســريع وهنالــك قابلنــا شــخصني مــن اجلنســية البحرينيــة وحصــل‬\n\n\n                                                                                     ‫‪430‬‬\n\f      ‫بينهمــا خــاف ومشــادة وكان بيــد الشــخص الراكــب معــي علبــة‬\n      ‫بالســتيك بهــا مبلــغ ســتني ألــف ريــال وبعــد مشــادة بينــه وبــن زمالئــه قــام‬\n      ‫برمــي العلبــة التــي حتــوي املبلــغ بداخل الســيارة فقمــت باخذها وخرجت‬\n      ‫مــن الســيارة لرمــي املبلــغ وهنــا مت القبــض علــي مــن قبــل رجــال االمــن‬\n      ‫هكــذا أجــاب ورفعــت اجللســة الحضــار بينــة املدعــي العــام وهــم أعضــاء‬\n      ‫محضــر القبــض مــن افــراد مكافحــة املخــدرات بالدمــام ويف جلســة‬\n      ‫اخــرى حضــر املدعــي العــام وحضــر للشــهادة عضــو الفرقــة القابضــة ‪...‬‬\n      ‫ســجله ‪ ...‬وبســؤاله عمــا لديــه شــهد قائــا وردنــا إخباريــة عــن وجــود‬\n      ‫شــخص يقــوم بترويــج الهرويــن املخــدر بكميــات كبيــرة ويعمــل ســائق‬\n      ‫تاكســي فجــرى التنســيق واالعــداد لالطاحــة بــه فجــرى متكني املصدر‬\n      ‫مــن االتصــال بــه فاتفــق معــه علــى كميــة محــددة مببلــغ ســتني ألــف ريــال‬\n      ‫فتواعدنــا عنــد ‪ ...‬مــول عنــد البوابــه رقــم (‪ )8‬وملــا وصلنــا للموقــغ اتصلنــا‬\n      ‫بــه فقــال ســوف اصــل بعــد عشــر دقائــق ثــم بعــد عشــر دقائــق وصــل علــى‬\n      ‫ســيارة تاكســي والتقينــا معــه وركبنــا معــه يف الســيارة وتفاوضنــا معــه‬\n      ‫علــى ان تشــتري منــه كميــة حشــيش مخــدر فقــال البــد ان اخــذ مبلــغ‬\n      ‫الســتني ألــف ريــال ثــم ادخــل الســوق واحضــر كميــة الهيرويــن بعــد‬\n      ‫خمــس دقائــق فرفضنــا تســليمه املبلــغ اال بتســليم الهيرويــن فحاولنــا‬\n      ‫اقناعــه بقصــد االيقــاع بــه فطلبنــا منــه عينــة حتــى تعــرف جــودة الهيروين‬\n      ‫فرفضــت ذلــك اال باســتالم املبلــغ كامــل فقلنــا لــه نعطيــك جــزء مــن‬\n      ‫املبلــغ قــدره خمســة االف ريــال امــا كامــل املبلــغ فــا فرفــض فلــم نتفــق‬\n      ‫فافترقنــا بعدهــا بعشــر دقائــق اتصلنــا عليــه مــره ثانيــة وطلبنــا ان نلتقــي‬\n      ‫معــه وذلــك للتفــاوض مــرة اخــرى فاتفقنــا علــى االلتقــاء عنــد مجمــع ‪...‬‬\n      ‫يف املــكان احملــدد قابلنــاه وحاولنــا التفــاوض معــه ثــم ســلمناه كامــل‬\n\n\n‫‪431‬‬\n\f‫املبلــغ وقــدره ســتون ألــف ريــال ثــم قــال ســوف ادخــل الســوق واســتلم‬\n‫كميــة الهيرويــن وارجــع اليكــم مــرة ثانيــة ثــم دخــل الســوق وهنــا انتهــى‬\n‫دوري فاشــهد هلل تعالــى بالتفــاوض مــع املدعــى عليــه علــى شــراء هيروين‬\n‫مخــدر مببلــغ ســتني ألــف ريــال واســتالمه للمبلــغ هــذا مالــدي واشــهد بــه‬\n‫هــذا وحضــر للشــهادة وادائهــا ‪ ...‬ســجله ‪ ...‬وبســؤاله عمــا لديــه قــال‬\n‫اشــهد هلل تعالــى أنــي كنــت مــن ضمــن الفرقــة القابضــة وشــاهدت‬\n‫املدعــى عليــه يدخــل إلــى مجمــع ‪ ....‬مــن بوابــة بعــد ان تــرك الشــاهد‬\n‫األول يف ســيارته ويخــرج مــن بوابــة اخــرى وركــب ســيارة اجــرة فقمــت‬\n‫بالقبــض عليــه وبحيازتــه مبلــغ الســتني ألــف ريــال احلكومــي املرقــم هــذا‬\n‫مالــدي وبــه اشــهد وحضــر للشــهادة ‪ ...‬ســجله ‪ ...‬و‪...‬سجله‪....‬وبســؤالهما‬\n‫عمــا لديهمــا شــهد كل واحــد منهمــا منفــردا بعدالــة وثقــة الشــاهدين‬\n‫وعليــه جــرى التوقيــع ويف جلســة اخــرى حضــر املدعــي العــام ‪ ....‬و‬\n‫حضــر حلضــوره الســجني ‪ ...‬بنجالديشــي هــذا وبطلبــي مــن املدعــي العــام‬\n‫زيــادة بينــة قــال ليــس لــدي ســوى مــا يف أوراق املعاملــة هــذا وبتــاوة‬\n‫شــهادة الشــاهدين قــرر املدعــى عليــه قائــا بواســطة املترجــم املتعــاون‬\n‫‪ ........‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬و الــذي يقــوم‬\n‫بالترجمــة مــن اللغــة العربيــة إلــى اللغــة األرديــة و بالعكــس قائــا مــا‬\n‫ذكــره الشــاهد ‪ ...‬غيــر صحيــح جملــة و تفصيــا و الصحيــح هــو جوابي‬\n‫يف اجللســة الســابقة أمــا مــا شــهد بــه الشــاهد ‪ ...‬فالصحيــح منــه أنــه مت‬\n‫القبــض علــي و معــي املبلــغ احلكومــي املرقــم ألن الشــخص البحرينــي‬\n‫ألقــاه بســيارتي بداخــل علبــة فقمــت بأخذهــا وخرجــت مــن الســيارة‬\n‫لرمــي املبلــغ وهنــا مت القبــض و غيــر صحيــح أنــي دخلــت للســوق مــن‬\n‫بوابــة ثــم خرجــت مــن بوابــة أخــرى و ركبــت ســيارة ملوزيــن بــل مت القبض‬\n\n\n                                                                                    ‫‪432‬‬\n\f      ‫علــي مبجــرد خروجــي مــن ســيارة اللموزيــن التــي أقودهــا و غيــر صحيــح‬\n      ‫أنــي قمــت بالتوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر و وغيــر‬\n      ‫صحيــح أيضــا أنــي قمــت بالشــروع يف بيــع نصــف كيلــو مــن الهيرويــن‬\n      ‫املخــدر أمــا الشــهود فــا أعرفهــم وال أقــول فيهــم شــيئا هكــذا أجــاب‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث أنكــر املدعــى عليــه‬\n      ‫التوســط أربــع مــرات يف ترويــج الهيرويــن املخــدر والشــروع يف بيــع‬\n      ‫نصــف كيلــو مــن الهيرويــن املخــدر و حيــث أقــر بالقبــض عليــه وبيــده‬\n      ‫علبــه حتتــوي علــى مبلــغ ســتني ألــف ريــال و هــو املبلــغ احلكومــي املرقــم‬\n      ‫و حيــث أنــه دفــع أنــه كان يقصــد مــن ذلــك رمــي املبلــغ و حيــث أن هــذا‬\n      ‫الدفــع ينــايف شــهادة الشــاهدين حيــث شــهد الشــاهد األول ‪ ...‬بتســليمه‬\n      ‫كامــل املبلــغ وقــدره ســتون ألــف ريــال و شــهد الشــاهد الثانــي بالقبــض‬\n      ‫عليــه وبحيازتــه مبلــغ الســتني ألــف ريــال احلكومــي املرقــم و حيــث شــهد‬\n      ‫الشــاهد األول بالتفــاوض مــع املدعــى عليــه علــى بيــع هرويــن مببلــغ‬\n      ‫ســتني ألــف ريــال و حيــث ليــس للمدعــي العــام زيــادة بينــة لــذا فإنــه لــم‬\n      ‫يثبــت لــدي إدانــة املدعــى عليــه ‪ ...‬بالتوســط أربــع مــرات يف ترويــج‬\n      ‫الهيرويــن املخــدر والشــروع يف بيــع نصــف كيلــو مــن الهيرويــن املخــدر‬\n      ‫لعــدم كفايــة األدلــة و عــدم اكتمــال نصــاب الشــهادة و تتوجــه عليــه‬\n      ‫التهمــة يف الشــروع يف ترويــج الهرويــن املخــدر و اســتالم الثمــن وقــدره‬\n      ‫ســتون ألــف ريــال و ذلــك لشــهادة الشــاهد الواحــد يف التفــاوض مــع‬\n      ‫املدعــى عليــه يف بيــع هرويــن مخــدر مببلــغ ســتني ألــف ريــال و شــهادة‬\n      ‫شــاهد ثــانٍ يف القبــض علــى املدعــى عليــه و بحيازتــه مبلــغ الســتني ألــف‬\n      ‫ريــال و حكمــت عليــه باآلتــي ‪ ]1[ :‬تعزيــره علــى التهمــة يف الشــروع يف‬\n      ‫ترويــج الهرويــن املخــدر مــع مراعــاة التشــديد عليــه يف العقوبــة ملــا ورد يف‬\n\n\n‫‪433‬‬\n\f‫شــهادة الشــاهد مــن شــدة حــذره و رفضــه تســليم املخــدر إال بعــد اســتالم‬\n‫املبلــغ و لكبــر املبلــغ املقبــوض بحيازتــه و الــذي ســيؤدي بالتالــي إلــى‬\n‫كبــر كميــة الهرويــن املشــروع يف ترويجهــا ممــا يلــزم معــه التشــديد‬\n‫عليــه يف العقوبــة صيانــة للعبــاد والبــاد مــن شــر املفســدين يف األرض‬\n‫بنشــر هــذه اآلفــات التــي تضــر بديــن النــاس و دنياهــم وذلــك بســجنه‬\n‫أربــع ســنوات تبــدأ اعتبــارا مــن تاريــخ ســجنه و جلــده ثالثمائــة جلــدة‬\n‫مفرقــة علــى ســتة دفعــات متســاويات بــن كل دفعــة و األخــرى أســبوع‬\n‫[‪ ]2‬رد مطالبــة املدعــي العــام بتطبيــق عقوبــة الســجن واجللــد والغرامــة‬\n‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )38‬مــن النظــام لعــدم ثبــوت‬\n‫الترويــج [‪ ]3‬رد مطالبــة املدعــي العــام بإعمــال مقتضــى الفقــرة رقــم (‪)2‬‬\n‫مــن املــادة رقــم (‪ )56‬مــن النظــام لعــدم ثبــوت الترويــج [‪ ]4‬رد مطالبــة‬\n‫املدعــي العــام مبصــادرة الهاتــف اجلــوال العائــد للمدعــى عليــه ورد‬\n‫املطالبــة بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس املدعــى‬\n‫عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n‫‪1429/2/10-9‬هـ لعدم ثبوت الترويج [‪ ]5‬و حيث أن للقاضي احلكم‬\n‫باإلبعــاد و املصــادرة ولــو لــم تثبــت اإلدانــة وذلــك بنــاء على قواعــد التعزير‬\n‫العامــة حيــث نــص تعميــم معالــي وزيــر العــدل رقــم ‪/13‬ت‪ 3406 /‬بتاريخ‬\n‫‪1429 /6/17‬ه ـ ونــص احلاجــة منــه ‪ :‬أمــا يف حالــة عــدم ثبــوت اإلدانــة‬\n‫وتوجــه الشــبهة فــا مينــع مــن الســفر وفقـ ًا للمــادة (‪ )56‬املشــار إليهــا وإذا‬\n‫رأى ناظــر القضيــة أن يعــزر مــن توجهــت إليــه الشــبهة باملنــع مــن الســفر‬\n‫فلــه ذلــك ألنــه داخــل ضمــن صالحيــة أصحــاب الفضيلــة وفــق املــادة‬\n‫(‪ )2/6‬مــن نظــام الوثائــق الســفرية بالنســبة للمواطــن الســعودي‬\n‫ا باملــادة (‪ )49‬مــن النظــام‬  ‫وتعليمــات اإلبعــاد بالنســبة لألجنبــي عم ـ ً‬\n\n\n                                                                                        ‫‪434‬‬\n\f      ‫األساســي للحكــم ل ــذا نرغــب إليكــم االطــاع واعتمــاد كــون احلكم‬\n      ‫باملنــع مــن الســفر ال يكــون وفق ـ ًا للمــادة (‪ )56‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة إال يف حــال ثبــوت التهمــة واإلدانــة وفقـ ًا ملــا‬\n      ‫نــص عليــه النظــام مــن أوصــاف جرميــة و يف حــال عــدم ثبــوت اإلدانــة‬\n      ‫ورأى فضيلــة ناظــر القضيــة ‪ -‬لقــوة التهمــة ‪ -‬التعزيــر باملنــع مــن الســفر‬\n      ‫فــإن لــه ذلــك اســتناد ًا علــى املبــادئ العامــة يف التعزيــر لــذا فقــد حكمــت‬\n      ‫بإبعــاد املدعــى عليــه مــن البــاد و عــدم متكينــه مــن دخولهــا مــرة ثانيــة‬\n      ‫اتقــاء لشــره كمــا حكمــت مبصــادرة اجلــوال العائــد للمدعــى عليــه و‬\n      ‫إســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس املدعــى عليــه‬\n      ‫وذلــك بنــاء علــى املصلحــة العامــة حتــى ال يتم اســتغالل الرقــم يف عمليات‬\n      ‫تنســيق و تفــاوض أخــرى مــن قبــل املدعــى عليــه أو غيــره و بعرض احلكم‬\n      ‫عليهمــا قــرر املدعــي العــام املعارضــة و االكتفــاء بالئحــة الدعــوى عــن‬\n      ‫تقــدمي معارضــة وقــرر املدعــى عليــه القناعــة بــه وصلــى اهلل علــى نبينــا‬\n                                  ‫محمد و آله وصحبه وسلم حرر يف ‪1434 /2/27‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة اخلبــر برقم ‪34204121‬‬\n      ‫وتاريــخ ‪1434/4/14‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/959615‬‬\n      ‫وتاريــخ ‪1434/4/20‬ه ـ املرفــق بهاالقــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ‪ ... /‬املســجل برقــم ‪ 3457461‬وتاريــخ ‪1434/3/8‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ .../‬بنجالديشــي اجلنســية يف قضيــة‬\n      ‫مخــدرات وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ؛ وبدراســةالقرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة‬\n\n\n‫‪435‬‬\n\f‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                         ‫وســلم حــرر يف ‪1434 /5/18‬ه ـ ‪.‬‬\n\n\n\n\n                                                                               ‫‪436‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"acb567ff-c462-5140-add4-dd12fad14494","source_page_start":425,"source_page_end":436,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38dbd0fe4274288af2dfd1a32bd944f08c6398b23b416fc4a101cc85a66c4a88","normalized_text_hash":"ef2a0dab0b47b6f3fc80933db9a9e4fe51f11c9631a135e58f40218eea65b83d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v17-p425-3457461"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
